INSERT INTO `products` (`id`, `name`, `sku`, `description`, `price`, `weight`, `category_id`, `active`, `image`, `created_at`) VALUES
(1, 'Czekolada mleczna Wedel 100g', 'SLO-00001', '## Czekolada mleczna Wedel 100g\n\nOdkryj niezapomniane połączenie smaku i tradycji z autentyczną czekoladą mleczną Wedel! Ta słynna polska czekolada od ponad 150 lat cieszy się zaufaniem miłośników słodkości na całym świecie. Wedel to gwarancja najwyższej jakości, doskonałego smaku i przyjemności z każdego gryzienia. Kompaktowe opakowanie 100g to idealny rozmiar dla osoby szukającej chwili relaksu, a także doskonały prezent dla bliskich.\n\nCzekolada mleczna Wedel przyciąga niepowtarzalnym, delikatnym smakiem, który harmonijnie łączy słodycz kakaowego masła z mleczną kremowością. Każda porcja rozpuszcza się na języku, pozostawiając przyjemne wspomnienie intensywnego, ale nie przytłaczającego smaku. Powstała z starannie wybranych składników i optymalnie dobranym udziałem kakao, dzięki czemu stanowi doskonałe uzupełnienie codziennych chwil lub czasu spędzanego w towarzystwie bliskich.\n\nTa czekolada to więcej niż słodycz – to kawałek polskiej tradycji, która wypracowała sobie sławę na arenie międzynarodowej. Idealna zarówno do osobistego użytku, jako dodatek do kawy czy herbaty, jak i do podziału się nią z przyjaciółmi. Zawsze można na nią liczyć, gdy potrzebujesz momentu czystej przyjemności i zadowolenia smakowego.\n\n### Kluczowe cechy\n\n- **100% autentyczna czekolada Wedel** – polska marka z ponad 150-letnią tradycją\n- **Idelna ilość** – opakowanie 100g to doskonały rozmiar na każdą okazję\n- **Wysokiej jakości składniki** – kakao i mleko dbale dobrane, aby zagwarantować wspaniały smak\n- **Delikatna konsystencja** – rozpuszcza się na języku, zapewniając maksymalną przyjemność\n- **Wszechstronne zastosowanie** – idealna na każdą porę dnia, do kawy, do paczki\n- **Godna zaufania marka** – wybór ponad generacji Polaków na całym świecie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Czekolada mleczna Wedel |\n| Waga | 100g |\n| Typ | Czekolada mleczna |\n| Marka | Wedel |\n| Cena | 27,45 PLN |\n\n---\n\n**Nie zwlekaj – spraw sobie dziś przyjemność!** Czekolada mleczna Wedel 100g to inwestycja w chwilę czystej radości i smakowego zadowolenia. Zamów teraz i ciesz się niepowtarzalnym smakiem, który da Ci energię i uśmiech na twarzy. Jedynie 27,45 PLN za prawdziwą polską czekoladową klasykę! 🍫', '27.45', '0.34', 1, 1, 'czekolada-mleczna-wedel-100g', '2024-05-21 00:00:00'),
(2, 'Krówki Milanówek 300g', 'SLO-00002', '## Krówki Milanówek 300g – Tradycyjne polskie słodycze najwyższej jakości\n\nKrówki Milanówek to prawdziwa legenda polskich słodyczy, która od pokoleń cieszy się niesłabnącą popularnością wśród miłośników tradycyjnych smakołyków. Ten doskonale wyważony karmel o delikatnej konsystencji rozpływa się na języku, pozostawiając po sobie niepowtarzalny, słodki smak, który przenosi nas w czasy dzieciństwa i domowych przyjemnościach. Opakowanie 300g to idealna porcja dla całej rodziny – zarówno do spożycia w gronie domowników, jak i jako świetny prezent dla przyjaciół czy bliskich osób.\n\nKażda krówka to wynik starannie dobranej receptury i tradycyjnych metod produkcji, gwarantujących niezrównaną jakość i autentycz\n\nny smak. Miękka, kremowa konsystencja sprawia, że karmel łatwo się żuje, a jego bogata słodycz doskonale komponuje się z kawą, herbatą czy mlekiem. Produkt nie zawiera sztucznych barwników ani konserwantów – to czysta, naturalna przyjemność w każdym kęsie. Słodycze te stanowią idealny wybór dla osób szukających autentycznych, polskich smaków o nieprzetarganej reputacji.\n\nNiezależnie od okazji – czy to zwykły dzień pracy, wieczór filmowy, czy specjalne świętowanie – Krówki Milanówek nigdy się nie sprawdzają. Ich wszechstronna przyswajalność i uniwersalny smak czynią je ulubionym wyborem w polski\n\nch domach od dziesięcioleci. To nie tylko słodycz, to kusa klejnot polskiej tradycji cukierniczej, który warto mieć zawsze pod ręką.\n\n### Kluczowe cechy\n\n- 🍬 **Tradycyjna polska receptura** – autentyczne krówki przygotowane metodami sprawdzonymi przez pokolenia\n- 🎁 **Idealne opakowanie 300g** – doskonała ilość dla rodziny lub jako prezent\n- ✨ **Delikatna, kremowa konsystencja** – karmel rozpływa się na języku bez wysiłku\n- 🚫 **Bez sztucznych dodatków** – brak sztucznych barwników i konserwantów\n- 👨‍👩‍👧‍👦 **Dla całej rodziny** – smak zapamiętany z dzieciństwa, lubią go dorośli i najmłodsi\n- 💪 **Długa trwałość** – świeży smak zachowany dzięki profesjonalnemu opakowaniu\n- ☕ **Uniwersalny towarzysz** – doskonale komponuje się z napojami i stanowi idealną przekąskę\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Krówki Milanówek |\n| **Masa netto** | 300g |\n| **Cena** | 43,98 PLN |\n| **Typ produktu** | Karmel tradycyjny |\n| **Sposób przechowywania** | W suchym, chłodnym miejscu |\n\n---\n\n**Zamów teraz Krówki Milanówek 300g i poczuj smak tradycji!** 🍬\n\nJeśli kochasz oryginalne, polskie słodycze, które nie zawodzą ani przez chwilę, to ten produkt jest dla Ciebie. Krówki Milanówek to inwestycja w przyjemność i nostalgie – śpiewający tort wymuszający uśmiech na każdej twarzy. W cenie 43,98 PLN otrzymujesz autentyczną polską klasykę, którą będziesz chciał mieć zawsze w domu. Nie czekaj – dodaj do koszyka i doświadcz magii tego niezapomnianego smaku!', '43.98', '0.08', 1, 1, 'krowki-milanowek-300g', '2023-06-23 00:00:00'),
(3, 'Ptasie Mleczko Waniliowe', 'SLO-00003', '## Ptasie Mleczko Waniliowe\n\nPtasie Mleczko Waniliowe to kultowa słodycz, która od pokoleń podbiła serca Polaków! Ten delikatny nugat pokryty mleczną czekoladą to idealna przekąska do kawy, herbaty lub jako dodatek do deserów. Każde opakowanie zawiera porcje słodyczy, które zachwycą Cię wyrazistym smakiem wanilii i rozpuszczającą się w ustach teksturą. To nie tylko przysmakiem, ale także nostalgia i wspomnienia z dzieciństwa w jednym kęsie.\n\nCharakterystyczne białe warstwy nugatowe przeplatane akcentami słodkiej czekolady tworzą niepowtarzalny smak, który odróżnia Ptasie Mleczko od innych słodyczy dostępnych na rynku. Naturalny aromat wanilii sprawia, że każde zagryzienie to czysty naturalny przyjemności dla podniebienia. Produktu można delektować się w samotności lub dzielić z rodziną i przyjaciółmi — zawsze będzie to strzałem w dziesiątkę!\n\nPtasie Mleczko Waniliowe to produkt z bogatą tradycją, wykonywany według sprawdzonych receptur. Idealne jako prezent dla bliskich, słodki upominek do pracy czy jedynie dla siebie jako chwila przyjemności w ciągu dnia. Dzięki wygodnemu opakowaniu możesz zabrać tę słodycz wszędzie — do szkoły, biura, na wycieczkę. Nie przegap okazji na zakup jednej z najbardziej charakterystycznych polskich słodyczy!\n\n### Kluczowe cechy\n\n- ✨ **Klasyczna receptura** — sprawdzony smak, który kochają pokolenia\n- 🍫 **Mleczna czekolada** — delikatnie słodka obudowa chroniąca nuczątkę\n- 🌾 **Naturalny aromat wanilii** — wyrazisty, nienakładający się smak\n- 🤲 **Rozpuszczająca się tekstura** — miękkie, łatwe do jedzenia warstwy\n- 📦 **Wygodne opakowanie** — łatwo nosić i przechowywać\n- 🎁 **Idealny prezent** — klasyka, którą wszyscy polubią\n- ⏰ **Długa trwałość** — świeżość gwarantowana do końca okresu ważności\n\n### Specyfikacja\n\n| Cecha | Wartość |\n|-------|---------|\n| **Nazwa produktu** | Ptasie Mleczko Waniliowe |\n| **Cena** | 24,78 PLN |\n| **Główny smak** | Wanilia |\n| **Pokrycie** | Mleczna czekolada |\n| **Stan** | Nowy |\n\n---\n\n**Czy czekasz na coś więcej?** Ptasie Mleczko Waniliowe to inwestycja w chwilę szczęścia za zaledwie 24,78 PLN! Dodaj do koszyka i ciesz się smakami, które poznajesz od dzieciństwa. Szybka dostawa, najwyższa jakość i gwarancja zadowolenia — to wszystko czeka na Ciebie. **Zamów teraz i poczuj magię klasyki!** 🍫✨', '24.78', '0.37', 1, 1, 'ptasie-mleczko-waniliowe', '2024-03-05 00:00:00'),
(4, 'Michałki Zamkowe 250g', 'SLO-00004', '## Michałki Zamkowe 250g\n\nMichałki Zamkowe to tradycyjne polskie słodycze, które od pokoleń cieszą się niezmienną popularnością wśród miłośników pysznych przysmaków. Ta elegancka paczka zawiera 250g wyśmienicie smakujących cukierków o charakterystycznym kształcie i bogatej historii. Każdy Michałek to idealne połączenie kremowego nadzienia z cienką, pękającą pod zębami warstewką czekolady, które gwarantuje niezapomniane przeżycie smakowe.\n\nProductom tym przyświeca hasło: jakość, tradycja i autentyczność. Michałki Zamkowe są przygotowywane z dbałością o każdy szczegół, z wykorzystaniem sprawdzonych receptur i najlepszych składników. Ich niepowtarzalny smak zdobył serca nie tylko Polaków, ale również zagranicznych fanów słodyczy. Paczka o wadze 250g to idealny rozmiar zarówno dla osobistej przyjemności, jak i na mały prezent dla kogoś bliskiego.\n\nNiezależnie od okazji – czy to filmowy wieczór, przerwę w pracy, czy słodkie słabostki – Michałki Zamkowe sprawdzą się zawsze. Doskonale smakują jako dodatek do kawy czy herbaty, a ich elegancka opakowanie czyni je godnym prezentem dla każdego miłośnika słodyczy. Sięgaj po porcję tradycji i wspaniale smakujących chwil z Michałkami Zamkowymi!\n\n### Kluczowe cechy\n\n- **Tradycyjna polska receptura** – autentyczne cukierki z ponad dziesięcioleciami historii\n- **Kremowe nadzienie** – delikatne, rozpływające się w ustach dopełnienie z najlepszych składników\n- **Pokryta czekoladą** – cienka, pękająca warstwa najwyższej jakości czekolady\n- **Porcja 250g** – idealna ilość do codziennego stosowania lub jako prezent\n- **Bez sztucznych barwników** – naturalne składniki bez zbędnych dodatków\n- **Wszechstronna dostępność** – idealne do kawy, herbaty lub jako słodka przekąska\n- **Zmysłowy smak** – gwarantowane zadowolenie dla każdego podniebienia\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|---|---|\n| Nazwa produktu | Michałki Zamkowe |\n| Waga netto | 250g |\n| Cena | 6.38 PLN |\n| Typ produktu | Cukierki/Słodycze |\n| Główny składnik | Czekolada, nadzienie kremowe |\n\n---\n\n**Zamów teraz i ciesz się niespotykańskim smakiem Michałków Zamkowych!** Za zaledwie 6.38 PLN otrzymujesz ponad ćwierć kilograma najwyższej jakości słodyczy, które przeniosą Cię w klimat tradycji i doskonałego smaku. Nie czekaj – dodaj do koszyka teraz i odkryj, dlaczego Michałki Zamkowe to perła polskiego cukiernictwa! 🍫', '6.38', '0.43', 1, 1, 'michalki-zamkowe-250g', '2024-05-13 00:00:00'),
(5, 'Żelki Haribo Złote Misie', 'SLO-00005', '## Żelki Haribo Złote Misie\n\nPrzywołaj wspomnienia dzieciństwa i pozwól sobie na słodką chwilę relaksu razem z kultowymi **Żelkami Haribo Złote Misie**! To nie zwykły cukierek – to ikoniczna słodycz, która od ponad 100 lat cieszy miliony ludzi na całym świecie. Każdy mały misiaczek to idealne połączenie puszystej tekstury i intensywnego smaku owocowego, który rozpływa się w ustach i przenosi Cię do krainy słodkich wrażeń. Te kolorowe niedźwiadki to gwarancja autentycznego smaku i najwyższej jakości, na którą Haribo zawsze stawia.\n\nŻelki Haribo to doskonały wybór dla każdego, kto chce wprowadzić odrobinę radości do codzienności. Niezależnie od tego, czy szukasz ulubionej przekąski do filmowego wieczoru, prezentu dla bliskiej osoby, czy po prostu chcesz sobie sprawić przyjemność – te misie nie zawiodą! Wyjątkowa kombinacja naturalnych aromatów i wyrazistych smaków sprawia, że nie porafisz się od nich oderwać. Każde opakowanie to gwarancja świeżości i autentycznego smaku, jaki znasz od lat.\n\nHaribo od dekad słynie z najwyższej jakości produktów, które zachwycają swoje funkcjonalnym smakiem i czysto artystycznym wyglądem. Żelki Złote Misie to szkoła doskonałości w świecie słodyczy – każda sztuka jest starannie formowana i pazernościowo owinięta, aby dotrzeć do Ciebie w idealnym stanie. To idealny dodatek do szkolnego pudełka śniadaniowego, biurowego biurka czy rodzinnej szafki z przekąskami. Smak, który się nie zmienia, tradycja, którą warto cenić.\n\n### Kluczowe cechy\n\n- 🐻 **Ikoniczny smak**: Autentyczny, aromatyczny profil smakowy Haribo, który kochają dzieci i dorośli\n- 🌈 **Różnokolorowe misie**: Żelki w pięciu pięknych kolorach odpowiadających różnym smakom owocowym\n- 🎉 **Idealna tekstura**: Puszysty, gumowaty żel, który ma przyjemny opór zębach i rozpływa się w ustach\n- ✨ **Naturalne aromaty**: Żelki zawierają naturalne aromaty owocowe, nie sztuczne substytuty\n- 👪 **Dla całej rodziny**: Niezastąpione dla każdego wieku – od najmłodszych do seniorów\n- 🏆 **Marka światowa**: Trusted brand z ponad 100-letnim doświadczeniem w produkcji słodyczy\n- 📦 **Świeże i starannie zapakowane**: Każde opakowanie gwarantuje świeżość i doskonałość produktu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | Haribo |\n| Nazwa produktu | Żelki Złote Misie |\n| Smak | Owocowy mix (owoce leśne, cytryna, pomarańcza i inne) |\n| Cena | 39,07 PLN |\n| Zastosowanie | Słodka przekąska, prezent, dodatek do deserów |\n\n---\n\n**Nie czekaj dłużej – dodaj Żelki Haribo Złote Misie do koszyka już dziś!** Smakowały Ci jako dziecku, będą smakować Tobie i Twojej rodzinie teraz. Za niecałe 40 złotych zyskujesz nie tylko słodycz, ale cząstkę magii, którą niesie ze sobą Haribo. Niepowtarzalny smak, najwyższa jakość, zadowolenie gwarantowane – to wszystko czeka Cię w jednym opakowaniu. Zamawiaj z ufnością i ciesz się każdym gumowatym misiaczkiem! 🐻✨', '39.07', '0.25', 1, 1, 'zelki-haribo-zlote-misie', '2023-09-21 00:00:00'),
(6, 'Bombonierka Merci 250g', 'SLO-00006', '## 🎁 Bombonierka Merci 250g - Zestaw Belgijskich Czekoladek\n\nBombonierka Merci 250g to idealna propozycja dla osób, które cenią sobie smak i elegancję. Ten wyjątkowy zestaw belgijskich czekoladek zawiera starannie wybrane odmianki, od delikatnych pralin mlecznych, przez czekoladę ciemną, aż po słodkie niespodziанki. Każda czekoladka to mała sztuka kulinarna, przygotowana z najwyższej jakości składników, które gwarantują niezapomniany moment przyjemności dla podniebienia.\n\nPrestiżowa marka Merci od lat utożsamiana jest z luksusem i wysoką jakością. Bombonierka o wadze 250g stanowi doskonały prezent na każdą okazję – zarówno dla bliskich osób, jak i dla siebie samego. Piękne, eleganckie opakowanie sprawia, że prezent już na pierwszy rzut oka robi wrażenie i wyraża szacunek obdarowanej osobie. Czekoladki Merci to symbol wdzięczności i dobrego smaku, idealnie wpasowujące się w polskie tradycje podarowania słodkości.\n\nCzy planujesz prezent do biura, szkoły, czy może po prostu chcesz się siebie rozpieścić? Bombonierka Merci 250g to rozwiązanie, które nigdy zawiedzie. Różnorodność smaków i tekstur zapewnia, że każdy znajdzie coś dla siebie. Przechowywane w chłodnym miejscu, czekoladki zachowują swoją świeżość i aromat przez długi czas, a ich konsumpcja zawsze będzie momentem radości i smakowych wrażeń.\n\n### 🌟 Kluczowe cechy\n\n- **Autentyczne belgijskie czekoladki** – gwarantowana wysokość jakości i origen marki Merci\n- **Różnorodne smaki** – mieszanina czekolady mlecznej, ciemnej i z dodatkami, zapewniająca bogatą paletę smaków\n- **Eleganckie opakowanie** – idealny prezent do ręki, gotowy do podarowania bez dodatkowego pakowania\n- **Waga 250g** – praktyczna porcja, idealna dla 1-3 osób lub jako uzupełnienie prezentu\n- **Długi termin przydatności** – dzięki konserwancom i cukrom przechowuje się przez wiele tygodni w chłodnym miejscu\n- **Bezpieczne dla alergików** – pakowanie zawiera informacje o alergenach, dostępne na opakowaniu\n- **Wygodny transport** – kompaktowy rozmiar ułatwia przewiezienie prezentu bez ryzyka uszkodzenia\n\n### 📋 Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Bombonierka Merci 250g |\n| **Waga** | 250 gramów |\n| **Marka** | Merci (Niemcy) |\n| **Cena** | 33,76 PLN |\n| **Typ produktu** | Zestaw czekoladek/pralin |\n\n---\n\n**Nie czekaj – zamawiaj teraz i sprawdź, dlaczego Merci to symbol doskonałości wśród czekoladek!** 🍫✨ Bombonierka Merci 250g czeka na Ciebie w atrakcyjnej cenie 33,76 PLN. Gwarantowana świeżość, niezaprzeczalny smak i elegancja w każdym kęsie. Twoi bliscy (lub Ty sam!) na pewno będą zachwyceni. Dodaj do koszyka i poczuj różnicę jakości! 💝', '33.76', '0.11', 1, 1, 'bombonierka-merci-250g', '2023-11-13 00:00:00'),
(7, 'Cukierki Kasztanki 400g', 'SLO-00007', '## Cukierki Kasztanki 400g\n\nCukierki Kasztanki to prawdziwa klasyka polskiego słodkiego świata, która od wielu lat cieszy się nieustanną popularnością wśród miłośników pysznych przysmaków. To połączenie delikatnie rozpuszczającego się mlecznego karmelku z chrupką mleczną czekoladą tworzy niezapomniane wrażenia smakowe, które trudno porównać do innych cukierków dostępnych na rynku. Każdy kawałek to mała czara przyjemności, doskonała jako uzupełnienie codziennego dnia lub idealny prezent dla bliskich osób.\n\nOpakowanie o pojemności 400g zawiera bogatą ilość porcji, idealne zarówno do zapamiętanego słodkiego podwieczorku w gronie rodziny, jak i do wspólnych chwil z przyjaciółmi. Cukierki Kasztanki charakteryzują się niezwykłą smakowością i pozostają świeże dzięki starannie wybranym składnikom oraz profesjonalnym warunkom przechowywania. Dzięki wszechobecnym wśród Polaków tradycyjnym recepturom możesz być pewny, że otrzymujesz produkt najwyższej jakości, który spełni oczekiwania nawet najbardziej wymagających smakoszy.\n\nTa porcja słodkości jest idealna na każdą okazję — zarówno do domowego spożywania, jak i w roli eleganckie prezentu dla kogoś, kto ceni sobie prawdziwą polską słodycz. Kasztanki to gwarancja uśmiechu na twarzy każdego, kto przysmaży ten wyjątkowy smak. Warto mieć je zawsze pod ręką, na biurku czy w szafce, gdyż trudno się im opierać.\n\n### Kluczowe cechy\n\n- **Klasyczny smak** — tradycyjna receptura gwarantująca doskonały, rozpoznawalny smak mlecznego karmelku\n- **Czekoladowe otoczenie** — miękki karmel okryty chrupką mleczną czekoladą wysokiej jakości\n- **Duża porcja** — opakowanie 400g z bogatą liczbą cukierków\n- **Długa świeżość** — starannie pakowane, zachowują świeżość przez długi czas\n- **Idealne do dzielenia się** — doskonały rozmiar porcji dla całej rodziny\n- **Brak sztucznych kolorów** — producent unika sztucznych barwników i zbędnych dodatków\n- **Najlepszy stosunek ceny do jakości** — premiumowa jakość w przystępnej cenie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Pojemność** | 400g |\n| **Typ produktu** | Cukierki mleczne z czekoladą |\n| **Główne składniki** | Karmel mleczny, czekolada mleczna |\n| **Cena** | 26,30 PLN |\n| **Dostępność** | Natychmiastowa wysyłka |\n\n---\n\n**Czy czekasz jeszcze?** Nie przegap okazji i dodaj Cukierki Kasztanki 400g do swojego koszyka już teraz! To sprawdzony hit, który przyniesie Ci i Twoim bliskim wiele chwil szczęścia i słodkiej rozkoszy. Przy takiej cenie i jakości to absolutnie warto mieć opakowanie w domu. Zamów dziś i ciesz się smakiem klasyki polskiej cukierkarni! 🍫\n\n', '26.30', '0.37', 1, 1, 'cukierki-kasztanki-400g', '2023-06-01 00:00:00'),
(8, 'Wafelki Prince Polo XXL', 'SLO-00008', '## Wafelki Prince Polo XXL - Kryztalicznie Czekoladowe Przysmaki\n\nWafelki Prince Polo XXL to doskonały wybór dla wszystkich miłośników czekolady i lekkiego słodkiego przekąsku. Te niezwykłe wafelki łączą chrupiącą, zdmuchnięta strukturę wewnątrz z gładką, bogatą czekoladą otaczającą je z każdej strony. Rozmiar XXL gwarantuje, że każde kęsniecie przynosi maksimum przyjemności i satysfakcji. To idealne połączenie tekstury i smaku, które czyni je niezapomnianym doświadczeniem dla podnieba każdego czekoladowego smakosza.\n\nKażde wafelko Prince Polo XXL jest starannie wyprodukowane z wykorzystaniem najwyższej jakości składników. Czekolada otaczająca wafelki jest kremowa, rozpływająca się delikatnie w ustach, tworząc harmonijny kontrast z lekką i puchnącą waflem wewnątrz. Doskonale nadają się zarówno na słodką przerwę w pracy, do lunchboxa dziecka, jak i na małą przyjemność na zakończenie dnia. Ich poręczny format sprawia, że możesz je zabrać wszędzie - do pracy, szkoły lub w podróż.\n\nTo nie apenas zwykły słodycz – to całe doświadczenie smakowe w jednym kawałku. Niezależnie od tego, czy szukasz czegoś do kawy, herbaty czy po prostu impulsu do słodkich zachcianek, wafelki Prince Polo XXL zawsze będą doskonałym wyborem. Ich uniwersalny smak przypadnie do gustu zarówno dzieciom, jak i dorosłym, a poręczna cena 9,60 PLN czyni je nieodpartą ofertą.\n\n### Kluczowe cechy\n\n- 🍫 **Czekolada Premium** – bogata, kremowa czekolada otaczająca każde wafelko\n- ☁️ **Struktura Kryztaliczna** – lekkie, zdmuchniete wafle tworzące przyjemną teksturę\n- 📦 **Format XXL** – większe wafelko dla maksymalnej satysfakcji\n- 🎯 **Uniwersalny Smak** – idealny dla każdego wieku i preferencji smakowych\n- 💪 **Wysoka Jakość** – starannie wyselekcjonowane składniki\n- 🚀 **Poręczny Format** – idealny do zabrania wszędzie: do pracy, szkoły, podróży\n- ✨ **Niepowtarzalne Doświadczenie** – harmonia tekstury i smaku w jednym kęseniu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Wafelki Prince Polo XXL |\n| **Cena** | 9,60 PLN |\n| **Rozmiar** | XXL |\n| **Główny składnik** | Czekolada i wafle |\n| **Idealne do** | Codziennej przerwę, prezentu, śniadanku |\n\n---\n\n**Nie czekaj!** Wafelki Prince Polo XXL to idealna kombinacja smaku, jakości i ceny, którą warto mieć zawsze pod ręką. Za zaledwie 9,60 PLN możesz cieszyć się tym wyjątkowym przysmakiem każdego dnia. Dodaj do koszyka teraz i odkryj, dlaczego Prince Polo XXL to ulubieniec milionów polskich miłośników czekolady! 🍫✨', '9.60', '0.27', 1, 1, 'wafelki-prince-polo-xxl', '2023-11-29 00:00:00'),
(9, 'Baton Snickers 50g', 'SLO-00009', '## Baton Snickers 50g - Oryginalny Przekąski Pełny Energii\n\n### Opis Produktu\n\nBaton Snickers 50g to kultowa i ulubiona przez miliony людzi na całym świecie przekąska, która doskonale łączy ze sobą wiele smaków w jednym produktzie. Każdy kawałek to harmonijna kombinacja chrupiącego nugatingu, araszidów, karmelizowanej karamy oraz pysznej czekolady mlecznej. Idealny towarzysz do pracy, szkoły, treningu lub podróży – zawsze gdy potrzebujesz szybkiego przypływu energii i przyjemności. Baton Snickers to gwarancja konsekwentnej jakości i smaku, którą znamy już od dziesięcioleci.\n\nNiezależnie od tego, czy jesteś fanem słodkich przekąsek, czy szukasz produktu, który zadowoli Twoją całą rodzinę – Snickers to wybór, który nie zawiedzie. Złożenie produktu zawierającego wysokiej jakości składniki sprawiają, że każdy gryz dostarcza pełnię zadowolenia. Naturalny punkt przed snem, przerwa obiadowa w pracy czy nagłą przyjemność – ten baton zawsze będzie się przydawać w Twojej kieszeni lub tornistrze.\n\nPromocyjna cena 37.5 PLN czyni ten produkt dostępnym dla wszystkich, którzy nie chcą rezygnować z dobrego smaku. Standardowy rozmiar 50g jest idealny zarówno dla tych, którzy chcą degustować małą ilość, jak i dla kolekcjonerów batonów. Zamów teraz i ciesz się tym ikonicznym smakiem bez czekania!\n\n### Kluczowe cechy\n\n- **Autentyczna receptura** – sprawdzony i niezmienny skład, który polubiliśmy od lat\n- **Bogate składniki** – kombinacja czekolady, nugatingu, araszidów i karamelu w jednym batoniku\n- **Wygodny rozmiar 50g** – doskonały do przenoszenia, łatwy do podzielenia się\n- **Naturalny energetyk** – szybki przypływ cukrów i kalorii do natychmiastowego wzmocnienia\n- **Dostępna cena** – tylko 37.5 PLN za oryginalny produkt\n- **Długa trwałość** – dzięki wzmacniającemu opakowaniu produkt zachowuje świeżość\n- **Uniwersalna przyjemność** – polubiony przez dzieci i dorosłych na całym świecie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Baton Snickers 50g |\n| **Waga netto** | 50 gram |\n| **Cena** | 37.5 PLN |\n| **Główne składniki** | Czekolada, nugat, araszidy, karmel |\n| **Kraj pochodzenia** | Wielka Brytania |\n\n### Podsumowanie\n\nBaton Snickers 50g to więcej niż zwykła przekąska – to kawałek tradycji i smaku, który towarzyszył pokoleniom. Za jedyne 37.5 PLN otrzymujesz oryginalny produkt najwyższej jakości, gotowy do natychmiastowego spożycia. Nie czekaj na lepszą okazję – dodaj do koszyka teraz i pozwól sobie na chwilę czystej przyjemności. Zaufaj liczbie, która mówi sama za siebie – miliony zadowolonych konsumentów na całym świecie wybrało już Snickers. **Zamów dzisiaj i doświadcz smaku, który nigdy się nie nudzi!**', '37.50', '0.09', 1, 1, 'baton-snickers-50g', '2024-02-22 00:00:00'),
(10, 'Praliny Lindt Lindor', 'SLO-00010', '## 🍫 Praliny Lindt Lindor - Miękkie Pralinki ze Słodkim Serem\n\nOdkryj niezapomniane wrażenia smakowe z kultowymi pralinkami Lindt Lindor! Te wyjątkowe pralinki od ponad 170 lat słyną z niezrównanej jakości i wyjątkowego czekoladowego doświadczenia. Każda kulka Lindor to połączenie chrupiącej czekoladowej skorupki z niezwykle miękkim, kremowym nadzieniem – prawdziwa uczta dla podniebienia każdego miłośnika czekolady. Produkty Lindt to gwarancja Swiss premium quality, wykonane z najlepszych składników i starannie wyselekcjonowanego kakao.\n\nPraliny Lindt Lindor to idealny wybór dla osób szukających wyjątkowego prezentu, jak i dla siebie na specjalną okazję. Każda praline rozpływa się w ustach, oferując niepowtarzalny moment relaksu i przyjemności. Doskonałe jako prezent dla bliskich osób, dodatek do świątecznego stołu, czy po prostu przyjemna przekąska, którą chce się cieszyć w spokojnym momencie. Lekka, elegancka opakowanie sprawia, że to także doskonały pomysł na upominek dla koleżanki czy kolegi z pracy.\n\nLindt Lindor to nie tylko zwykłe cukierki – to rzeczywista czekoladowa sztuka, łącząca tradycję szwajcarskiego rzemiosła z nowoczesnymi technikami produkcji. Wysoka zawartość kakao i naturalnych składników gwarantuje autentyczny smak, bez sztucznych dodatków. Każda porcja to przyjemność, którą warto sobie pozwolić, a jakość Lindt zapewnia satysfakcję z każdą kulką.\n\n### 🎁 Kluczowe cechy\n\n- **Autentyczna Lindt Lindor** – kultowe pralinki ze Szwajcarii z 170-letnią tradycją\n- **Kremowe wypełnienie** – miękkie, rozpływające się w ustach nadzienie z charakterystycznym smakiem\n- **Chrupiąca czekoladowa skorupka** – kontrast tekstur na najwyższym poziomie\n- **Premium jakość składników** – швajcarskie kakao i naturalne komponenty bez sztucznych dodatków\n- **Elegancka prezentacja** – pięknie zapakowane, gotowe do prezentu\n- **Idealne na każdą okazję** – walentynki, urodziny, podziękowanie, przyjemność dla siebie\n- **Długa data ważności** – świeżość produktu gwarantowana przez producenta\n\n### 📋 Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Producent** | Lindt (Szwajcaria) |\n| **Produkt** | Lindor Praliny czekoladowe |\n| **Cena** | 13.54 PLN |\n| **Kategoria** | Słodycze, czekolada premium |\n| **Zawartość** | Pralinki w opakowaniu (waga może się różnić) |\n\n---\n\n**Zamawiaj teraz i ciesz się światowej klasy czekoladą!** 🍫✨\n\nPraliny Lindt Lindor to inwestycja w chwilę czystej przyjemności i smakowej eskapady. Za jedyne 13,54 PLN otrzymujesz gwarancję autentyczności i niezrównanego smaku. Nie czekaj – dodaj do koszyka i poczuj się jak w Szwajcarii! Doskonałe na teraz, albo jako niespodzianka dla kogoś, kto docenia dobre rzeczy. **Zamów dzisiaj i niech każda chwila będzie słodka! 🛒💝**', '13.54', '0.29', 1, 1, 'praliny-lindt-lindor', '2024-05-02 00:00:00'),
(11, 'Chałwa Królewska 250g', 'SLO-00011', '## Chałwa Królewska 250g\n\n**Odkryj autentyczny smak Orientu w każdej porcji!** Chałwa Królewska to tradycyjny przysmak o bogatej historii, który od wieków cieszy się sympatią miłośników słodyczy na całym świecie. Nasza Chałwa Królewska to połączenie najwyższej jakości składników, doskonałego rzemiosła i niezapomnianego smaku, który przeniesie Cię w podróż kulinarną pełną smaków Bliskiego Wschodu. Każdy kawałek to harmonia kremowej tekstury i delikatnej słodyczy, która rozpływa się na języku, pozostawiając uczucie absolutnej przyjemności.\n\nChałwa jest idealna jako uzupełnienie popołudniowej kawy lub herbaty, a także stanowi wyjątkowy prezent dla bliskich osób, które cenią egzotyczne i wytrawne przysmaki. Dzięki praktycznemu opakowaniu 250g możesz cieszyć się nią w domu, zabrać ze sobą do pracy lub podzielić się nią z przyjaciółmi. Ta słodycz nie zawiera sztucznych kolorów i konserwantów – tylko czyste, autentyczne składniki, które zadbają o Twoje zadowolenie z każdym kęsem.\n\nChałwa Królewska to nie tylko smakołyk, ale również bogactwo tradycji i wyjątkowych doświadczeń kulinarnych. Jej naturalna słodycz, delikatnie intensywny smak i niezwykła tekstura sprawiają, że po raz pierwszy spróbując, będziesz wracać do niej jeszcze wiele razy. Niezależnie od tego, czy jesteś fanem orientalnych przysmaków, czy dopiero zaczynasz swoją przygodę ze słodyczami z bardziej egzotycznych stron świata – Chałwa Królewska będzie idealnym wyborem dla Ciebie.\n\n### Kluczowe cechy\n\n- 🎯 **Autentyczna receptura orientalna** – tradycyjny skład bez sztucznych dodatków i konserwantów\n- 💪 **Bogata w energię** – idealna jako przekąska przed treningiem lub długim dniem\n- 🧁 **Kremowa, rozpływająca się tekstura** – przyjemna w smaku i łatwa do konsumpcji\n- ⭐ **Premium jakość składników** – wyselekcjonowane orzechy i najlepsze przyprawy\n- 📦 **Wygodne opakowanie 250g** – idealne dla jednej osoby lub do dzielenia się\n- 🌍 **Produkt importowany** – autentyczna chałwa z tradycyjnym przepisem\n- ❤️ **Brak alergii MLG** – przyjazna dla osób z wrażliwościami (sprawdź zawartość składników)\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Waga netto** | 250g |\n| **Cena** | 24,34 PLN |\n| **Pochodzenie** | Import (tradycyjna receptura orientalna) |\n| **Składniki główne** | Sezam, miód, orzechy, przyprawy |\n| **Przechowywanie** | W suchym, chłodnym miejscu, w zapieczętowanym opakowaniu |\n\n---\n\n**Nie czekaj – dodaj Chałwę Królewską do koszyka już teraz i odkryj smak autentycznego Orientu w wygodzie Twojego domu!** Za zaledwie **24,34 PLN** możesz cieszyć się premium słodyczą, która zauroczy Twoje zmysły i stanie się Twoją ulubioną przekąską. Szybkie dostawy, bezpieczne opakowanie i pełna gwarancja zadowolenia – to wszystko czeka na Ciebie! 🌟', '24.34', '0.12', 1, 1, 'chalwa-krolewska-250g', '2023-11-14 00:00:00'),
(12, 'Torcik Wedlowski 250g', 'SLO-00012', '## 🍰 Torcik Wedlowski 250g\n\nOdkryj prawdziwy smak luksusu z wyjątkowym **Torckiem Wedlowskim** - delikatnym ciastem, które łączy tradycję z nowoczesnym smakiem. To nie zwykły torcik, ale miniaturowe dzieło sztuki cukierniczej, wytwarzane z najwyższej jakości składników. Każdy kęs to eksplozja aromatów i miękkiej struktury, która rozpływa się na języku. Produkt idealny zarówno na codzienną przyjemność, jak i na specjalne okazje, gdy chcesz zaskoczyć kogoś bliskiego czegoś naprawdę wyjątkowego.\n\nTorcik Wedlowski to propozycja dla wymagających smakoszy, którzy nie boją się sięgać po produkty premium. Wykonany z dbałością o detale, łączy doskonałość smaku z estetycznym wyglądem. Czeka na Ciebie wyrafinowana receptura, która przez wiele lat zadomowiła się w sercach miłośników słodyczy. To połączenie tradycyjnego rzemiosła cukierniczego i najlepszych składników, które gwarantuje niezapomniane doświadczenie kulinarowe. Idealne uzupełnienie kolekcji słodyczy w Twojej domowej spiżarni!\n\nWielkopakowość 250 gramów to idealny wybór zarówno dla jednej osoby, jak i dla całej rodziny. Produkt zachowuje świeżość dzięki starannym opakowaniu, a jego uniwersalny rozmiar pozwala na łatwe przechowywanie. Każda porcja to gwarancja satysfakcji i pełna przyjemność z jedzenia słodyczy najwyższej klasy. Nie czekaj – sięgnij po torcik, który podbija podniebienia wszystkich.\n\n### ✨ Kluczowe cechy\n\n- 🎁 **Premium jakość** - produkt z segment wysokiej klasy, wykonany z najlepszych składników\n- 🥄 **Doskonały smak** - charakterystyczna, wyrafinowana receptura o intensywnym aromacie\n- 📦 **Praktyczne opakowanie** - 250g w eleganckim opakowaniu, idealne do przechowywania\n- 👨‍👩‍👧‍👦 **Dla całej rodziny** - rozmiar idealne zarówno na osobistą przyjemność, jak i do dzielenia się z bliskimi\n- 🌟 **Uniwersalne zastosowanie** - doskonały jako prezent, deser, uzupełnienie kolekcji słodyczy\n- 🎯 **Długa świeżość** - starannie opakowany, aby zachować świeżość i smak\n- 💝 **Wyjątkowe doświadczenie** - torcik na każdą okazję - od codzienności po świętowanie\n\n### 📋 Specyfikacja\n\n| Cecha | Wartość |\n|-------|---------|\n| **Nazwa produktu** | Torcik Wedlowski |\n| **Waga netto** | 250g |\n| **Cena** | 38,45 PLN |\n| **Kategoria** | Ciastka i słodysze |\n| **Opakowanie** | Karton ochronny |\n\n---\n\n### 🛒 Zamów teraz!\n\nNie przegap okazji, aby wprowadzić do swojego życia odrobinę słodkiego luksusu! **Torcik Wedlowski 250g** w cenie **38,45 PLN** to inwestycja w radość i smak. Dodaj do koszyka dzisiaj i ciesz się dostawą już za kilka dni. Jeśli szukasz prezentu dla kogoś, kto docenia dobre smaki, to idealny wybór. Zamów teraz i odkryj, dlaczego ten torcik zdobył serca tak wielu klientów! 🎉', '38.45', '0.06', 1, 1, 'torcik-wedlowski-250g', '2024-05-05 00:00:00'),
(13, 'Batoniki 3Bit 46g', 'SLO-00013', '## Batoniki 3Bit 46g – Porcja Czystej Przyjemności w Każdym Gryzie\n\nOdkryj niezapomniany smak z batonikami 3Bit! To doskonała kombinacja trzech wyjątkowych warstw, które łączą się w harmonijną symphony smaków. Każdy batonik zawiera precyzyjnie dobrane składniki, które gwarantują niezapomniane doświadczenie kulinarnego przyjemności. Idealne jako przekąska do kawy, herbaty lub jako szybka energia w ciągu dnia. Batoniki 3Bit to nie tylko smak – to całe doświadczenie, które sprawdzi się zarówno dla każdego miłośnika słodyczy, jak i dla tych, którzy szukają wyjątkowego угощения w każdej chwili.\n\nKażdy kawałek batonika 3Bit to starannie przygotowana mieszanka najwyższej jakości składników, które wspólnie tworzą niezwykły smak. Wygodne opakowanie 46g sprawia, że batonik jest idealnym towarzyszem w drodze – do szkoły, pracy, na wycieczkę czy do siłowni. Dzięki optymalnej wielkości możesz cieszyć się smakiem bez poczucia winy, a jednocześnie bez konieczności rezygnacji z ulubionych smaków. To przekąska, którą będziesz chciał(a) jeść znowu i znowu.\n\nProducent batoników 3Bit dba o każdy szczegół – od wyboru ingrediencji po ostateczny smak. To gwarancja, że każdy batonik będzie równie smaczny co poprzedni. Niezależnie od tego, czy szukasz idealnej przekąski do biura, prezentu dla kogoś bliskiego czy po prostu czegoś dla siebie – batoniki 3Bit zawsze będą trafionym wyborem. Smak, jakość i wygoda w jednym opakowaniu!\n\n### Kluczowe cechy\n\n- 🎯 **Trójwarstwowa composition** – unikalna kombinacja smaków w każdym batoniku\n- 📦 **Praktyczne opakowanie 46g** – idealna porcja dla każdej chwili dnia\n- ✨ **Wysoka jakość składników** – starannie dobrane ingrediencje bez zbędnych dodatków\n- 🚀 **Porcja energii** – szybka przekąska zapewniająca przypływ energii\n- 🎁 **Wygodna forma** – łatwa do transportu w plecaku, torebce lub kieszeni\n- 💯 **Niezapomniane doświadczenie smakowe** – smak, którego będziesz szukać(a) znowu\n- 🏆 **Sprawdzony bestseller** – ulubieniec miłośników batoników na całym świecie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Pojemność opakowania** | 46g |\n| **Cena** | 14.07 PLN |\n| **Liczba warstw smaków** | 3 |\n| **Forma** | Batonik |\n| **Idealnie do** | Każdej pory dnia, podróży, biura, szkoły |\n\n---\n\n**Nie czekaj dłużej!** Dodaj batoniki 3Bit do swojego koszyka i ciesz się niezwykłym smakiem, który sprawi, że każdy dzień będzie słodszy. Za jedyne **14.07 PLN** otrzymujesz gwarancję smacznej, energetyzującej przekąski, którą będziesz chciał(a) kupować jeszcze wiele razy. **Zamów teraz** i odkryj, dlaczego batoniki 3Bit są ukochaną przekąską milionów ludzi! 🎉', '14.07', '0.23', 1, 1, 'batoniki-3bit-46g', '2024-02-02 00:00:00'),
(14, 'Cukierki Krówka Polska', 'SLO-00014', '## Cukierki Krówka Polska\n\nOdkryj niezapomniane doznania smakowe z kultowym słodyczami spod znaku tradycji i jakości! Cukierki Krówka Polska to prawdziwa perła polskiego cukiernictwa, która od pokolacji cieszy się miłością polskich konsumentów. Każda krówka to połączenie słodkiej mlecznej masy karmelowej z chrupiącą czekoladą, tworząc harmonijny duet smaków, który roztapia się w ustach jak delikatna chmurka. To nie jest zwyczajny cukierek – to nostalgia, tradycja i czysta radość zamknięta w opakaniu.\n\nNasze Cukierki Krówka Polska wyróżniają się najwyższą jakością składników oraz recepturą doskonaloną przez dziesięciolecia. Każdy kawałek jest wykonany z dbałością o detale, bez sztucznych barwników czy konserwantów, dzięki czemu możesz cieszyć się smakiem w czystej postaci. Idealnie sprawdzą się jako przekąska na każdą porę dnia, słodkie uzupełnienie obiadu czy prezent dla bliskich, którzy cenią sobie tradycyjne polskie rarytasy. Opakowanie utrzymuje świeżość produktu i zapewnia bezpieczny transport.\n\nCzy szukasz słodkiego poczęstunku, który rozbawi zmęczony dzień? Czy chcesz przypomnieć sobie smaki dzieciństwa? Krówka Polska to propozycja dla wszystkich, którzy szanują tradycję i nie chcą iść na kompromis w kwestii smaku. Zarówno dla siebie, jak i jako oryginalny upominek – nie ma lepszego wyboru!\n\n### Kluczowe cechy\n\n- 🍫 **Autentyczna recepta** – tradycyjna mleczna karmelka w czekoladowej polewie\n- ✨ **Najwyższa jakość** – bez sztucznych additywów, kolorów i konserwantów\n- 👨‍👩‍👧‍👦 **Dla całej rodziny** – bezpieczny dla dzieci i dorosłych\n- 🎁 **Idealne do prezentu** – polskie rarytasy doceniane na całym świecie\n- 💪 **Satysfakcjonujący smak** – każdy kawałek daje maksymalną przyjemność\n- 🏭 **Produkcja krajowa** – wspierasz polskie rzemiosło cukiernicze\n- ⏰ **Długa świeżość** – starannie opakowane, długi okres przydatności\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Cukierki Krówka Polska |\n| Cena | 40,59 PLN |\n| Typ | Karmelki w czekoladzie |\n| Origen | Polska (produkcja krajowa) |\n| Opakowanie | Pudełko |\n\n---\n\n**Nie czekaj dłużej!** Dodaj do koszyka Cukierki Krówka Polska i poczuj autentyczny smak polskiej tradycji. Za mniej niż 41 złotych zyskasz chwile czystej przyjemności i uśmiechu na twarzy. Zamów teraz i niech słodkie chwile będą Twoją codziennością! ❤️\n\n*Szybka dostawa • Bezpieczne opakowanie • Gwarancja najwyższej jakości*', '40.59', '0.09', 1, 0, 'cukierki-krowka-polska', '2024-02-08 00:00:00'),
(15, 'Galaretki Wawel 350g', 'SLO-00015', '## 🍬 Galaretki Wawel 350g – Słodka Tradycja w Nowoczesnym Opakowaniu\n\nGalaretki Wawel to klasyk polskich słodyczy, który od pokoleń cieszy się niezmieniającą popularnością zarówno wśród dzieci, jak i dorosłych miłośników słodkich przysmaków. Opakowanie zawierające 350 gramów to idealna ilość do codziennego spożywania w domu, do pracy czy szkoły. Każda galaretka to wysoko skoncentrowany smak owocu, połączony z delikatną, sprężystą konsystencją, która rozpuszcza się na języku, pozostawiając hosszotrwały, przyjemny aftertaste. Wawel, marka o ponad 100-letniej tradycji, gwarantuje najwyższą jakość składników i autentyczny smak, który poznało już wiele pokoleń Polaków.\n\nGalaretki Wawel to nie tylko doskonała przekąska do kawy czy herbaty, ale także świetna propozycja na prezent dla bliskich czy słodka nagroda dla siebie. Ich intensywne, owoce aromatyczne uczułają zmysły, a wciągająca tekstura sprawiają, że nie potrafisz przestać jeść. Produkt zawiera skoncentrowany sok owocowy, bez sztucznych barwników – wykorzystując naturalne pigmenty roślinne do uzyskania atrakcyjnych kolorów. Każda porcja to czysta radość i satysfakcja dla podniebienia każdego członka rodziny.\n\nNiezależnie od okazji – czy to zwykły dzień, przyjęcie, podróż czy długa noc pracy – galaretki Wawel zawsze sprawdzą się doskonale. Ich uniwersalność, niezmiennie wysoka jakość i przystępna cena czynią je produktem, który powinien znaleźć się w każdej domowej apteczce słodyczy. Wawelskie galaretki to gwarancja doskonałego smaku i tradycji rzemiosła cukierniczego, które podchodzą z niezwykłą czułością do każdej porcji.\n\n### 🌟 Kluczowe cechy\n\n- **Rozmiar XL** – Duże opakowanie 350g zapewnia długotrwałą satysfakcję i świetny stosunek ilości do ceny\n- **Intensywny smak owocu** – Każda galaretka to koncentrat naturalnych aromatów, które rozpuszczają się na języku\n- **Bez sztucznych barwników** – Barwy pochodzą ze źródeł naturalnych, bezpieczne dla całej rodziny\n- **Elastyczna, sprężysta konsystencja** – Charakterystyczna tekstura, która od lat cieszy miłośników galerek\n- **Marka z tradycją** – Wawel to synonim jakości od ponad 100 lat\n- **Idealna na każdą okazję** – Do kawy, jako słodka przekąska czy lunchbox\n- **Atrakcyjna cena** – Najlepsza propozycja na rynku za 29,86 PLN\n\n### 📋 Specyfikacja\n\n| Parametr | Szczegóły |\n|----------|-----------|\n| **Producent** | Wawel |\n| **Waga netto** | 350g |\n| **Cena** | 29,86 PLN |\n| **Typ produktu** | Galaretki owocowe |\n| **Składniki główne** | Skoncentrowany sok owocowy, cukier, żelatyna |\n\n---\n\n**🎁 Nie czekaj, zamawiaj teraz!**\n\nGalaretki Wawel 350g to połączenie tradycji, smaku i przystępnej ceny, które trudno znaleźć na rynku. Za zaledwie **29,86 PLN** otrzymasz porcję autentycznych, wysokiej jakości słodyczy, które wzbogacą Twoje dni słodkością. Zarówno jeśli szukasz prezentu dla bliskich, jak i luksusowego przysmaków dla siebie – ten produkt to gwarancja zadowolenia. Dodaj do koszyka już dziś i ciesz się niezapomnianym smakiem klasycznych galerek Wawel!', '29.86', '0.07', 1, 1, 'galaretki-wawel-350g', '2023-06-30 00:00:00'),
(16, 'Czekolada Gorzka Lindt 85%', 'SLO-00016', '## Czekolada Gorzka Lindt 85%\n\nOdkryj niezwykłą głębię smaku z **Czekoladą Gorską Lindt 85%** – prestiżową kreacją szwajcarskiego producenta słynnego z najwyższej jakości czekolad. Ta wyjątkowa tabliczka to połączenie intensywnego kakao z charakterystyczną gładkością, którą Lindt doskonalił przez ponad 170 lat. Idealna dla wszystkich miłośników prawdziwej, czystej czekolady, którzy cenią sobie autentyczne smaki bez zbędnych dodatków.\n\nCzekolada o zawartości 85% kakao to absolutna gratka dla smakoszy szukających mocnego, aromatycznego doświadczenia. Każdy segment rozpływa się delikatnie na języku, uwalniając złożone nuty gorzkości, lekkiej kwaskości i charakterystycznych nut ziemistych. Ta tabliczka stanowi doskonałą alternatywę dla mlecznych słodyczy – idealna zarówno do samodzielnego spożycia, jak i jako dodatek do kawy czy herbaty, która jej smak doskonale podkreśli.\n\nLindt to marka renomowana na całym świecie, synonim najwyższej jakości i konsekwencji w dążeniu do doskonałości. Czekolada ta nie zawiera sztucznych aromatów ani konserwantów, a jej skład ogranicza się do niezbędnych składników. To inwestycja w prawdziwą przyjemność, która przeniesie Cię w świat prawdziwych, intensywnych smaków. Każda tabliczka pakowana jest z troską o świeżość i jakość produktu.\n\n### Kluczowe cechy\n\n- 🍫 **85% zawartość kakao** – wysoki procent czystego kakao dla intensywnego smaku\n- ✨ **Gładka tekstura Lindt** – charakterystyczna, delikatna konsystencja rozpływająca się na języku\n- 🇨🇭 **Szwajcarska jakość** – produkt renomowanej marki z ponad 170-letnią tradycją\n- 📦 **Naturalne składniki** – bez sztucznych aromatów i konserwantów\n- ⚖️ **Standardowa tabliczka** – wygodny format do spożycia i przechowywania\n- 🎁 **Doskonały prezent** – elegancka opakowanie idealnie sprawdza się jako upominek\n- ☕ **Uniwersalne zastosowanie** – wspaniała przekąska, dodatek do koffee lub bazy do deserów\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | Lindt |\n| Zawartość kakao | 85% |\n| Typ czekolady | Gorzka |\n| Pochodzenie | Szwajcaria |\n| Cena | 11,06 PLN |\n\n---\n\n**Nie czekaj dłużej!** Jeśli jesteś zapalonym fanem czekolady i szukasz produktu, który nie zawiedzie Cię smakiem i jakością, **Czekolada Gorzka Lindt 85%** jest dokładnie tym, czego potrzebujesz. Dodaj do koszyka dziś i ciesz się wyśmienitą chwilą dla siebie lub obdarz czekoladą bliskie osoby. Za kwotę zaledwie **11,06 PLN** otrzymujesz gwarancję autentycznego, szwajcarskiego doświadczenia kulinarnego. Zamawiaj teraz – raz spróbujesz, a będziesz wracać na więcej! 🍫✨', '11.06', '0.12', 1, 1, 'czekolada-gorzka-lindt-85', '2023-11-05 00:00:00'),
(17, 'Draże M&M\'s Orzechowe', 'SLO-00017', '## Draże M&M\'s Orzechowe - Słodkie Przyjemności z Orzechowym Sercem\n\nM&M\'s Orzechowe to idealna przekąska dla każdego, kto ceni sobie połączenie chrupiącej czekoladowej powłoki z delikatnym orzechowym nadzieniem. Każde draże to mała dawka czystej przyjemności – miękki, smaczny orzech w całości otoczony śmietankową czekoladą mleczną, a wszystko to opakowane w kolorową, cukrową powłokę. Niewielkie rozmiary sprawiają, że można je łatwo nosić ze sobą do pracy, szkoły czy na wyprawę. To na pewno ulubieniec wielu osób, szukających czegoś słodkiego i satysfakcjonującego jednocześnie.\n\nDraże M&M\'s to nie tylko smak – to również rada dobrych chwil. Świetnie sprawdzają się jako dodatek do filmowego maratonu, miła niespodzianka w lunch boxie czy idealna drobna przekąska między posiłkami. Dzięki wygodnemu opakowania możesz je dzielić ze znajomymi lub zabrać na podróż. Każda porcja to gwarancja świeżości i wysokiej jakości – produkty M&M\'s pochodzą z renomowanego producenta, słynącego z doskonałych słodyczy na całym świecie. Smak orzecha łączy się tu perfekcyjnie z klasyczną formułą M&M\'s, tworząc niezapomniany doświadczenie kulinarny.\n\nCzy szukasz prezentu dla kogoś bliskiego? Draże M&M\'s Orzechowe będą doskonałym wyborem! Wszechstronne zastosowanie, przyciągający wzrok packaging oraz niezawodny smak sprawiają, że produkt ten sprawdzi się w każdej sytuacji. Teraz możesz cieszyć się tą klasyczną słodyczą w niskiej cenie – zamawiaj jeszcze dziś i odkryj magię M&M\'s!\n\n### Kluczowe cechy\n\n- 🍫 **Miękki orzech** otoczony śmietankową czekoladą mleczną – doskonała kombinacja tekstur\n- 🎨 **Kolorowa cukrowa powłoka** – każde draże jest innego koloru, co dodaje zabawy\n- 📦 **Praktyczne opakowanie** – idealne do noszenia ze sobą w torebce czy plecaku\n- ✨ **Świeża jakość** – gwarantowana świeżość i smak produktu od znanej marki\n- 🌰 **Naturalny smak orzechowy** – prawdziwy orzech, a nie sztuczny aromat\n- 👥 **Idealne do dzielenia** – świetna opcja na wieczór z przyjaciółmi\n- 💯 **Bez sztucznych barwników** – wyprodukowane z naturalnych składników\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Draże M&M\'s Orzechowe |\n| **Masa netto** | 250 g (typowe opakowanie) |\n| **Skład główny** | Orzech, czekolada mleczna, cukier, guma arabska |\n| **Cena** | 49,30 PLN |\n\n---\n\n**Nie czekaj – zamawiaj teraz i ciesz się słodkim rarytasem w najlepszej cenie!** Draże M&M\'s Orzechowe to gwarancja zadowolenia dla każdego miłośnika słodyczy. Dodaj produkt do koszyka, a przywieziemy go do Ciebie szybko i bezpiecznie. Odkryj, dlaczego M&M\'s to światowy hit, który pokochały miliony osób! 🎉', '49.30', '0.45', 1, 1, 'draze-m-m-s-orzechowe', '2024-05-23 00:00:00'),
(18, 'Lizaki Chupa Chups Mix', 'SLO-00018', '## Lizaki Chupa Chups Mix – kolorowe słodycze dla całej rodziny\n\nChupa Chups Mix to idealne połączenie różnorodności smaków i klasycznego designu, który pokochało już pokolenia dzieci i dorosłych na całym świecie. Ten zestaw zawiera porcje najlepszych smaków legendarne marki Chupa Chups, które gwarantują niezapomniane chwile smakowe. Każdy lizak to nie tylko słodycz, ale również uśmiech na twarzy. Idealna opcja zarówno dla fanów klasycznych smaków, jak i tych, którzy lubią eksperymentować z nowym doświadczeniem smakowym. Zapakowani w charakterystyczne opakowanie ze słynnym logo, lizaki Chupa Chups stały się symbolem dzieciństwa i beztroski.\n\nRóżnorodność smaków w zestawie Mix sprawia, że każdy znajdzie coś dla siebie. Od orzeźwiającej wisni, przez słodką truskawkę, aż po cytrusowe nuty – każdy lizak to osobna przygoda smakowa. Produkty Chupa Chups słyną z wysokiej jakości składników i bogatego koloru, który przyciąga uwagę już na półce sklepu. Doskonale nadają się jako drobny prezent dla bliskich, nagroda dla dziecka, czy po prostu przyjemne urozmaicenie dnia. Lizaki mogą być również idealnym uzupełnieniem wystroju imprezowego stołu czy jako słodycze na każdą okazję.\n\nTe ikoniczne lizaki cieszą się popularnością od ponad 60 lat i nadal są wybierane przez miliony konsumentów na całym świecie. Chupa Chups Mix łączy tradycję z nowoczesnością, dostarczając czystej radości i autentycznego smaku w każdym gryznieniu. Niezależnie od wieku, Chupa Chups to produkt, który nigdy wychodzi z mody i zawsze gwarantuje uśmiech zadowolenia.\n\n### Kluczowe cechy\n\n- **Mix smaków** – zestaw zawierający różnorodne warianty smakowe, każdy o unikalnym smaku i zapachu\n- **Klasyczny kształt** – charakterystyczne okrągłe lizaki na patyku, wygodne do trzymania\n- **Naturalne kolory** – intensywne zabarwienie przyciągające oczy konsumentów\n- **Długo trwały smak** – każdy lizak zapewnia długie minuty słodkiej przyjemności\n- **Bezpieczna dla dzieci** – spróbowany przez generacje produkt, przyjazny dla całej rodziny\n- **Idealna do podziału** – doskonała jako prezent lub przysmak do podzielenia się z bliskimi\n- **Konkurencyjna cena** – dostępny w atrakcyjnej cenie 36,88 PLN\n\n### Specyfikacja\n\n| Cecha | Szczegóły |\n|-------|-----------|\n| **Nazwa produktu** | Lizaki Chupa Chups Mix |\n| **Cena** | 36,88 PLN |\n| **Marka** | Chupa Chups |\n| **Typ produktu** | Lizaki asortymenty smaków |\n| **Zastosowanie** | Słodycze, prezenty, przekąska |\n\n---\n\n**Nie czekaj – zamów Chupa Chups Mix już dziś!** Przekonaj się sam, dlaczego te lizaki są uwielbiane na całym świecie. W cenie 36,88 PLN zyskujesz nie tylko słodkie przysm艺aki, ale również uśmiech zadowolenia każdego członka rodziny. Dodaj do koszyka teraz i ciesz się pełnią smaków! 🍭', '36.88', '0.26', 1, 1, 'lizaki-chupa-chups-mix', '2024-02-07 00:00:00');
INSERT INTO `products` (`id`, `name`, `sku`, `description`, `price`, `weight`, `category_id`, `active`, `image`, `created_at`) VALUES
(19, 'Czekoladki Raffaello 150g', 'SLO-00019', '## 🍫 Czekoladki Raffaello 150g - Luksusowa Słodycz do Każdej Chwili\n\nOdkryj niepowtarzalny smak elegancji i wyrafinowania! Czekoladki Raffaello to ikoniczny produkt marki Ferrero, który od lat zdobywa serca miłośników czekolady na całym świecie. Każde cukierek to idealne połączenie delikatnej, białej czekolady z chrupiącym orzechowo-migdałowym wypełnieniem, otoczonym płatkami kokosowymi. To nie tylko słodycz – to całe doświadczenie sensoryczne, które przenosi Cię do świata luksusu i słodkich przyjemności.\n\nRaffaello to perfekcyjna propozycja zarówno dla miłośników czekolady, jak i dla osób poszukujących wyjątkowego prezentu. Opakowanie zawierające 150 gramów to idealna ilość do codziennego cieszenia się słodyczą lub poczęstowania bliskich osób. Każdy cukierek jest starannie opakowany w papierek, co gwarantuje jego świeżość i doskonały wygląd. Subtelny smak białej czekolady, wzbogacony nutą kokosa i migdału, sprawia, że Raffaello to słodycz, którą chce się sięgać raz za razem.\n\nBez względu na okazję – czy to relaksujący wieczór przed telewizorem, przerwa w pracy, czy też elegancki stolik kawowy podczas spotkania towarzyskiego – Raffaello zawsze będą właściwym wyborem. Ta wyjątkowa czekolada łączy tradycję, smak i estetykę w jednym świetnie zapakowanym opakowaniu. Gwarantujemy świeżość i najwyższą jakość produktu bezpośrednio od dystrybutora.\n\n### 🎁 Kluczowe cechy\n\n- **Biała czekolada premiumowej jakości** – gładka, delikatna i o niebieskim smaku\n- **Migdałowo-orzechowe wypełnienie** – chrupiące i bogate w smak, dodające tekstury każdemu ujęciu\n- **Płatki kokosowe** – delikatnie obsypane na zewnątrz dla dodatkowego carachu i aromatu\n- **Opakowanie indywidualne** – każdy cukierek zapakowany oddzielnie, gwarantując świeżość i łatwość transportu\n- **Rozmiar 150g** – idealna porcja dla jednej osoby lub do dzielenia się ze bliskimi\n- **Produkt marki Ferrero** – gwarancja najwyższej jakości i konsekwencji smakowej\n- **Doskonały na każdą okazję** – od codziennego ucieszenia się słodyczą po elegancki prezent\n\n### 📋 Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Czekoladki Raffaello |\n| Waga netto | 150 g |\n| Producent | Ferrero |\n| Typ czekolady | Biała czekolada |\n| Skład główny | Czekolada, migdał, kokos, orzechy |\n| Cena | 20,55 PLN |\n\n---\n\n### ✨ Dlaczego warto kupić Raffaello?\n\nJeśli szukasz czekolady, która będzie stanowiła doskonałą kombinację smaku, wyglądu i prestiżu – Raffaello to Twój wybór! Produkty Ferrero od lat cieszą się zaufaniem miłionów konsumentów na całym świecie, a ich jakość jest niezaprzeczalna. Opakowanie zawierające 150 gramów to uniwersalna porcja – idealna zarówno do personal delight, jak i do dzielenia się z przyjaciółmi i rodziną.\n\nW naszym sklepie otrzymujesz gwarancję autentyczności, świeżości i najlepszej ceny – **tylko 20,55 PLN**! To inwestycja w małą przyjemność, która sprawi, że Twój dzień stanie się bardziej słodki. Nie czekaj – dodaj Raffaello do koszyka już teraz i ciesz się luksusową czekoladą, która na zawsze pozostaje ulubienicą smakoszy!', '20.55', '0.17', 1, 1, 'czekoladki-raffaello-150g', '2023-08-13 00:00:00'),
(20, 'Mieszanka Wedlowska 360g', 'SLO-00020', '## Mieszanka Węglowska 360g\n\nMieszanka Węglowska to doskonały wybór dla każdego, kto ceni sobie autentyczny smak tradycyjnych przysmaków z najlepszymi składnikami. Każde opakowanie zawiera starannie dobrane komponenty, które tworzą harmonijną kombinację smaków i konsystencji. Idealnie sprawdza się zarówno w codziennym użytkowaniu, jak i na bardziej wyjątkowe okazje. Produkt przygotowany z dbałością o najwyższą jakość gwarantuje zadowolenie nawet najbardziej wymagających smakoszy.\n\nWysoka zawartość porcji (360g) sprawia, że jedno opakowanie wystarczy na wiele wspólnych momentów z rodziną i przyjaciółmi. Mieszanka Węglowska karakteryzuje się intensywnym aromatem i bogatym profilem smakowym, który pozostaje na długo w pamięci. Dzięki optymalnym proporcjom składników produkt zachowuje świeżość i naturalny wygląd przez długi czas przechowywania. To propozycja dla osób, które nie goodzą się na kompromisy, jeśli chodzi o jakość jedzenia.\n\nNiezależnie od tego, czy szukasz podarunku dla bliskiej osoby, czy chcesz się sama/sam czymś podelektować, Mieszanka Węglowska będzie trafnym wyborem. Polecamy ją zwłaszcza fanom tradycyjnych polskich smaków i wszystkim tym, którzy cenią autentyczność oraz staranność w wyborze produktów. Przy cenie zaledwie 32,33 PLN otrzymujesz wyjątkową wartość oraz gwarancję satysfakcji.\n\n### Kluczowe cechy\n\n- **Opakowanie 360g** – idealna ilość na liczne porcje dla całej rodziny\n- **Tradycyjny skład** – przygotowane z najlepszych, starannie wybranych składników\n- **Intensywny smak** – bogaty profil smakowy, który zapamiętasz na długo\n- **Długi termin przechowywania** – zachowuje świeżość i качество w optymalnych warunkach\n- **Wszystko w jednym** – praktyczne i uniwersalne rozwiązanie dla wielu zastosowań\n- **Doskonała cena** – niesamowita wartość za tak wysoką jakość\n- **Bezpośrednio od producenta** – gwarancja autentyczności i świeżości\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Waga netto** | 360g |\n| **Cena** | 32,33 PLN |\n| **Opakowanie** | Hermetyczne, chroniące świeżość |\n| **Pochodzenie** | Polska, tradycyjny przepis |\n\n---\n\n**Nie czekaj dłużej!** Mieszanka Węglowska 360g czeka na Ciebie w naszym sklepie. Dodaj produkt do koszyka już teraz i ciesz się autentycznym smakiem za niepowtarzalną cenę. To propozycja, która na pewno Ci się spodoba – albo zwrócimy każdy złoty! Zamawiaj dziś i odkryj, dlaczego tysiące zadowolonych klientów powraca po więcej. 🛒✨', '32.33', '0.39', 1, 1, 'mieszanka-wedlowska-360g', '2023-07-20 00:00:00'),
(21, 'Kamera IP Hikvision 4MP', 'BEZ-00021', '## Kamera IP Hikvision 4MP\n\nProfesjonalna kamera IP Hikvision to idealne rozwiązanie dla każdego, kto pragnie zapewnić sobie pełny monitoring swojej nieruchomości, działalności biznesowej lub obiektu wartościowego. Dzięki zaawansowanej technologii transmisji sieciowej oraz wysokiej rozdzielczości 4MP, uzyskasz krystalicznie czystą jakość obrazu zarówno w dzień, jak i w nocy. Kamera sprawdzi się zarówno w systemach domowych, jak i profesjonalnych instalacjach komercyjnych – jej wszechstronność i niezawodność czynią ją wyborem wielu instalatorów na całej Polsce.\n\nUrządzenie wyróżnia się lekką obsługą i integracją z istniejącymi systemami monitoringu. Hikvision to marka zaufana na całym świecie, która gwarantuje najwyższą jakość wykonania i trwałość. Kamera IP zachowuje stabilne połączenie sieciowe nawet w trudnych warunkach, a jej kompaktowa obudowa pozwala na dyskretne umieszczenie w każdym miejscu. Dzięki możliwości zasilania przez PoE (Power over Ethernet) instalacja staje się niezwykle prosta i ekonomiczna – wystarczy jeden kabel do przesyłania zarówno danych, jak i zasilania.\n\nNiezależnie od tego, czy zabezpieczasz dom, sklep, magazyn czy parking – ta kamera IP Hikvision zapewni Ci całodobowy monitoring z wyjątkową ostrością obrazu. Dzięki doskonałym parametrom techniczne i konkurencyjnej cenie, stanowi najlepszy stosunek jakości do wydatku. Zadbaj o bezpieczeństwo swoich najbliższych i mienia już teraz, wybierając sprawdzone rozwiązanie od światowego lidera w branży systemów monitoringu.\n\n### Kluczowe cechy\n\n- 📷 **Rozdzielczość 4MP** – ostry obraz zarówno w dzień jak i w nocy, idealna do identyfikacji osób i pojazdów\n- 🌐 **Transmisja IP** – łatwa integracja z sieciami Ethernet, dostęp zdalny przez internet\n- ⚡ **Zasilanie PoE** – uproszczona instalacja dzięki zasilaniu przez jeden kabel sieciowy\n- 🔒 **Bezpieczeństwo dane** – szyfrowanie transmisji i obsługa standardowych protokołów\n- 🌙 **Funkcja noktowizyjna** – praktycznie bezstratny monitoring w warunkach słabego oświetlenia\n- 💼 **Uniwersalne zastosowanie** – idealna dla domu, biura, sklepu, magazynu czy parkingu\n- ✅ **Marka renomowana** – gwarancja jakości i niezawodności od producenta o światowym uznaniu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Rozdzielczość | 4MP (2688 x 1520) |\n| Typ połączenia | IP (Ethernet RJ-45) |\n| Zasilanie | PoE 802.3af/at |\n| Widzenie nocne | TAK (IR LED) |\n| Obudowa | Metalowa, kompaktowa |\n\n---\n\n**Nie czekaj dłużej!** Kamera IP Hikvision 4MP w cenie zaledwie **141,06 PLN** to okazja, którą trudno przejść obojętnie. Zapewniająca profesjonalną jakość monitoringu, łatwą instalację i niezawodność przez lata – to inwestycja, która się opłaca. Dodaj do koszyka już teraz i zyskaj pełną kontrolę nad bezpieczeństwem! Wysyłka w 24h, gwarancja producenta i gwarancja satysfakcji od nas.', '141.06', '4.55', 2, 1, 'kamera-ip-hikvision-4mp', '2023-10-29 00:00:00'),
(22, 'Czujnik dymu FireAngel', 'BEZ-00022', '## Czujnik Dymu FireAngel – Niezawodna Ochrona Twojego Domu i Rodziny\n\n### Profesjonalna Ochrona Przed Zagrożeniem Pożarem\n\nCzujnik dymu FireAngel to niezawodny, profesjonalny system detekcji dymu, który stanowi niezbędny element bezpieczeństwa każdego domu, mieszkania czy małej firmy. Urządzenie zostało zaprojektowane z myślą o maksymalnej efektywności i łatwości obsługi, aby zapewnić Ci i Twojej rodzinie spokojny sen i poczucie bezpieczeństwa przez całą dobę. Czujnik wykorzystuje zaawansowaną technologię optyczną do wczesnego wykrywania dymu, reagując błyskawicznie na pierwsze oznaki zagrożenia.\n\nMontaż urządzenia jest niezwykle prosty – wystarczy wybrać odpowiednie miejsce (najlepiej blisko potencjalnych źródeł ognia, takich jak kuchnia czy salon) i przymocować czujnik do sufitu lub ściany. Dzięki inteligentnym algorytmom FireAngel minimalizuje liczbę fałszywych alarmów, które mogą być uciążliwe w codziennym użytkowaniu. Jednocześnie urządzenie nie traci na czujności – każdy dym zostanie szybko wykryty i zasygnalizowany hałasną syreną ostrzegającą.\n\nInwestycja w czujnik dymu FireAngel to inwestycja w życie. Statystycznie pokazuje się, że działające czujniki dymu zwiększają szanse przeżycia w przypadku pożaru nawet o 50%. To urządzenie może okazać się tym jedynym, które da Ci i Twoim bliskim chwilę na bezpieczną ewakuację. Za cenę zaledwie **1341.55 PLN** otrzymujesz wieloletni spokój ducha i profesjonalną ochronę – inwestycję, która nie ma ceny.\n\n### Kluczowe cechy\n\n- **Zaawansowana detekcja optyczna** – system wykrywania dymu oparty na optycznym czujniku dymu, reagujący na pierwsze oznaki zagrożenia pożarowego\n- **Głośny alarm dźwiękowy** – sygnał ostrzegawczy o mocy co najmniej 85 dB, słyszalny nawet w głębokim śnie\n- **Minimalizacja fałszywych alarmów** – inteligentna elektronika odróżniająca dym pożarowy od zwykłych oparów kuchni\n- **Bateria o długim czasie działania** – zasilanie bateryjne zapewniające nieprzerwany monitoring przez miesiące\n- **Łatwa instalacja** – prosty montaż na suficie lub ścianie, nie wymaga specjalistów\n- **Kompaktowy design** – dyskretny wygląd, który nie psuje estetyki wnętrza\n- **Certyfikacja i normy bezpieczeństwa** – spełnia międzynarodowe standardy bezpieczeństwa\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Typ detekcji** | Optyczna (fotoelektyczna) |\n| **Poziom alarmu** | Powyżej 85 dB |\n| **Zasilanie** | Bateria (typ zależny od modelu) |\n| **Czas działania baterii** | Do 12 miesięcy |\n| **Wymiary** | ~100 mm (średnica), ~40 mm (wysokość) |\n| **Certyfikaty** | CE, normy europejskie ds. bezpieczeństwa |\n\n---\n\n### Bezpieczeństwo to Podstawa\n\nFireAngel to marka z ponad 20-letnim doświadczeniem w branży bezpieczeństwa pożarowego. Miliony ludzi na całym świecie powierza swoją bezpieczeństwo czujnikom tej marki. Nie czekaj na nieszczęście – zadbaj o ochronę swojego domu już dziś! Czujnik dymu FireAngel za **1341.55 PLN** to inwestycja, która może uratować życie. Dodaj do koszyka teraz i zadbaj o bezpieczeństwo swoich bliskich.', '1341.55', '4.19', 2, 1, 'czujnik-dymu-fireangel', '2024-04-22 00:00:00'),
(23, 'Zamek Yale Smart Lock', 'BEZ-00023', '## Zamek Yale Smart Lock - Inteligentny Zamek do Drzwi\n\n**Nowoczesne zabezpieczenie, które zmienia sposób korzystania z domowego bezpieczeństwa.** Zamek Yale Smart Lock to rewolucyjna kombinacja zaawansowanej technologii i niezawodności, którą znamy od ponad 170 lat z produktów Yale. Zapomni o tradycyjnych kluczach! Ten inteligentny zamek pozwala na otwarcie drzwi za pomocą smartfonu, karty dostępu lub starożytnego jeszcze kodu PIN. Montaż odbywa się bez konieczności wymiany istniejącego zamka – wystarczy zainstalować urządzenie na wewnętrznej stronie drzwi w zaledwie kilka minut. Yale Smart Lock to idealny wybór dla osób, które cenią sobie nowoczesność, wygodę i bezpieczeństwo w jednym pakiecie.\n\nInteligentny zamek Yale świetnie sprawdza się zarówno w mieszkaniach, domach jednorodzinnych, jak i biurach. Kontrolujesz dostęp z dowolnego miejsca na świecie – sprawdzaj historię wejść i wyjść, udzielaj czasowego dostępu gościom, a także automatycznie otwieraj drzwi dzieciom lub pracownikom. System integruje się z najpopularniejszymi platformami smart home, takimi jak Apple HomeKit, Google Home i Amazon Alexa. Dzięki zaawansowanym algorytmom bezpieczeństwa i szyfrowanej komunikacji możesz być pewien, że Twój dom jest rzeczywiście bezpieczny. Yale Smart Lock to inwestycja w komfort życia i spokój ducha.\n\nZaawansowana bateryjność zamka (ponad 1 rok na jednym zestawie baterii AA) oraz możliwość podłączenia do zasilania sieciowego gwarantują niezawodność urządzenia. Dzięki czujnikom ruchu i inteligentnym powiadomieniom zawsze wiesz, czy drzwi są otwarte, a nieautoryzowane próby dostępu natychmiast Cię powiadomią. Elegant i minimalistyczny design zamazka harmonijnie wpisuje się w każdy styl wnętrza – od klasycznego do nowoczesnego.\n\n### Kluczowe cechy:\n\n- 🔐 **Otwieranie przez aplikację mobilną** – Kontrola zamka z poziomu smartfonu z dowolnego miejsca na świecie\n- 🔑 **Wieloznak dostępu** – Kod PIN, karta dostępu lub klucz tradycyjny – wybierasz metodę najwygodniejszą\n- 📱 **Integracja z HomeKit, Google Home, Alexa** – Kompatybilność z najpopularniejszymi ekosystemami smart home\n- 🔋 **Długa żywotność baterii** – Do 1 roku pracy na zestawie baterii AA (4 szt.)\n- 📊 **Historia dostępu i powiadomienia real-time** – Śledzenie wszystkich prób otwarcia drzwi\n- 🛡️ **Zaawansowane szyfrowanie** – Bezpieczna komunikacja Bluetooth i obsługa SSL\n- 💡 **Łatwa instalacja** – Montaż na wewnętrznej stronie drzwi bez wymiany istniejącego zamka\n\n### Specyfikacja:\n\n| Parametr | Wartość |\n|----------|---------|\n| **Marka** | Yale |\n| **Model** | Smart Lock |\n| **Zasilanie** | Baterie AA (4 szt.) / opcja zasilania sieciowego |\n| **Kompatybilność** | iOS, Android, HomeKit, Google Home, Alexa |\n| **Wymiary** | 80 x 80 x 23 mm |\n| **Materiał** | Stal nierdzewna + poliwęglan |\n\n---\n\n**Nie czekaj dłużej na przyszłość domowego bezpieczeństwa!** Yale Smart Lock za przystępną cenę **1147,16 PLN** daje Ci możliwości, o których marzysz. Efektywnie zarządzaj dostępem do swojego domu, biura lub wynajmowanego mieszkania. Zamek Yale Smart Lock to gwarancja bezpieczeństwa, wygody i nowoczesności. **Zamów teraz i ciesz się inteligentnymi drzwiami już jutro!**', '1147.16', '4.60', 2, 1, 'zamek-yale-smart-lock', '2024-05-26 00:00:00'),
(24, 'Alarm Satel Integra 32', 'BEZ-00024', '## Alarm Satel Integra 32 - Profesjonalny System Zabezpieczenia\n\nSatel Integra 32 to nowoczesny, niezawodny system alarmowy, który stanowi idealne rozwiązanie do ochrony domu, biura, magazynu lub małego obiektu użyteczności publicznej. Urządzenie łączy zaawansowaną technologię z intuicyjną obsługą, gwarantując maksymalny poziom bezpieczeństwa Twoich pomieszczeń 24/7. Dzięki kompaktowym wymiarom i stylowemu designowi, centralka bez problemu zmieści się w każdym wnętrzu, nie psując estetyki wystroju.\n\nSystem Integra 32 pozwala na podłączenie i zarządzanie 32 strefami alarmowymi, co daje ogromną elastyczność przy planowaniu zainstalowania czujników ruchu, kontaktronów, detektorów dymu czy innych urządzeń zabezpieczających. Urządzenie wyposażone jest w niezawodne łącze komunikacyjne, które zapewnia natychmiastowe powiadomienie o jakichkolwiek zagrożeniach. Alarm pracuje niezawodnie w każdych warunkach, od mroźnych zimowych nocy po upalnych letnich dni, zapewniając stałą czujność i ochronę.\n\nMontaż i konfiguracja Satel Integra 32 jest niezwykle prosta, a obsługa intuicyjna - wystarczy kilka minut, aby system był w pełni operacyjny. Centralka kompatybilna jest z szeroką gamą czujników i akcesoriów marki Satel, a także obsługuje popularne protokoły komunikacyjne. Inwestycja w ten system to gwarancja spokojnego snu i pewności, że Twój majątek jest pod stałą ochroną profesjonalnego urządzenia zabezpieczającego najwyższej klasy.\n\n### Kluczowe cechy\n\n- **32 strefy alarmowe** - możliwość rozbudowy systemu i obsługi licznych czujników w różnych lokalizacjach\n- **Niezawodna komunikacja** - szybkie powiadomienie o wszelkich anomaliach i zagrożeniach\n- **Zasilanie awaryjne** - bateria zapasowa gwarantuje pracę systemu nawet podczas przerwy w zasilaniu\n- **Intuicyjny interfejs** - łatwa obsługa dla użytkowników o różnych umiejętnościach technicznych\n- **Kompaktowe wymiary** - elegancka, niewielka centralka nie zajmuje dużo miejsca\n- **Szeroka kompatybilność** - współpraca z bogatą ofertą czujników i akcesoriów Satel\n- **Niezawodność i trwałość** - sprawdzony system o wieloletniej historii na rynku bezpieczeństwa\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Liczba stref | 32 |\n| Zasilanie | 230V AC / bateria zapasowa |\n| Wymiary | Kompaktowe, montaż ścienny |\n| Kompatybilność | Czujniki i akcesoria Satel |\n| Gwarancja | Zgodnie z warunkami producenta |\n\n**Cena: 1402,86 PLN**\n\n---\n\n### Podsumowanie\n\nAlarm Satel Integra 32 to inwestycja w pewność i spokój ducha. Profesjonalny system zabezpieczenia, łatwy w instalacji i obsłudze, zapewni Ci i Twojej rodzinie pełne bezpieczeństwo. Nie zwlekaj - złóż zamówienie dziś i zyskaj niezawodną ochronę swojego domu lub biura. Wielka liczba zadowolonych użytkowników w całej Polsce potwierdza wysoką jakość tego produktu. **Zamów teraz za 1402,86 PLN i ciesz się bezpieczeństwem!**', '1402.86', '3.13', 2, 1, 'alarm-satel-integra-32', '2023-12-22 00:00:00'),
(25, 'Kamera cofania Tracer', 'BEZ-00025', '## Kamera cofania Tracer - Niezawodna asystentka parkowania\n\nKamera cofania Tracer to nowoczesne rozwiązanie dla każdego kierowcy, który ceni sobie bezpieczeństwo i komfort podczas manewrów wstecznych. Urządzenie wyposażone w wysokiej jakości sensor obrazu zapewnia doskonałą widoczność wszystkiego, co znajduje się za pojazdem, eliminując martwe punkty i znacznie zmniejszając ryzyko wypadku. Idealna dla osób parkujących w ciasnych przestrzeniach, jazdy w ruchu drogowym lub kierowców mających problem z oceną odległości. Kamera seamlessly integruje się z systemem multimediów pojazdu, wyświetlając obraz na wyświetlaczu radia lub centralnego panelu sterowania.\n\nMontaż kamery Tracer jest prosty i nie wymaga skomplikowanych prac instalacyjnych. Urządzenie charakteryzuje się solidną konstrukcją odporną na warunki atmosferyczne - deszcz, śnieg, brud i wysokie temperatury nie stanowią dla niej problemu. Zaawansowana technologia noktowizyjna pozwala na korzystanie z kamery także w warunkach słabego oświetlenia, zapewniając wyraźny obraz zarówno w dzień, jak i w nocy. To inwestycja w bezpieczeństwo Twoje i Twoich bliskich, która szybko się zwraca dzięki uniknięciu potencjalnych uszkodzeń pojazdu.\n\nKamera cofania Tracer to połączenie nowoczesnej technologii z praktycznym zastosowaniem. Niezależnie od tego, czy jesteś początkującym kierowcą, czy doświadczonym profesjonalistą - urządzenie ułatwi Ci parkowanie, skręcanie na podjeździe czy wjazdy na ciasne miejsca parkingowe. Obraz jest wyraźny, kontrast doskonały, a całość zapewnia całkowitą pewność podczas manewrów wstecznych. To rozwiązanie, które już teraz powinno być standardem w każdym samochodzie.\n\n### Kluczowe cechy\n\n- **Wysoka rozdzielczość obrazu** - wyraźny, szczegółowy obraz w HD zapewniający doskonałą widoczność\n- **Widzenie nocne (noktowizja)** - zaawansowana technologia umożliwiająca pracę w warunkach słabego oświetlenia\n- **Odporność na warunki atmosferyczne** - obudowa IP67 chroni urządzenie przed deszczem, śniegiem i zanieczyszczeniami\n- **Szeroki kąt widzenia** - do 170°, eliminujący martwe punkty i pokazujący szeroki obszar za pojazdem\n- **Łatwy montaż** - uniwersalna instalacja bez konieczności demontażu tylnego zderzaka\n- **Kompatybilność** - współpracuje z większością systemów multimedialnych i radia samochodowego\n- **Solidna konstrukcja** - trwałe materiały gwarantujące długoletnie bezawaryjne działanie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Rozdzielczość** | 720p HD |\n| **Kąt widzenia** | 170° |\n| **Zasilanie** | 12V DC |\n| **Odporność** | IP67 (wodoszczelna) |\n| **Temperatura pracy** | -10°C do +60°C |\n\n---\n\n## Dlaczego warto wybrać kamerę cofania Tracer?\n\nBezpieczeństwo na drodze nie jest towarem luksusowym - to konieczność. Kamera cofania Tracer to inwestycja, która ochroni Twój pojazd i zapewni Ci spokój ducha podczas każdego manewru wstecznego. Za zaledwie **534,96 PLN** otrzymujesz profesjonalne urządzenie o jakości porównywalnej z wiele droższymi systemami. Montaż zajmie Ci ledwie kilkanaście minut, a korzyści będziesz odczuwać każdego dnia.\n\nNie czekaj na najbliższy niebezpieczny manewr - zadbaj o swoje bezpieczeństwo już teraz. Kamera Tracer czeka na Ciebie w naszym sklepie. **Zamów dzisiaj i ciesz się pełnym komfortem parkowania!**', '534.96', '0.71', 2, 1, 'kamera-cofania-tracer', '2023-10-22 00:00:00'),
(26, 'Gaśnica proszkowa 2kg', 'BEZ-00026', '## Gaśnica proszkowa 2kg - Niezawodna ochrona przed pożarem\n\nGaśnica proszkowa 2kg to uniwersalne urządzenie gaśnicze, które powinno znaleźć się w każdym domu, garażu, biurze czy pojeździe. Dzięki zaawansowanej formule proszku uniwersalnego, skutecznie gasi pożary klas A, B i C, zapewniając bezpieczeństwo Tobie i Twoim bliskim. Wysoka wydajność gaśnicza w kompaktowym, łatwo dostępnym formacie czyni ten produkt idealnym rozwiązaniem do szybkiego reagowania w sytuacjach zagrożenia.\n\nNaszą gaśnicę wyróżnia nowoczesna konstrukcja z precyzyjnym systemem rozpylania oraz ergonomiczna rękojeść, umożliwiająca bezpieczne i wygodne użycie nawet osobom bez wcześniejszego doświadczenia. Proszek gaśniczy o wydajności 2kg zapewnia wystarczający czas działania do opanowania pożaru w fazie początkowej. Produkt posiada czytelny manometr ciśnienia, dzięki czemu zawsze wiesz, że gaśnica jest w pełnej gotowości do działania. Elegancki design sprawia, że gaśnica harmonijnie pasuje do wnętrza każdego pomieszczenia.\n\nRegularna kontrola i okresowa konserwacja gaśnicy to kluczowe elementy bezpieczeństwa. Produkt dostępny w naszym sklepie spełnia wszystkie normy bezpieczeństwa i pochodzi od zaufanych producentów gwarantujących najwyższą jakość. Inwestycja w gaśnicę to inwestycja w spokój i ochronę - cena 1159.37 PLN to niewielki koszt dla zapewnienia bezpieczeństwa.\n\n### Kluczowe cechy\n\n- **Uniwersalna klasa gaszenia** - Skutecznie gasi pożary klas A (materiały stałe), B (ciecze łatwopalne) i C (gazy)\n- **Pojemność 2kg** - Kompaktowa, łatwa do przenoszenia, idealna do zastosowań domowych i biurowych\n- **System rozpylania** - Precyzyjny rozpylacz zapewniający równomierny rozkład proszku gaśniczego\n- **Manometr ciśnienia** - Wyraźny wskaźnik umożliwiający szybką ocenę gotowości urządzenia\n- **Certyfikacja i normy** - Produkt spełnia normy europejskie dotyczące gaśnic proszkowych\n- **Łatwa obsługa** - Intuicyjny system zapalnika, obsługiwany bez specjalnego szkolenia\n- **Trwała konstrukcja** - Odporny na korozję, wytrzymały korpus gwarantujący długoletnie użytkowanie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Typ gaśnicy | Proszkowa uniwersalna |\n| Pojemność | 2 kg |\n| Klasy pożaru | A, B, C |\n| Zasięg strumienia | Ok. 3-4 metry |\n| Czas działania | Do 20 sekund |\n| Cena | 1159.37 PLN |\n\n---\n\n**Bezpieczeństwo to priorytet!** Nie czekaj na niebezpieczną sytuację - zaopatrz się w gaśnicę proszkową 2kg już dziś. Dzięki uniwersalności i niezawodności, będziesz pewny, że masz pod ręką sprawdzony sprzęt do walki z pożarem. Zamów teraz i otrzymaj spokój ducha dla siebie i swojej rodziny. **Cena 1159.37 PLN to inwestycja w bezpieczeństwo - nie oszczędzaj na tym, co ważne!**', '1159.37', '0.65', 2, 1, 'gasnica-proszkowa-2kg', '2023-12-28 00:00:00'),
(27, 'Czujnik ruchu PIR Bosch', 'BEZ-00027', '## Czujnik ruchu PIR Bosch - Profesjonalna ochrona i automatyka\n\nCzujnik ruchu PIR firmy Bosch to niezawodne urządzenie, które idealnie sprawdzi się zarówno w systemach alarmowych, jak i w instalacjach automatyki budynkowej. Dzięki zaawansowanej technologii wykrywania ruchu na podczerwień, urządzenie niezwykle precyzyjnie rejestruje każdy ruch w zasięgu detektora. Bosch to gwarancja najwyższej jakości i niezawodności — marka zaufana przez profesjonalistów w całym świecie. Ten czujnik to inwestycja w bezpieczeństwo Twojego domu, biura lub magazynu na wiele lat.\n\nCzujnik ruchu PIR Bosch oferuje niezwykłą czułość i odporność na fałszywe alarmy dzięki inteligentnym algorytmom filtracji. Reaguje natychmiast na każdą zmianę w polu widzenia, zapewniając rzeczywistą ochronę 24/7. Instalacja jest niezwykle prosta i intuicyjna — urządzenie można umieścić praktycznie w każdym pomieszczeniu. Czujnik pracuje w każdych warunkach oświetleniowych, zarówno w całkowitej ciemności, jak i przy silnym oświetleniu słonecznym.\n\nTo urządzenie świetnie sprawdza się nie tylko w systemach bezpieczeństwa. Możesz go wykorzystać do automatycznego włączania oświetlenia w garażu, klatce schodowej, łazience czy magazynie. Dzięki niskiemu poboru energii oraz długiemu czasowi działania, czujnik działa bez przeszkód przez wiele lat. Kompatybilność z popularnymi systemami alarmowymi i automatyki budynkowej czyni go uniwersalnym rozwiązaniem dla każdego.\n\n### Kluczowe cechy\n\n- **Technologia PIR** — precyzyjne wykrywanie ruchu na podczerwień z minimalnym opóźnieniem\n- **Szeroki zasięg detektora** — skutecznie monitoruje duże powierzchnie pomieszczeń\n- **Odporność na fałszywe alarmy** — zaawansowana filtracja eliminuje fałszywych trików\n- **Niezawodność Bosch** — gwarancja najwyższej jakości i trwałości urządzenia\n- **Łatwa instalacja** — prosty montaż ścienną lub sufitowy bez konieczności profesjonalnej obsługi\n- **Niski pobór energii** — długo działające baterie lub zasilanie sieciowe\n- **Uniwersalna kompatybilność** — działa z większością systemów alarmowych na rynku\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Producent | Bosch |\n| Typ czujnika | PIR (podczerwień) |\n| Cena | 52,34 PLN |\n| Zasięg detektora | Do 12 metrów |\n| Kąt widzenia | 120° |\n| Zasilanie | Baterie AA lub zasilanie 12V DC |\n\n---\n\n**Zamów teraz i zyskaj pewność, że Twoja nieruchomość jest chroniona najlepszą dostępną technologią!** Czujnik ruchu PIR Bosch to małe urządzenie, które zapewnia maksimum spokoju. Niezależnie od tego, czy chodzi Ci o bezpieczeństwo czy wygodę, ten niezawodny czujnik spełni Twoje oczekiwania. Dołącz do tysięcy zadowolonych klientów i zadbaj o ochronę już dziś — za zaledwie **52,34 PLN** masz dostęp do profesjonalnego rozwiązania Bosch!', '52.34', '0.31', 2, 1, 'czujnik-ruchu-pir-bosch', '2023-10-05 00:00:00'),
(28, 'Domofon Commax CDV-43K', 'BEZ-00028', '## Domofon Commax CDV-43K – Profesjonalny System Wideodomofonu do Twojego Domu\n\n**Nowoczesna kontrola i bezpieczeństwo na wyciągnięcie ręki**\n\nDomofon Commax CDV-43K to zaawansowany system wideodomofonu, który łączy funkcjonalność z eleganckim designem. Urządzenie zostało opracowane dla osób, które cenią sobie bezpieczeństwo, wygodę i niezawodność. Monitor 4,3 cala z wyświetlaczem LCD zapewnia doskonałą widoczność, niezależnie od warunków oświetlenia w Twojej przestrzeni mieszkalnej. System idealnie sprawdza się zarówno w domach jednorodzinnych, jak i w apartamentach czy budynkach mieszkalnych, gdzie bezpieczna komunikacja z odwiedzającymi jest kluczowa.\n\n**Funkcjonalność i praktyczne zastosowanie**\n\nCommax CDV-43K oferuje intuicyjny interfejs, który każdy członek rodziny będzie w stanie obsługiwać bez problemu. Kamera nocna zapewnia doskonałą jakość obrazu nawet w ciemnych warunkach, co stanowi dodatkową warstwę bezpieczeństwa dla Twojego domu. Dzięki czystemu dźwiękowi i ostrej transmisji wideo możesz w pełni kontrolować, kto przychodzi do Twojej bramy, zanim otworzysz drzwi. Urządzenie współpracuje z innymi komponentami systemu Commax, co umożliwia rozbudowę instalacji w miarę potrzeb. To inwestycja w spokój ducha Twojej rodziny na lata.\n\n**Montaż i kompatybilność**\n\nSystem montuje się łatwo na ścianie wewnątrz pomieszczeń. Commax CDV-43K charakteryzuje się przystępną ceną przy wysokiej jakości wykonania, co czyni go popularnym wyborem konsumentów szukających dobrego stosunku ceny do jakości. Urządzenie jest całkowicie kompatybilne z bramkami wideo Commax, umożliwiając pełną integrację systemu bezpieczeństwa w Twoim domu.\n\n### Kluczowe cechy\n\n- 📺 **Wyświetlacz LCD 4,3 cala** – wyraźny obraz o wysokiej rozdzielczości\n- 🌙 **Funkcja noktowizyjna (IR)** – doskonały wgląd w słabych warunkach oświetlenia\n- 🔊 **Dwukierunkowy system dźwięku** – wyraźna komunikacja z osobą przy bramce\n- 🎚️ **Intuicyjny interfejs użytkownika** – obsługa bez żadnych skomplikowanych ustawień\n- 🔌 **Szeroka kompatybilność** – współpraca z wieloma modelami bramek Commax\n- 🖼️ **Elegancki design** – urządzenie wpisuje się w nowoczesne wnętrza\n- 🔒 **Wysokie standardy bezpieczeństwa** – niezawodna ochrona Twojego domu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Ekran** | LCD 4,3 cala (16:9) |\n| **Rozdzielczość** | 480 × 272 pikseli |\n| **Funkcja noktowizyjna** | Tak (IR LED) |\n| **Zasilanie** | 12V/24V AC/DC |\n| **Wymiary** | ~185 × 115 × 20 mm |\n\n### Podsumowanie i zachęta do zakupu\n\nDomofon Commax CDV-43K to doskonały wybór dla każdego, kto pragnie podnieść bezpieczeństwo i wygodę swojego domu na nowy poziom. Za zaledwie **1388,93 PLN** zyskujesz niezawodny system wideodomofonu od zaufanego producenta, który od lat specjalizuje się w rozwiązaniach bezpieczeństwa. Dzisiejsza oferta to inwestycja w spokój i ochronę Twojej rodziny. Dodaj do koszyka teraz i ciesz się pełną kontrolą nad tym, co dzieje się przed Twoimi drzwiami!\n\n**Zamów dzisiaj i otrzymaj pewność, że Twój dom jest bezpieczny.** 🏡✨', '1388.93', '2.41', 2, 1, 'domofon-commax-cdv-43k', '2023-07-07 00:00:00'),
(29, 'Sejf elektroniczny Yale', 'BEZ-00029', '## Sejf elektroniczny Yale — Niezawodna ochrona Twoich cennych rzeczy\n\nSejf elektroniczny Yale to idealne rozwiązanie dla osób, które chcą zapewnić bezpieczeństwo swoim cennościom, dokumentom, biżuterii i innym wartościowym przedmiotom. Nowoczesny system elektroniczny, połączony z solidną konstrukcją, gwarantuje, że tylko osoba posiadająca hasło będzie miała dostęp do zawartości. Yale to marka o wieloletniej tradycji w branży zabezpieczeń, zaufana przez miliony użytkowników na całym świecie. Sejf ten doskonale sprawdzi się zarówno w domu, jak i w biurze czy na terenie firmy.\n\nDzięki kompaktowym wymiarom sejf łatwo zmieści się w szafie, biurku lub kącie pokoju, a jednocześnie zapewnia pojemność wystarczającą do przechowywania dokumentów, pieniędzy gotówki, kluczy, paszportów czy cennych pamiątek. Elektroniczny system dostępu eliminuje konieczność przechowywania kluczy — wystarczy zapamiętać bezpieczny kod dostępu. Solidna stal, z której wykonany jest sejf, stanowi efektywną barierę dla potencjalnych złodziei, a połysk metaliczny nadaje produktowi elegancki wygląd pasujący do każdego wnętrza.\n\nObsługa sejfu Yale jest intuicyjna i niezawodna. Po wprowadzeniu prawidłowego kodu na klawiaturze elektronicznej zamek automatycznie się odblokowuje, dając dostęp do wnętrza. Sejf posiada zasilanie bateryjne, co gwarantuje jego funkcjonalność przez długi czas bez konieczności podłączania do prądu. W razie zapomnienia kodu przewidziane są procedury awaryjne umożliwiające odblokowanie sejfu. Idealny sprawdzian jako prezent dla osoby, która ceni bezpieczeństwo i porządek w swoim domu.\n\n### Kluczowe cechy\n\n- 🔐 **Elektroniczny system zamka** — bezpieczny kod dostępu zamiast tradycyjnych kluczy\n- 💾 **Solidna obudowa ze stali** — wytrzymała konstrukcja odporająca na włamania i uderzenia\n- ⚡ **Zasilanie bateryjne** — autonomiczna praca bez potrzeby podłączania do sieci elektrycznej\n- 📏 **Kompaktowe wymiary** — łatwe umieszczenie w domu lub biurze bez zajmowania zbyt dużo miejsca\n- 🔋 **Wskaźnik stanu baterii** — powiadomienie o konieczności wymiany baterii\n- 🎯 **Łatwa obsługa** — intuicyjny interfejs dostępny dla każdego użytkownika\n- 🛡️ **Gwarancja producenta** — pewność solidności i trwałości produktu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|---|---|\n| Marka | Yale |\n| Typ zamka | Elektroniczny z kodem PIN |\n| Materiał obudowy | Stal |\n| Zasilanie | 4 baterie AA |\n| Pojemność | Do 12 litrów |\n\n---\n\n**Nie czekaj dłużej!** Sejf elektroniczny Yale w cenie **837,80 PLN** to inwestycja w spokój i bezpieczeństwo. Chroń to, co dla Ciebie najważniejsze, przed nieuprawnionym dostępem. Zamów teraz i ciesz się poczuciem bezpieczeństwa każdego dnia! ✅', '837.80', '2.04', 2, 1, 'sejf-elektroniczny-yale', '2023-10-15 00:00:00'),
(30, 'Atrapa kamery CCTV', 'BEZ-00030', '## 🎥 Atrapa Kamery CCTV\n\nSzukasz efektywnego i ekonomicznego sposobu na zwiększenie bezpieczeństwa Twojej posesji? **Atrapa kamery CCTV** to doskonałe rozwiązanie dla każdego, kto chce odstraszać potencjalnych włamywaczy bez dużych inwestycji. Ta realistycznie wyglądająca kamera pozorna stanowi widoczny element systemu bezpieczeństwa, który z daleka przypomina profesjonalne urządzenia monitorujące. Jej nowoczesny design oraz solidne wykonanie powodują, że laik nie potrafi rozróżnić jej od prawdziwej kamery. Idealna zarówno dla domów, jak i małych sklepów, magazynów czy biur.\n\nGłównym atutem atrap kamer CCTV jest ich zdolność do psychologicznego odstraszenia potencjalnych złodziei. Badania wykazują, że obecność widocznego systemu monitoringu zmniejsza chęć do popełnienia kradzieży o ponad 70%. Nie musisz wydawać tysięcy złotych na zainstalowanie pełnego systemu kamer — nasza atrapa podziała tak samo skutecznie, a przy tym jest o wiele bardziej przystępna cenowo. Produkt jest niezawodny, nie wymaga zasilania elektrycznego (lub wymagane jest minimalnie do diod LED) i nie generuje żadnych kosztów operacyjnych.\n\nCzy montaż pod stropem, na ścianie czy w rogu budynku — wszędzie będzie wyglądać profesjonalnie. Zastosuj atrapę kamery CCTV na terenie Twojej nieruchomości, a otrzymasz spokój i poczucie bezpieczeństwa. To prosty, ale skuteczny sposób na ochronę mienia bez konieczności inwestowania w drogi sprzęt elektroniczny.\n\n### 🎯 Kluczowe cechy\n\n- **Realistyczny wygląd** — identyczna jak prawdziwa kamera CCTV, trudna do odróżnienia\n- **Ochrona bez kosztów operacyjnych** — nie wymaga zasilania sieciowego ani abonamentu\n- **Uniwersalne zastosowanie** — idealna dla domów, mieszkań, sklepów, magazynów i biur\n- **Łatwy montaż** — szybkie i proste zainstalowanie na dowolnej powierzchni\n- **Psychologiczne odstraszanie** — widoczna obecność zmniejsza chęć do kradzieży\n- **Wytrzymała konstrukcja** — solidne materiały zapewniające długotrwałą eksploatację\n- **Mała cena przy dużej efektywności** — inwestycja, która się opłaca\n\n### 📋 Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Typ produktu** | Atrapa kamery CCTV |\n| **Wymiary** | Standardowe (zgodne z profesjonalnym sprzętem) |\n| **Zasilanie** | Bez zasilania (opcjonalnie: baterie AA do diod LED) |\n| **Cena** | 209,65 PLN |\n| **Gwarancja** | Zgodnie z polityką sklepu |\n\n---\n\n**Postaw na bezpieczeństwo, wybierz rozsądnie!** 🛡️\n\nNie czekaj na problemy — zainstaluj atrapę kamery CCTV już dzisiaj i ciesz się pełnym spokojem ducha. Za niespełna 210 złotych otrzymasz niezawodną ochronę i widoczny symbol bezpieczeństwa, który będzie stanowić doskonałe odstręczenie dla potencjalnych złodziei. **Kup teraz i zabezpiecz swoją nieruchomość!**', '209.65', '3.92', 2, 1, 'atrapa-kamery-cctv', '2023-06-17 00:00:00'),
(31, 'Kłódka ABUS Granit', 'BEZ-00031', '## 🔒 Kłódka ABUS Granit - Najwyższej Klasy Bezpieczeństwo Dla Twojego Mienia\n\n### Opis Produktu\n\nKłódka ABUS Granit to gwarancja bezpieczeństwa na najwyższym poziomie. Wykonana z zachodnioeuropejskiego rzemiosła, przeszła surowe testy wytrzymałości i odporności na ataki. Ta kłódka to wybór profesjonalistów, którzy wiedzą, że bezpieczeństwo nie ma ceny. Solidna konstrukcja, najwyższe materiały i perfekcyjne wykończenie sprawiają, że Granit jest niezawodnym obrońcem Twojego roweru, motocykla lub skutera przez wiele lat.\n\nWyjątkowa odporność na włamania jest wynikiem starannego procesu produkcji i zastosowania specjalnej stali hartowanej. Kłódka ABUS Granit nie podda się przecinarkom, młotkom ani innym popularnym narzędziom złodziei. Kompaktowe wymiary i niska waga ułatwiają transport, a elegancki design pas do każdego rodzaju pojazdu. Niezależnie od warunków pogodowych – deszcz, śnieg, mróz czy żar słońca – Granit zachowuje swoją niezawodność i estetykę.\n\nWybierając kłódkę ABUS Granit, inwestujesz w długoterminową ochronę i spokój ducha. Gwarancja producenta, renomowana marka znana od ponad 100 lat i opinie tysiącletek zadowolonych użytkowników potwierddzają: to jest ta kłódka, którą warto mieć. Bez względu na to, czy parkujesz w centrum miasta, na peronie czy przed domem – będziesz spał spokojnie.\n\n### 🎯 Kluczowe Cechy\n\n- **Stal hartowana najwyższej jakości** – Gwarantowana odporność na przecinanie i walenie\n- **Kompaktowy rozmiar** – Łatwa w transporcie, idealnie mieści się do plecaka lub torby rowerowej\n- **Certyfikat bezpieczeństwa** – Spełnia międzynarodowe normy ASTM i EN\n- **Nowoczesny zamek** – Precyzyjny mechanizm z ochroną przed манипулацjами\n- **Ochrona przed korozją** – Powłoka ochronna gwarantuje żywotność nawet w trudnych warunkach atmosferycznych\n- **Design ergonomiczny** – Łatwa obsługa, wygodne użytkowanie codziennie\n- **Gwarancja producenta** – 10-letnia gwarancja świadczy o zaufaniu ABUS do swojego produktu\n\n### 📋 Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Marka** | ABUS |\n| **Model** | Granit |\n| **Materiał** | Stal hartowana |\n| **Kategoria Bezpieczeństwa** | Wysoka (9/10) |\n| **Waga** | Ok. 1200 g |\n| **Średnica szyny** | 13 mm |\n| **Długość użyteczna** | 230 mm |\n\n### 💡 Dlaczego Warto Wybrać ABUS Granit?\n\nNie kupujesz tylko kłódkę – kupujesz spokój i bezpieczeństwo. ABUS od ponad 100 lat produkuje systemy bezpieczeństwa, którym ufają policja i agencje ochrony na całym świecie. Kłódka Granit to świadomy wybór każdego właściciela pojazdu, który wie, że najtańsza ochrona to ta, którą nie będzie trzeba testować.\n\n**Nie zwlekaj – zabezpiecz swoją inwestycję dziś!** Za kwotę **1418,03 PLN** otrzymujesz gwarancję bezpieczeństwa na lata. Zamów teraz i ciesz się pełnym spokojem. Dostawa w 24-48 godzin. Kłódka ABUS Granit czeka na Twój rower!\n\n---\n\n*Produkt dostarczany jest w oryginalnym opakowaniu producenta z dokumentacją gwarancyjną i kluczami zapasowymi.*', '1418.03', '0.75', 2, 1, 'klodka-abus-granit', '2023-11-05 00:00:00'),
(32, 'Czujnik zalania Fibaro', 'BEZ-00032', '## Czujnik zalania Fibaro - Inteligentny system ochrony przed zalaniem\n\nCzujnik zalania Fibaro to innowacyjne urządzenie, które stanowi idealną ochronę dla Twojego domu przed nieoczekiwanymi zalaniami. Czy to potok z pralki, nieszczelny dach, zablokowana rura odpływowa czy zalew gruntowy – sensor natychmiast wykryje obecność wody i poinformuje Cię o zagrożeniu. Dzięki łączności Z-Wave Plus, urządzenie bezprzewodowo komunikuje się z Twoim hubem domowym, umożliwiając natychmiastowe powiadomienie na telefon, nawet gdy jesteś poza domem.\n\nMontaż Fibarowy czujnika zalania jest niezwykle prosty i nie wymaga specjalistycznych umiejętności. Minimalistyczny design pozwala na dyskretne umieszczenie czujnika w kluczowych lokalizacjach – łazience, kuchni, piwnicy czy przy bojlerze. Urządzenie zasilane jest jedną baterią AA, która wytrzymuje do kilku lat regularnej pracy. Czujnik wysyła również powiadomienie o stanie baterii, dzięki czemu nigdy nie zostaniesz zaskoczony jej wyczerpaniem.\n\nSystem jest w pełni kompatybilny z najpopularniejszymi hubami automatyki domowej – zarówno polskimi, jak i międzynarodowymi rozwiązaniami. Możesz łatwo zintegrować czujnik z innymi urządzeniami smart home, tworząc zaawansowane scenariusze automatyzacji. Na przykład, gdy sensor wykryje zalanie, system może automatycznie wyłączyć zasilanie, wysłać alert do sąsiada lub włączyć kamerę monitorującą. To nie tylko bezpieczeństwo – to kompletny system ochrony Twojego majątku.\n\n### Kluczowe cechy\n\n- **Szybka detekcja zalania** – czujnik reaguje natychmiast na kontakt z wodą, wysyłając alarm w kilka sekund\n- **Bezprzewodowe połączenie Z-Wave Plus** – niezawodna komunikacja z hubem na odległość do 100 metrów w linii prostej\n- **Niski pobór energii** – jedna bateria AA wystarczy na kilka lat pracy\n- **Powiadomienie o stanie baterii** – automatyczne alerty przed wyczerpaniem zasilania\n- **Kompaktowy design** – dyskretne urządzenie o wymiarach 29 x 29 x 12 mm, łatwe do ukrycia\n- **Integracja z systemami automatyki** – kompatybilność z popularnymi hubami i aplikacjami mobilnymi\n- **Certyfikaty bezpieczeństwa** – europejskie normy i certyfikacje gwarantujące niezawodność\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Protokół komunikacji | Z-Wave Plus |\n| Zasilanie | Bateria AA (1 szt.) |\n| Czas pracy baterii | ~3-5 lat |\n| Wymiary | 29 x 29 x 12 mm |\n| Zasięg sygnału | do 100 m (linia prosta) |\n| Temperatura pracy | 0°C do 40°C |\n| Cena | 633,49 PLN |\n\n---\n\nCzujnik zalania Fibaro to inwestycja, która chroni to, co dla Ciebie najważniejsze. Za mniej niż 650 złotych uzyskujesz profesjonalny system wczesnego ostrzegania, który może uratować Ci tysiące złotych strat. Nie czekaj na katastrofę – kup Fibarowy czujnik zalania dzisiaj i śpij spokojnie, wiedząc, że Twój dom jest pod ochroną! 🏠💧', '633.49', '3.94', 2, 1, 'czujnik-zalania-fibaro', '2024-04-13 00:00:00'),
(33, 'Monitoring Arlo Pro 4', 'BEZ-00033', '## Monitoring Arlo Pro 4 - Kamera Bezpieczeństwa WiFi 4K\n\nArlo Pro 4 to zaawansowany system monitoringu, który łączy nowoczesną technologię z niezawodnością i intuicyjną obsługą. Kamera w rozdzielczości 4K zapewnia krystalicznie czysty obraz zarówno w dzień, jak i w nocy dzięki zaawansowanemu podczerwieni. Niezależnie od tego, czy chcesz chrzcić swój dom, ogród, garaż czy małą firmę - Arlo Pro 4 zapewni Ci kompleksowe bezpieczeństwo przez całą dobę.\n\nSystem wyróżnia się bateryjnym zasilaniem z bardzo długim czasem pracy - do 6 miesięcy na jednym ładowaniu. Dzięki temu możesz zainstalować kamerę praktycznie wszędzie, bez konieczności paścia przewodów i szukania kontaktów. Synchronizacja WiFi jest stabilna i szybka, a aplikacja mobilna pozwala na zdalne sterowanie i podgląd na żywo z każdego miejsca na świecie. Nagrania trafiają do bezpiecznej chmury lub lokalnie na dysk, co gwarantuje ochronę Twoich danych.\n\nArlo Pro 4 posiada zaawansowane funkcje detekcji - inteligentne rozpoznawanie osób, pojazdów i zwierząt zmniejsza ilość fałszywych alarmów. Możesz ustawić własne strefy monitorowania i dostosować czułość detektora do swoich potrzeb. Wbudowany dwukierunkowy system audio pozwala na komunikację w czasie rzeczywistym - porozmawiasz z gościem, dostawcą lub alarmem potencjalnym intruzem. IP67 to gwarancja odporności na wszelkie warunki pogodowe - deszcz, śnieg czy upały nie będą stanowiły problemu.\n\n### Kluczowe cechy\n\n- **Rozdzielczość 4K** - Wideo w ultrawysokim poziomie detali, idealne do identyfikacji szczegółów\n- **Zasilanie bateryjne** - Do 6 miesięcy pracy na jednym ładowaniu, brak kabli\n- **Noktowizja HD** - Wyraźne nagrania w całkowitej ciemności dzięki zaawansowanemu podczerwieni\n- **Inteligentna detekcja** - Rozpoznawanie osób, samochodów i zwierząt z powiadomieniami w Real-time\n- **Dwukierunkowy audio** - Mów i słuchaj na żywo przez wbudowany mikrofon i głośnik\n- **IP67 + Wytrzymałość** - Pełna odporność na warunki atmosferyczne i ekstremalne temperatury\n- **Aplikacja mobilna** - Pełna kontrola smartfona/tabletu 24/7 z dostępem z całego świata\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Rozdzielczość | 4K (2560x1440 px) |\n| Zasilanie | Bateria AA x4 / Zasilacz opcjonalny |\n| Zasięg WiFi | Do 100 metrów (bez przeszkód) |\n| Odporność | IP67 (pyło i wodoszczelna) |\n| Przechowywanie | Chmura + MicroSD (do 64GB) |\n\n---\n\n**Arlo Pro 4 za 1035,29 PLN to inwestycja w spokój ducha i bezpieczeństwo Twojej rodziny.** Niezawodny system, który będzie pracował niezawodnie przez lata, obsługiwany przez doskonałą aplikację i wsparcie techniczne. Nie czekaj - zamów dziś i zyskaj pełną kontrolę nad tym, co się dzieje wokół Twojego domu. Arlo Pro 4 - profesjonalny monitoring dostępny dla każdego! ✓', '1035.29', '0.50', 2, 0, 'monitoring-arlo-pro-4', '2023-09-02 00:00:00'),
(34, 'Kamera Xiaomi Mi Home 2K', 'BEZ-00034', '## Kamera Xiaomi Mi Home 2K\n\n### Opis produktu\n\nKamera Xiaomi Mi Home 2K to idealne rozwiązanie dla każdego, kto chce mieć pełną kontrolę nad swoim domem, mieszkaniem lub biurem. Dzięki wysokiej rozdzielczości 2K (2560x1440 pikseli) otrzymujesz niezwykle wyraźne obrazy zarówno w dzień, jak i w nocy. Inteligentna kamera wyposażona jest w szeroki kąt widzenia 110 stopni, co pozwala monitorować większą powierzchnię bez martwienia się o martwymi strefami. Obsługa Inteligentnych Asystentów i aplikacji mobilnej Mi Home sprawia, że zarządzanie bezpieczeństwem domu staje się proste i dostępne z każdego miejsca na świecie.\n\nWszechstronna funkcjonalność kamery obejmuje zaawansowaną detekcję ruchu z możliwością wysyłania powiadomień w czasie rzeczywistym. Niezawodne noktowizyjne podczerwienie zapewnia jasne nagrania nawet w całkowitej ciemności, a dwukierunkowy mikrofon i głośnik umożliwiają bezpośrednią komunikację z osobami w polu widzenia kamery. Wbudowana karta SD o pojemności do 128 GB pozwala na przechowywanie nagrań z kilku dni, a chmura Xiaomi Cloud oferuje dodatkową kopię bezpieczeństwa dla najważniejszych materiałów.\n\nMontaż kamery zajmuje zaledwie kilka minut – wystarczy gniazdo zasilające oraz połączenie Wi-Fi. Kamera współpracuje z systemami smart home Xiaomi, pozwalając na integrację z innymi urządzeniami w sieci. Niskie zużycie energii i kompaktowy design sprawiają, że urządzenie nie zajmuje zbyt wiele miejsca i jest niezauważalne dla domowników. Ta kamera to inwestycja w spokój ducha i bezpieczeństwo Twojej rodziny.\n\n### Kluczowe cechy\n\n- **Rozdzielczość 2K (2560x1440)** – wyraźne obrazy z bogatymi szczegółami\n- **Kąt widzenia 110°** – monitorowanie dużej powierzchni z jednego urządzenia\n- **Noktowizja IR** – nagrywanie w pełnej ciemności z zasięgiem do 8 metrów\n- **Detekcja ruchu** – natychmiastowe powiadomienia na telefon o podejrzanych ruchach\n- **Dwukierunkowa komunikacja** – mikrofon i głośnik dla bezpośredniego dialogu\n- **Obsługa karty SD** – możliwość przechowywania do 128 GB nagrań lokalnie\n- **Integracja z Mi Home** – sterowanie przez aplikację mobilną z dowolnego miejsca\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Rozdzielczość | 2560 x 1440 pikseli (2K) |\n| Kąt widzenia | 110° |\n| Noktowizja | Podczerwień IR, zasięg 8m |\n| Łączność | Wi-Fi 2.4/5GHz |\n| Karta SD | Do 128 GB |\n| Zasilanie | AC 100-240V / 5V DC |\n\n### Podsumowanie\n\nKamera Xiaomi Mi Home 2K to niezawodny strażnik Twojego domu za wyjątkową cenę **620,87 PLN**. Wysoka jakość obrazu, inteligentne funkcje bezpieczeństwa i łatwość obsługi czynią ją idealnym wyborem zarówno dla początkujących, jak i zaawansowanych użytkowników smart home. Nie czekaj – zabezpiecz swój dom już dziś i zyskaj pewność, że zawsze widzisz, co się wokół Ciebie dzieje. Gwarantowana jakość Xiaomi i wsparcie polskiego serwisu to dodatkowa korzyść zakupu w naszym sklepie!\n\n**Zamów teraz i korzystaj z ochrony w jakości 2K! 📹✨**', '620.87', '2.07', 2, 0, 'kamera-xiaomi-mi-home-2k', '2024-04-02 00:00:00');
INSERT INTO `products` (`id`, `name`, `sku`, `description`, `price`, `weight`, `category_id`, `active`, `image`, `created_at`) VALUES
(35, 'Zamek szyfrowy Gerda', 'BEZ-00035', '## Zamek szyfrowy Gerda\n\nZamek szyfrowy Gerda to nowoczesne rozwiązanie zabezpieczające, które łączy niezawodność tradycyjnych zamków z wygodą cyfrowego dostępu. Idealny do użytku w domu, biurze, sklepie czy magazynie – wszędzie tam, gdzie potrzebna jest szybka, bezpieczna kontrola dostępu. Dzięki mechanizmowi szyfrowania, zapomnisz o kluczach i ich gromadzeniu. Gerda to gwarancja spokojnego snu – Twoja własność chroniona zaawansowaną technologią.\n\nSystem zapamiętuje do 99 różnych kodów dostępu, co czyni go idealnym do pracy w zespołach lub dla rodzin o wielu członkach. Każdy użytkownik może mieć indywidualny kod, a wszystkie dostępy są rejestrowane w pamięci urządzenia – możesz dokładnie śledzić, kto i kiedy otwierał zamek. Instalacja jest dziecinnie prosta i nie wymaga specjalistycznych narzędzi – wystarczy śrubokręt. Zamek Gerda pracuje niezawodnie przez miesiące na bateriach, a niski poziom energii sygnalizowany jest wyraźnym dźwiękiem ostrzeżenia.\n\nNiezależnie od pogody – deszczu, śniegu czy upalnego słońca – Gerda nie zawodnie stoi na straży. Obudowa ze stali nierdzewnej i wzmocnionych polimerów gwarantuje odporność na korozję i uszkodzenia mechaniczne. Zamek sprawdził się już w tysiącach domów, biur i sklepów na całym świecie. To wybór zaufanych użytkowników, którzy doceniają połączenie bezpieczeństwa, trwałości i wygody.\n\n### Kluczowe cechy\n\n- 🔐 **Kod dostępu do 99 użytkowników** – każdy członek rodziny lub pracownik może mieć swój indywidualny kod\n- 📱 **Elektroniczny system szyfru** – wpisanie prawidłowego kodu natychmiast otwiera zamek bez użycia klucza\n- 🔋 **Zasilanie na bateriach** – działa miesiącami na standardowych bateriach, wskaźnik niskiego poziomu energii\n- 🌧️ **Obudowa ze stali nierdzewnej** – całkowita odporność na warunki pogodowe i korozję\n- 📊 **Rejestrowanie dostępów** – pamięć wszystkich próśb otwarcia z czasem i kodem użytkownika\n- 🛠️ **Łatwa instalacja** – żaden profesjonalista nie potrzebny, instrukcja krok po kroku\n- 🔇 **Tryb cichy** – możliwość wyłączenia dźwięków dla dyskretności użytkowania\n\n### Specyfikacja\n\n| Parametr | Opis |\n|----------|------|\n| **Materiał** | Stal nierdzewna + wzmocniony polimer |\n| **Zasilanie** | 4 x baterie AA (alkaliczne) |\n| **Pojemność pamięci** | Do 99 kodów dostępu |\n| **Wymiary** | 85 × 60 × 30 mm |\n| **Waga** | 220 g |\n\n---\n\n**Zamek szyfrowy Gerda za 611,47 PLN to inwestycja w bezpieczeństwo i wygodę, która szybko się zwraca.** Nie czekaj – zabezpiecz swoją własność dzisiaj! Dodaj do koszyka teraz i ciesz się bezstresowym dostępem do wszystkich ważnych pomieszczeń. Dostawa w ciągu 24-48 godzin! 🚚✨', '611.47', '3.07', 2, 1, 'zamek-szyfrowy-gerda', '2023-11-24 00:00:00'),
(36, 'Czujnik gazu Keno', 'BEZ-00036', '## Czujnik gazu Keno - Niezawodna ochrona Twojego domu\n\nCzujnik gazu Keno to profesjonalny system alarmowy zapewniający całodobową ochronę przed wyciekami gazu w Twoim domu, mieszkaniu lub biurze. Urządzenie wyposażone w zaawansowaną technologię detekcji gazu LPG, ziemnego i metanu natychmiastowo reaguje na zagrożenie, wydając głośny alarm o natężeniu 85 dB. Dzięki intuicyjnej obsłudze i eleganckinemu designowi Czujnik Keno idealnie wpasowuje się w każde wnętrze, jednocześnie zapewniając bezpieczeństwo najwyższego poziomu dla Ciebie i Twoich bliskich.\n\nUrządzenie posiada ultraczuły sensor zdolny do wykrycia nawet najmniejszych stężeń niebezpiecznych gazów, zanim staną się zagrożeniem dla zdrowia. Keno wyposażony jest w inteligentny system autodiagnostyki, który regularnie testuje sprawność urządzenia i sygnalizuje wszelkie anomalie. Zasilany bateryjnie (które wliczają się w cenę) czujnik działa niezawodnie przez cały rok bez konieczności instalacji przez fachowca. To rozwiązanie, które faktycznie ratuje życie – polecane przez specjalistów od bezpieczeństwa pożarowego i gazowego.\n\nZastosowanie Czujnika Keno to nie tylko obowiązek, ale przede wszystkim inwestycja w spokój i bezpieczeństwo. Sprawdza się zarówno w domach jednorodzinnych opalanych gazem, jak i w mieszkaniach z aneksem kuchennym. Nieodłączny element wyposażenia dla każdej rodziny, zwłaszcza jeśli w domu są dzieci lub osoby starsze. Montaż zajmuje zaledwie kilka minut – wystarczy wybrać odpowiednie miejsce, a urządzenie zaczyna pracować natychmiast.\n\n### Kluczowe cechy\n\n- ⚡ **Czujnik wysokoczuły** – wykrywanie gazu LPG, ziemnego i metanu z bezzwłocznym alarmem\n- 🔊 **Alarm 85 dB** – ostrzeżenie słyszalne w całym domu, gwarantuje szybką reakcję\n- 🔋 **Zasilanie bateryjne** – baterie wliczone w zakup, brak konieczności instalacji elektrycznej\n- ✅ **Autodiagnostyka** – inteligentny system testujący sprawność urządzenia 24/7\n- 📍 **Łatwa montaż** – przymocowanie ścienne, gotowe do użytku w minutę\n- 🏠 **Elegancki design** – nowoczesny wygląd, dezaktywujący się w każdym mieszkaniu\n- 💪 **Niezawodność** – certyfikat EU, sprawdzony przez profesjonalistów ds. bezpieczeństwa\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Detektowane gazy | LPG, gaz ziemny, metan |\n| Natężenie alarmu | 85 dB |\n| Zasilanie | Baterie AA/AAA (w zestawie) |\n| Czas detekcji | < 60 sekund od pojawienia się gazu |\n| Wymiary | 120 x 70 x 45 mm |\n| Gwarancja | 24 miesiące |\n\n---\n\n**Nie czekaj na wypadek – zadbaj o bezpieczeństwo dzisiaj!** Czujnik gazu Keno za jedyne **685,24 PLN** to inwestycja, która może uratować Ci życie. Szybko się montuje, niezawodnie pracuje i daje poczucie spokoju każdego dnia. Dodaj do koszyka teraz i skup się na tym, co ważne – na bezpieczeństwie Twoich bliskich. 🛡️', '685.24', '3.26', 2, 1, 'czujnik-gazu-keno', '2023-10-28 00:00:00'),
(37, 'Oświetlenie LED z czujnikiem', 'BEZ-00037', '## Oświetlenie LED z czujnikiem – Inteligentne światło dla Twojego domu\n\nOdkryj nową jakość oświetlenia z naszym nowoczesnym systemem LED wyposażonym w zaawansowany czujnik ruchu. To idealne rozwiązanie dla osób, które cenią wygodę, bezpieczeństwo i oszczędność energii. Oświetlenie LED z czujnikiem to połączenie najnowszych technologii z praktycznym designem, który bezproblemowo integruje się z każdym wnętrzem. Niezależnie od tego, czy szukasz oświetlenia do korytarza, łazienki, garażu czy na zewnątrz – ten produkt spełni wszystkie Twoje oczekiwania.\n\nDzięki zabudowanemu czujnikowi ruchu światło automatycznie włączy się, gdy ktoś się zbliży, a wyłączy się po upływie ustawionego czasu. Oznacza to nie tylko maksymalną wygodę – nie musisz szukać wyłącznika w ciemności – ale także znaczące oszczędności na rachunkach za prąd. Diody LED zużywają nawet 80% mniej energii niż tradycyjne żarówki, a ich żywotność wynosi ponad 50 000 godzin. Ta inwestycja zwróci się szybciej, niż się spodziewasz, jednocześnie chroniąc naszą planetę.\n\nProdukt wyróżnia się trwałą konstrukcją wykonaną z najwyższej jakości materiałów, odpornych na zarówno wysokie temperatury, jak i wilgoć. Intuicyjne ustawienia pozwalają na pełną konfigurację czułości czujnika oraz czasu działania światła. Oświetlenie LED z czujnikiem to gwarancja bezpieczeństwa dla całej rodziny – zawsze będzie Ci świecić w drodze, niezależnie od pory dnia i nocy. To rozwiązanie docenią zarówno właściciele domów, mieszkań, jak i przedsiębiorcy szukający niezawodnego systemu oświetlenia.\n\n### Kluczowe cechy\n\n- ✨ **Zaawansowany czujnik ruchu PIR** – automatyczne włączanie/wyłączanie światła w zasięgu do 8 metrów\n- 💡 **Diody LED o najwyższej wydajności** – światło o barwie 4000K (naturalna biel), natężenie 1200 lumenów\n- ⚡ **Oszczędność energii** – zaledwie 15W mocy, znacznie poniżej tradycyjnych rozwiązań\n- ⏱️ **Regulowane parametry** – możliwość ustawienia czasu wyłączenia od 10 do 300 sekund\n- 🌧️ **Odporność na warunki atmosferyczne** – IP65, idealne do użytku wewnętrznego i zewnętrznego\n- 🔧 **Łatwa instalacja** – gotowy do użytku, nie wymaga specjalistycznej wiedzy\n- 🛡️ **Certyfikat CE** – gwarancja jakości i bezpieczeństwa\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Typ diody | LED SMD 2835 |\n| Moc znamionowa | 15W |\n| Napięcie zasilania | 220-240V AC, 50Hz |\n| Strumień świetlny | 1200 lm |\n| Temperatura barwowa | 4000K (biała naturalna) |\n| Wskaźnik oddania barw CRI | ≥80 Ra |\n| Klasa izolacji | IP65 |\n| Zasięg czujnika | do 8 metrów |\n| Czas wyłączenia | 10-300 sekund (regulowany) |\n| Żywotność diod | 50 000 godzin |\n| Wymiary | 260 × 180 × 85 mm |\n| Waga | 350 g |\n| Gwarancja | 24 miesiące |\n\n---\n\n**Nie czekaj – zainwestuj w inteligentne oświetlenie już dziś!** Oświetlenie LED z czujnikiem za 1408,43 PLN to doskonała alternatywa dla tradycyjnych żarówek. Przystąp do rewolucji smart home i ciesz się wygodą, bezpieczeństwem i oszczędnościami każdego dnia. Szybkie dostarczenie, bezpieczne opakowanie i pełna gwarancja producenta – to wszystko czeka na Ciebie. **Dodaj do koszyka i odczuj różnicę!**', '1408.43', '2.19', 2, 1, 'oswietlenie-led-z-czujnikiem', '2023-07-16 00:00:00'),
(38, 'Alarm samochodowy Viper', 'BEZ-00038', '## Alarm samochodowy Viper – Profesjonalna ochrona pojazdu\n\n### Opis produktu\n\nAlarm samochodowy Viper to niezawodny system ochrony, który zapewnia pełną bezpieczeństwo Twojego pojazdu przez całą dobę. Urządzenie wyposażone jest w zaawansowaną technologię detekcji włamania, która reaguje na każdą próbę nieautoryzowanego dostępu. Dzięki głośnemu syrenom o mocy sięgającej 120 dB alarm skutecznie odstrasza potencjalnych złodziei, a jednocześnie alertuje właściciela o zagrożeniu. Viper to gwarancja spokojnego snu – Twój samochód jest pod stałą ochroną, niezależnie od tego, gdzie się znajduje.\n\nSystem został zaprojektowany z myślą o maksymalnej wydajności i niezawodności. Alarm Viper charakteryzuje się łatwą instalacją i intuicyjnym obsługiwaniem. Nowoczesne komponenty elektryczne zapewniają długoletnie bezawaryjne użytkowanie, a odporność na warunki atmosferyczne pozwala na pracę zarówno zimą, jak i latem. To rozwiązanie sprawdza się idealnie zarówno w przypadku samochodów osobowych, jak i pojazdów użytkowych.\n\nInwestycja w alarm Viper to inwestycja w bezpieczeństwo. Wiele zdarzeń kradzieży mogłoby być uniknięte dzięki obecności widocznego systemu alarmowego. Potencjalni przestępcy omijają pojazdy wyposażone w alarm, wybierając łatwiejsze cele. Dodatkowo, niektóre ubezpieczalnie oferują zniżki dla pojazdów wyposażonych w profesjonalne systemy bezpieczeństwa – inwestycja może więc zwrócić się dzięki niższym składkom ubezpieczenia.\n\n### Kluczowe cechy\n\n- 🔔 **Syren o mocy 120 dB** – głośny dźwięk skutecznie odstrasza złodziei i powiadamia otoczenie\n- 🚗 **Uniwersalna kompatybilność** – pracuje z większością marek i modeli samochodów\n- 🔒 **Zaawansowana detekcja ruchu** – czujnik reaguje na każdą próbę włamani\n- 📡 **Niezawodna elektronika** – solidne komponenty gwarantują długoletnie bezawaryjne użytkowanie\n- ❄️ **Odporność na warunki atmosferyczne** – sprawdza się w każdej porze roku\n- 🎚️ **Łatwa instalacja** – prosty montaż bez konieczności specjalistycznych narzędzi\n- 💡 **Wymiana baterii** – ekologiczne źródło zasilania, długi czas pracy bez serwisu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Moc syreny | 120 dB |\n| Zasilanie | Bateria litowa |\n| Kompatybilność | Uniwersalna (większość samochodów) |\n| Temperatura pracy | od -20°C do +60°C |\n| Wymiary | 156 x 85 x 45 mm |\n\n### Podsumowanie\n\nAlarm samochodowy Viper to gwarancja kompleksowej ochrony Twojego pojazdu za rozumną cenę. Za jedyne **373,31 PLN** otrzymujesz profesjonalny system bezpieczeństwa, który będzie strzegł Twojego samochodu dzień i noc. Nie czekaj – zadbaj o swoją inwestycję już dziś i ciesz się pełnym spokojem. Zamawiaj teraz i dołącz do tysięcy zadowolonych klientów, którzy bezpiecznie parkują swoje pojazdy dzięki Viperowi!\n\n---\n\n**Szybka dostawa | Gwarancja producenta | Zadowolenie 100% gwarantowane**', '373.31', '2.24', 2, 1, 'alarm-samochodowy-viper', '2023-09-08 00:00:00'),
(39, 'Kamera termowizyjna FLIR', 'BEZ-00039', '## Kamera termowizyjna FLIR\n\nOdkryj świat niewidoczny dla ludzkiego oka dzięki zaawansowanej kamerze termowizyjnej FLIR! Ta innowacyjna urządzenie pozwala na wizualizację rozkładu temperatury w rzeczywistym czasie, wykorzystując technologię termografii podczerwonej. Idealna zarówno dla profesjonalistów z branży budowlanej, elektrycznej i instalacyjnej, jak i dla entuzjastów DIY szukających niezawodnego narzędzia diagnostycznego. Kamera FLIR to połączenie precyzji, niezawodności i łatwości obsługi w jednym kompaktowym urządzeniu.\n\nDzięki zaawansowanym czujnikom termicznym możesz szybko identyfikować problemy z izolacją termiczną, wykrywać przecieki w systemach grzewczych, diagnozować usterki urządzeń elektrycznych oraz monitorować efektywność energetyczną budynków. Wszystko to w tym jednym profesjonalnym narzędziu! Kamera dostarcza wyraźnych, szczegółowych obrazów termicznych, które pomogą Ci podjąć właściwe decyzje naprawcze i oszczędzić czas oraz pieniądze. Obsługa intuicyjna, wyświetlacz o wysokiej rozdzielczości i szybka analiza danych to cechy, które wyróżniają FLIR na tle konkurencji.\n\nNiezależnie od tego, czy pracujesz w zawodzie, czy po prostu dbasz o stan swojego domu, ta kamera stanie się Twoim niezbędnym asystentem. Kompaktowe rozmiary umożliwiają łatwe przenoszenie, a solidna konstrukcja gwarantuje wieloletnie użytkowanie bez obaw o uszkodzenia. Inwestycja w kamerę FLIR to inwestycja w bezpieczeństwo, efektywność i spokój ducha.\n\n### Kluczowe cechy\n\n- **Termografia podczerwona** – Nowoczesna technologia pozwala na dokładną wizualizację rozkładu temperatury z precyzją do 0,1°C\n- **Wysoka rozdzielczość obrazu** – Wyraźne, szczegółowe termogramy ułatwiające diagnostykę problemów\n- **Szybka analiza** – Natychmiastowe wyniki bez czekania na przetwarzanie danych\n- **Trwała konstrukcja** – Obudowa odporna na warunki trudne, idealnie sprawdza się w terenie\n- **Łatwa obsługa** – Intuicyjny interfejs użytkownika dostępny dla każdego, bez konieczności specjalistycznego szkolenia\n- **Kompaktowe wymiary** – Lekka i przenośna, łatwa do schowania w plecaku lub torbie narzędziownika\n- **Szeroki zakres zastosowań** – Od budownictwa i elektrotechniki po medycynę i badania naukowe\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Technologia | Termografia podczerwona (IR) |\n| Zakres temperatury | -20°C do +250°C |\n| Dokładność pomiaru | ±2% lub ±2°C |\n| Rozdzielczość termiczna | 320 × 240 pikseli |\n| Wyświetlacz | LCD kolorowy, diagonala 3,5\" |\n| Zasilanie | Akumulator Li-ion (czas pracy: 4-5 godzin) |\n\n---\n\n**Nie czekaj dłużej!** Kamera termowizyjna FLIR za jedyne **1175,57 PLN** to okazja, która nie powinna Ci umknąć. Przystępna cena w stosunku do profesjonalnej jakości i zaawansowanym funkcjom. Dołącz do tysięcy zadowolonych użytkowników, którzy już odkryli możliwości, jakie stwarza ta niezwykła technologia. Zamów teraz i zaoszczędź czas i pieniądze na diagnostyce i naprawach! **⭐⭐⭐⭐⭐**', '1175.57', '0.95', 2, 1, 'kamera-termowizyjna-flir', '2023-12-21 00:00:00'),
(40, 'System alarmowy Ajax Hub', 'BEZ-00040', '## System Alarmowy Ajax Hub – Zaawansowana Ochrona Twojego Domu i Biznesu\n\nSystem alarmowy Ajax Hub to nowoczesne rozwiązanie bezpieczeństwa, które łączy najnowocześniejszą technologię z intuicyjną obsługą. Urządzenie stanowi serce inteligentnego systemu ochrony, umożliwiając zarządzanie wszystkimi czujnikami i akcesoriami bezprzewodowo z poziomu dedykowanej aplikacji mobilnej. Ajax Hub gwarantuje profesjonalny poziom zabezpieczeń zarówno dla małych domów, jak i większych nieruchomości komercyjnych, zapewniając spokój i bezpieczeństwo 24/7.\n\nBezpieczeństwo nigdy nie było tak proste i dostępne. Ajax Hub komunikuje się z urządzeniami poprzez niezawodną technologię radiową na dedykowanym kanale 868 MHz, co gwarantuje stabilność połączenia i ochronę przed zakłóceniami. System obsługuje jednocześnie dziesiątki urządzeń, a sieć mesh-owa zapewnia nieprzerwaną komunikację nawet w trudnych warunkach architektonicznych. Inteligentne powiadomienia docierają do Ciebie w rzeczywistym czasie, umożliwiając szybką reakcję w sytuacji zagrożenia.\n\nWiele rodzin i firm w Polsce już zaufało systemowi Ajax Hub. Jego modułowa budowa pozwala na łatwe rozszerzanie systemu w miarę potrzeb – możesz zacząć od podstawowych czujników ruchu i drzwi, a następnie dodawać kamery, czujniki dymu czy wody. Wszystko działa harmonijnie w jednym ekosystemie, sterowanym z jednej aplikacji. Niezależnie od tego, czy jesteś w domu, w pracy czy na wakacjach, system Ajax Hub zawsze czuwa nad Twoją bezpieczeństwem.\n\n### Kluczowe Cechy\n\n- **Bezprzewodowa komunikacja** – Technologia radiowa 868 MHz zapewnia stabilne i bezpieczne połączenie z czujnikami\n- **Obsługa wielu urządzeń** – Możliwość podłączenia dziesiątek akcesoriów (czujniki ruchu, drzwi, dymu, kamery) w jednym systemie\n- **Sieć mesh** – Urządzenia automatycznie wzmacniają sygnał, eliminując tzw. martwe strefy w domu\n- **Aplikacja mobilna** – Pełna kontrola systemu z poziomu smartfona iOS lub Android, powiadomienia w czasie rzeczywistym\n- **Zasilanie bateryjne z opcją zasilacza** – Gwarancja działania nawet podczas przerwy w prądzie\n- **Certyfikat bezpieczeństwa** – Spełnia europejskie normy bezpieczeństwa i jest homologowany do pracy z operatorami monitoringu\n- **Konfiguracja w kilka minut** – Intuicyjny interfejs umożliwia szybką konfigurację nawet dla użytkowników bez doświadczenia\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Komunikacja | Bezprzewodowa, frekwencja 868 MHz |\n| Liczba obsługiwanych urządzeń | Do 100 akcesoriów |\n| Zasilanie | Bateria litowa + opcja zasilacza sieciowego |\n| Wymiary | 120 × 120 × 26 mm |\n| Gwarancja | 24 miesiące |\n\n---\n\n**Nie czekaj – zainwestuj w bezpieczeństwo już dziś!** System Ajax Hub to wybór tysięcy zadowolonych klientów w Polsce. Za cenę **1434.31 PLN** otrzymujesz profesjonalne rozwiązanie bezpieczeństwa, które będzie pracować dla Ciebie przez lata. Dodaj do koszyka teraz i zadbaj o to, co dla Ciebie najważniejsze – bezpieczeństwo Twojej rodziny i mienia!', '1434.31', '4.04', 2, 1, 'system-alarmowy-ajax-hub', '2024-04-01 00:00:00'),
(41, 'Olej silnikowy Castrol 5W-30 4L', 'MOT-00041', '## Olej silnikowy Castrol 5W-30 4L\n\nCastrol 5W-30 to profesjonalny olej silnikowy o uniwersalnym zastosowaniu, polecany dla właścicieli samochodów osobowych i lekkich pojazdów dostawczych. Ten 4-litrowy pojemnik zapewnia doskonałą ochronę silnika zarówno w trudnych warunkach jazdy miejskiej, jak i na długich trasach autostradalnych. Formuła opracowana przez specjalistów Castrol gwarantuje optymalną lepkość w szerokim zakresie temperatur, od mrozu zimowego aż po upały letnie. Olej spełnia rygorystyczne normy branżowe i rekomendacje głównych producentów pojazdów, co czyni go idealnym wyborem dla każdego właściciela samochodu dbającego o długowieczność silnika.\n\nZastosowanie oleju Castrol 5W-30 to gwarancja sprawnego działania systemu silnikowego przez dłuższy czas. Zaawansowana technologia zmniejsza zużycie paliwa, wspomaga czyszczenie silnika z zanieczyszczeń oraz zapewnia lepką ochronę wszystkich ruchomych części. Olej wykazuje doskonałe właściwości rozruchowe w niskich temperaturach, a jednocześnie utrzymuje stabilność warstwy ochronnej w temperaturach wysokich. Idealny do stosowania w silnikach benzynowych i wysokoprężnych, zgodny z najnowszymi specyfikacjami ACEA i americańskich standardów.\n\nPojemność 4 litrów pozwala na przeprowadzenie standardowej wymiany oleju w większości samochodów europejskich i japońskich. Zakup tego pojemnika to inwestycja w jakość i niezawodność Twojego pojazdu. Castrol to marka o ponad 100-letniej tradycji, zaufana przez miliony kierowców na całym świecie i rekomendowana przez serwisy dealerskie. Wybierając ten produkt, zyskujesz pewność, że Twój silnik otrzyma najlepszą opiekę.\n\n### Kluczowe cechy\n\n- **Lepkość uniwersalna 5W-30** – optymalna dla szerokiego zakresu temperatur otoczenia, od -20°C do +30°C\n- **Ochrona przed zużyciem** – wzmocniony skład zabezpiecza silnik przed startem na zimno i intensywnym obciążeniem\n- **Zmniejszone zużycie paliwa** – formuła energooszczędna wspomaga efektywność spalania\n- **Czyszczenie silnika** – specjalne detergenty usuwają osady i zanieczyszczenia z wewnętrznych części silnika\n- **Zgodność uniwersalna** – spełnia normy ACEA A3/B4, API SN, odpowiedni do większości samochodów osobowych\n- **Pojemność 4L** – praktyczny rozmiar wystarczający do jednej wymiany oleju w większości pojazdów\n- **Certyfikowana jakość** – produkt oryginalny z gwarancją autentyczności i trwałości\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Castrol 5W-30 |\n| Pojemność | 4 litry |\n| Typ silnika | Benzynowe i wysokoprężne |\n| Norma ACEA | A3/B4 |\n| Norma API | SN |\n| Zakres temperatur | -20°C do +30°C |\n| Producent | Castrol |\n\n---\n\n**Nie czekaj – zadbaj o swój samochód już dziś!** Olej silnikowy Castrol 5W-30 w pojemności 4L za jedyne **192,68 PLN** to doskonała okazja do zakupu produktu światowej klasy w przystępnej cenie. Regularna wymiana oleju to jeden z najtańszych sposobów na przedłużenie żywotności silnika i uniknięcie kosztownych napraw. Zamów teraz i ciesz się niezawodną pracą Twojego pojazdu. **Wysyłka w 24 godziny – szybko, bezpiecznie i niezawodnie!**', '192.68', '2.27', 3, 1, 'olej-silnikowy-castrol-5w-30-4l', '2024-01-17 00:00:00'),
(42, 'Akumulator Varta Blue 60Ah', 'MOT-00042', '## Akumulator Varta Blue 60Ah\n\nAkumulator Varta Blue 60Ah to niezawodne źródło energii dla każdego kierowcy, który ceni sobie jakość i niezawodność. Seria Blue od światowego producenta Varta gwarantuje solidne parametry, długą żywotność i doskonałą wydajność w każdych warunkach pogodowych. To doskonały wybór zarówno dla pojazdów benzynowych, jak i dla starszych samochodów wymagających stabilnego zasilania układu elektrycznego.\n\nAkumulator charakteryzuje się nowoczesną technologią produkcji, która zapewnia szybki start silnika nawet w mroźne poranki. Dzięki grubszym płytom ołowianych bateria wykazuje wyjątkową odporność na wibracje i warunki drogowe. Varta Blue 60Ah to gwarancja, że Twój samochód nigdy Cię nie zawiedzie – niezależnie od pory roku i warunków jazdy. Produkt spełnia najwyższe normy jakości europejskie i posiada niezbędne certyfikaty.\n\nDoskonale sprawdzi się w samochodach osobowych, taksówkach czy малoletnich pojazdach użytkowych. Montaż jest prosty i szybki, a akumulator pasuje do większości ogólnie dostępnych uchwytów. Dzięki zoptymalizowanemu systemowi wentylacji oraz grubszej obudowie, bateria pracuje cichutko i bezpiecznie, bez ryzyka wycieku. Inwestycja w Varta Blue to inwestycja w spokojną jazdę!\n\n### Kluczowe cechy\n\n- **Pojemność:** 60 Ah – idealna dla większości samochodów osobowych\n- **Prąd rozruchowy:** 540 A – gwarantuje niezawodny start w każdych warunkach\n- **Technologia:** Grube płyty ołowiowe – wytrzymałość i długotrwałość\n- **Odporność:** Mrozoodporny do -25°C – pracuje bez zawahania zimą\n- **Bezpieczeństwo:** System antywylania – bezpieczne użytkowanie\n- **Certyfikaty:** Normy CE, TÜV – pełna gwarancja jakości\n- **Producent:** Varta – lider światowego rynku akumulatorów\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Pojemność nominalna | 60 Ah |\n| Napięcie znamionowe | 12 V |\n| Prąd rozruchowy (CCA) | 540 A |\n| Wymiary (D × S × W) | 242 × 175 × 190 mm |\n| Masa | ok. 15 kg |\n\n---\n\n### Dlaczego warto wybrać Varta Blue 60Ah?\n\nTo nie jest zwykły akumulator – to gwarancja bezpieczeństwa i niezawodności na drodze. Seria Blue od Varty to wśród europejskich kierowców synonim solidności i profesjonalnego podejścia. Każdy akumulator przechodzi surowe testy jakości przed opuszczeniem fabryki, a producent oferuje zadowalającą gwarancję.\n\nNiezależnie od tego, czy jesteś początkującym kierowcą, czy doświadczonym mechanikiem – Varta Blue 60Ah to opcja, która nie rozczaruje. Zapomnij o rannych problemach z uruchomieniem silnika, o niepokoju podczas zimnych poranków czy lęku przed awarią w najmniej odpowiednim momencie. \n\n**Zamów teraz Akumulator Varta Blue 60Ah za zaledwie 360,82 PLN i ciesz się absolutnym spokojem na drodze!** Szybka dostawa, profesjonalna obsługa i pełna gwarancja producenta czekają na Ciebie. To inwestycja, która się opłaca – nie zwlekaj!', '360.82', '9.71', 3, 1, 'akumulator-varta-blue-60ah', '2024-03-26 00:00:00'),
(43, 'Opony Michelin Primacy 205/55 R16', 'MOT-00043', '## Opony Michelin Primacy 205/55 R16\n\nOdkryj perfekcyjne połączenie bezpieczeństwa, komfortu i oszczędności paliwa z legendarnymi oponami Michelin Primacy w rozmiarze 205/55 R16. Te nowoczesne opony pasażerskie zostały opracowane z myślą o kierowcach poszukujących niezawodności i wydajności zarówno w codziennych podróżach, jak i podczas dłuższych wyjazdów. Michelin Primacy to synonimu jakości i trwałości na polskich drogach – gwarancja spokojnego snu każdego posiadacza samochodu.\n\nOpony Primacy charakteryzują się zaawansowaną technologią przyczepności w warunkach mokrych, co gwarantuje bezpieczeństwo nawet podczas intensywnych opadów deszczu czy porannych mgieł. Precyzyjnie zaproponowany wzór bieżnika zapewnia doskonałą stabilność auta na drodze, a jednocześnie minimalizuje hałas podczas jazdy. Innowacyjny skład gumy zmniejsza opór toczenia, co bezpośrednio przełada się na niższe zużycie paliwa – Twój portfel będzie Ci za to wdzięczny. Niezależnie od pory roku lub warunków pogodowych, opony te wykazują niezwykle responsywne zachowanie, zapewniając pewną jazdę na każdej estradzie.\n\nTe opony sprawdzą się idealnie dla właścicieli kompaktowych sedanów i hatchbacjów szukających uniwersalnego rozwiązania. Zarówno dla codziennego dojeżdżania do pracy, jak i podróży rodzinnych, Primacy 205/55 R16 dostarczają niezmiennie wysokie standardy wydajności i bezpieczeństwa. Dzięki wytrzymałości i odporności na zużycie, zainwestowanie w te opony to inwestycja na długie lata beztroski.\n\n### Kluczowe cechy\n\n- **Doskonała przyczepność na mokrych powierzchniach** – zaawansowana technologia bieżnika dla maksymalnego bezpieczeństwa\n- **Niski opór toczenia** – zmniejszone zużycie paliwa i przyjazność dla portfela\n- **Wyciszenie hałasu** – przyjemna, cicha jazda nawet na autostradzie\n- **Wszechstronna przydatność** – idealne na cztery pory roku dla standardowych warunków\n- **Trwałość i odporność na zużycie** – gwarancja długotrwałej eksploatacji bez przesadnego straty profilu\n- **Responsywne prowadzenie** – precyzyjne trzymanie drogi i pewna kontrola pojazdu\n- **Zastosowanie uniwersalne** – idealne dla samochodów osobowych, sedanów i kompaktowych pojazdów\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Rozmiar** | 205/55 R16 |\n| **Markarz opony** | Michelin |\n| **Seria** | Primacy |\n| **Typ pojazdu** | Samochody osobowe, sedany, hatchbacki |\n| **Rekomendowana cena** | 441,17 PLN |\n\n---\n\n**Nie czekaj – zadbaj o bezpieczeństwo Twojej rodziny na drodze!** Opony Michelin Primacy 205/55 R16 to inwestycja w komfort i spokój jazdy, która zwraca się sama dzięki oszczędzanym paliwu. W tej cenie otrzymujesz sprawdzony, międzynarodowy standard jakości – markę ufną milionom kierowców na całym świecie. Dodaj do koszyka już teraz i ciesz się gwarantowaną jazdą bez zmartwień!', '441.17', '2.83', 3, 1, 'opony-michelin-primacy-205-55-r16', '2023-07-14 00:00:00'),
(44, 'Wycieraczki Bosch Aerotwin', 'MOT-00044', '## Wycieraczki Bosch AeroTwin\n\nWycieraczki Bosch AeroTwin to nowoczesne połączenie funkcjonalności, trwałości i elegancji. Przeznaczone dla kierowców, którzy cenią sobie bezpieczeństwo i najwyższą jakość. Seria AeroTwin reprezentuje pinnakl rozwoju technologii wycieraczek, łącząc aerodynamiczny design z niezawodną wydajnością w każdych warunkach pogodowych. Od intensywnych opadów deszczu po mgielne poranki – te wycieraczki gwarantują doskonałą widoczność i bezpieczeństwo na drodze.\n\nNowoczesna konstrukcja wycieraczy gwarantuje równomierny nacisk na całej długości szyby, co zapewnia perfekcyjne czyszczenie bez smug i pasm. Specjalna osłona chroni mechanizm przed uszkodzeniami spowodowanymi śniegiem, lodem i zabrudzeniami. Wycieraczki AeroTwin są kompatybilne z większością marek samochodowych, a instalacja jest niezwykle prosta – nie wymagają żadnych dodatkowych narzędzi ani adaptorów.\n\nInwestycja w wycieraczki Bosch AeroTwin to inwestycja w bezpieczeństwo i komfort jazdy. Materiały wysokiej klasy, certyfikowane przez producenta, gwarantują długotrwałą eksploatację nawet w najtrudniejszych warunkach atmosferycznych. Każda para przechodzi surową kontrolę jakości, aby spełnić najwyższe standardy branżowe. Wycieraczki to element, któremu warto poświęcić uwagę – od nich zależy Twoja bezpieczna jazda.\n\n### Kluczowe cechy\n\n- **Aerodynamiczny design** – nowoczesna forma zmniejsza opór powietrza i wygląda stylowo\n- **Równomierny nacisk** – guma rozkłada się równomiernie na całej szerokości szyby, eliminując smugi i pasy\n- **Wytrzymała guma** – odporny materiał wytrzymuje ekstremalne warunki pogodowe i wiele sezonów użytkowania\n- **Łatwa montaż** – szybka i intuicyjna instalacja bez konieczności wymiany wsporników\n- **Ochronna osłona** – specjalny kaptur chroni mechanizm przed lodem, śniegiem i zanieczyszczeniami\n- **Uniwersalna kompatybilność** – dostępne w wielu rozmiarach pasujących do większości pojazdów\n- **Wyciszenie** – praktycznie bezgłośne działanie dzięki optymalizowanej konstrukcji\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | Bosch AeroTwin |\n| Długość | Uniwersalna (dostępna w rozmiarach 450-800 mm) |\n| Typ | Wycieraczki ramkowe |\n| Materiał gumi | Naturalna guma odporna na UV |\n| Gwarancja | 24 miesiące |\n| Cena | 571,18 PLN |\n\n---\n\n**Nie czekaj – oceń kompleks wycieraczek Bosch AeroTwin już dziś!** Bezpieczna jazda w każdych warunkach to nie luksus, a konieczność. Wycieraczki AeroTwin zapewnią Ci doskonałą widoczność za parę złotych rocznie. Zamów teraz i ciesz się spokojem na drodze – gwarancjowana jakość Bosch, cena 571,18 PLN. Twoje bezpieczeństwo jest warte tej inwestycji! 🚗', '571.18', '10.49', 3, 1, 'wycieraczki-bosch-aerotwin', '2023-08-29 00:00:00'),
(45, 'Filtr oleju Mann-Filter', 'MOT-00045', '## Filtr oleju Mann-Filter – Niezawodna ochrona silnika Twojego pojazdu\n\nFiltr oleju Mann-Filter to gwarancja długowieczności i bezawaryjnej pracy silnika Twojego samochodu. Produkty tej niemieckiej marki są wyborem profesjonalnych mechaników i miłośników motoryzacji na całym świecie. Zastosowanie najwyższej jakości materiałów filtracyjnych oraz precyzyjne wykonanie sprawiają, że Mann-Filter skutecznie usuwa zanieczyszczenia z oleju silnikowego, chroniąc wszystkie krytyczne części jednostki napędowej przed przedwczesnym zużyciem.\n\nDzięki zaawansowanej technologii filtracji, ten filtr oleju zapewnia optymalny przepływ oleju przy jednoczesnym zatrzymaniu najmniejszych cząsteczek osadu, zanieczyszczeń metalicznych i produktów spalania. Niezależnie od warunków jazdy – w mieście, na autostradzie czy w ekstremalnych temperaturach – Mann-Filter pracuje niezawodnie, przedłużając żywotność silnika i utrzymując jego wydajność na najwyższym poziomie. To inwestycja w komfort eksploatacji Twojego pojazdu i spokój ducha.\n\nMontaż filtru jest prosty i nie wymaga specjalistycznych umiejętności – standardowe gwinty ułatwiają szybką wymianę. Rekomendujemy wymianę filtru oleju co 10-15 tysięcy kilometrów (w zależności od modelu pojazdu i warunków użytkowania), co zapewni maksymalną efektywność ochrony silnika. Mann-Filter to gwarancja oryginalności i pewności, że Twój silnik otrzyma najlepszą opiekę.\n\n### Kluczowe cechy\n\n- ✓ **Niemiecka jakość** – Produkt renomowanego producenta filtrów z ponad 80-letnim doświadczeniem\n- ✓ **Zaawansowana filtracja** – Materiały filtracyjne zadaniowe zatrzymują zanieczyszczenia o wymiarach od 10 mikrometrów\n- ✓ **Szeroki zakres temperatur** – Efektywna praca w temperaturach od -40°C do +150°C\n- ✓ **Łatwa instalacja** – Standardowe gwinty i opatentowany system mocowania\n- ✓ **Wydłużona żywotność silnika** – Systematyczna ochrona przed zużyciem i utlenieniem oleju\n- ✓ **Optymalny przepływ oleju** – Zminimalizowany opór przepływu, maksymalna efektywność smarowania\n- ✓ **Certyfikat jakości** – Zgodność z normami ISO i standardami koncernów motoryzacyjnych\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Producent | Mann-Filter (Niemcy) |\n| Rodzaj | Filtr oleju do silnika spalinowego |\n| Gwinty | Standardowe M20x1.5 (uniwersalne) |\n| Cena | 309,89 PLN |\n| Gwarancja | Zgodna z polityką producenta |\n\n### Podsumowanie\n\nMann-Filter to nie tyle produkt, ile inwestycja w bezawaryjną pracę Twojego silnika. Wybierając ten filtr oleju, decydujesz się na sprawdzony standard jakości i niezawodność testowaną przez miliony kierowców. Za cenę zaledwie 309,89 PLN otrzymujesz niemiecką precyzję, ochronę warty znacznie więcej oraz spokój ducha, że Twój pojazd pracuje w optymalnych warunkach. **Zamów teraz i zadbaj o długowieczność swojego samochodu!**\n\n🚗 *Dostawa szybka i bezpłatna przy zakupach powyżej 150 PLN*', '309.89', '13.46', 3, 1, 'filtr-oleju-mann-filter', '2023-11-09 00:00:00'),
(46, 'Klocki hamulcowe TRW', 'MOT-00046', '## Klocki hamulcowe TRW - Najwyższa jakość dla Twojego samochodu\n\nKlocki hamulcowe TRW to gwarancja bezpieczeństwa i niezawodności na każdej drodze. Renomowany producent, znany na całym świecie z doskonałości, oferuje komponenty hamulcowe, które łączą najnowocześniejszą technologię z wytrzymałością. Te profesjonalne klocki hamulcowe zostały zaprojektowane z myślą o maksymalnej efektywności hamowania, precyzyjnym sterowaniu pojazdem oraz długotrwałą eksploatacją bez utraty właściwości. Niezależnie od warunków drogowych – czy to miasta, autostrady czy trudne warunki pogodowe – możesz liczyć na konsekwentne osiągi i przewidywalny hamulec.\n\nProducent TRW zadbał o każdy szczegół, aby zapewnić Ci komfort i spokój jazdy. Klocki zostały wyposażone w materiały o wysokiej odporności na zużycie, co gwarantuje wydłużoną żywotność i zmniejszone koszty eksploatacji pojazdu. Dzięki zaawansowanym procesom produkcji oraz rygorystycznym testom kontroli jakości, każdy zestaw spełnia najwyższe standardy branżowe i normy bezpieczeństwa. Zamiana tych klocków to inwestycja w bezpieczeństwo Twojego pojazdu i osób w nim podróżujących.\n\nZastosowanie uniwersalne klocków TRW oznacza, że zaproponujemy Ci właściwe komponenty do praktycznie każdego modelu samochodu osobowego czy lekkiego pojazdu dostawczego. Montaż jest prosty i intuicyjny – klocki doskonale pasują do systemów hamulcowych większości pojazdów. Dzięki doskonałemu stosunkowi ceny do jakości oraz niezawodziemu działaniu, TRW to wybór liczący się na rynku – wybór profesjonalistów i wymagających kierowców.\n\n### Kluczowe cechy\n\n- **Trwałość i niezawodność** – materiały wysokiej jakości zapewniające długotrwałą eksploatację\n- **Precyzyjne hamowanie** – optymalna moc hamowania w każdych warunkach\n- **Niska emisja kurzu** – przyjazne dla środowiska i łatwiejsze czyszczenie felg\n- **Cicha praca** – specjalnie wyciszane, bez irytujących trzasków\n- **Uniwersalna kompatybilność** – pasują do większości modeli samochodów\n- **Certyfikacja europejska** – pełna zgodność z normami EU i bezpieczeństwa\n- **Szybka dostawa** – gotowe do natychmiastowego montażu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Producent | TRW |\n| Typ produktu | Klocki hamulcowe |\n| Moc hamowania | Wysokiej klasy |\n| Odporność na zużycie | Wzmocniona |\n| Certyfikat | Norma EU ECE R90 |\n| Cena | 756,54 PLN |\n\n---\n\n**Nie czekaj, zadbaj o bezpieczeństwo!** Klocki hamulcowe TRW to inwestycja w spokojną i bezpieczną jazdę. Doskonała jakość, sprawdzona reputacja i konkurencyjna cena sprawiają, że ten produkt powinien znaleźć się na Twojej liście zakupów już teraz. Zamów dziś i ciesz się niezawodnym hamowaniem przez następne tysiące kilometrów!', '756.54', '10.51', 3, 1, 'klocki-hamulcowe-trw', '2024-04-25 00:00:00'),
(47, 'Płyn do chłodnic Borygo Nowy', 'MOT-00047', '## Płyn do chłodnic Borygo Nowy\n\nPłyn do chłodnic Borygo Nowy to nowoczesny preparat opracowany specjalnie dla współczesnych systemów chłodzenia silników spalinowych. Stanowi idealne połączenie tradycyjnego doświadczenia marki Borygo z najnowszymi technologiami w zakresie ochrony silnika. Produkt został sformułowany z wykorzystaniem zaawansowanych inhibitorów korozji i dodatków przeciwzamarznięciowych, które gwarantują niezawodną pracę systemu chłodzenia zarówno w zimne, jak i w upalnie gorące dni.\n\nDzięki kompleksowej formule Płyn do chłodnic Borygo Nowy zapewnia całoroczną ochronę przed korozją, osadami oraz zamarznięciem. Jego specjalna receptura zawiera dodatki antykorozyjne, które tworzą ochronną warstwę na wewnętrznych ścianach chłodnicy i przewodów, uniemożliwiając powstanie rdzy. Produkt idealnie sprawdza się zarówno w nowoczesnych silnikach benzynowych, jak i w jednostkach diesla, oferując wszechstronną ochronę dla każdego pojazdu.\n\nPłyn charakteryzuje się doskonałą kompatybilnością z systemami chłodzenia różnych marek pojazdów. Łatwo się miesza z innymi płynami chłodniczymi na bazie glikolu, co czyni go praktycznym rozwiązaniem w sytuacjach awaryjnych. Zastosowanie tego produktu znacząco przedłuża żywotność całego systemu chłodzenia, zmniejsza ryzyko awarii silnika oraz gwarantuje efektywne odprowadzanie ciepła w każdych warunkach eksploatacji.\n\n### Kluczowe cechy\n\n- **Ochrona przed korozją** – Zaawansowany system inhibitorów zapobiega powstawaniu rdzy na metalowych elementach systemu chłodzenia\n- **Bezpieczeństwo termiczne** – Utrzymuje optymalną temperaturę pracy silnika w szerokim zakresie warunków atmosferycznych\n- **Odporność na zamarznięcie** – Bezpeczna praca w temperaturach poniżej -30°C, idealna dla użytkowników z krajów o ostrych zimach\n- **Kompatybilność uniwersalna** – Przeznaczony dla wszystkich typów silników spalinowych – benzynowych, diesla i gazowych\n- **Długa żywotność** – Przedłużona żywotność płynu gwarantuje oszczędność na częstych wymianie\n- **Ekologiczna formuła** – Produkt bezpieczny dla środowiska, niepowodujący szkody dla zbiorników wodnych\n- **Gotowy do użycia** – Łatwy w aplikacji, nie wymaga rozcieńczania w standardowych warunkach\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | Borygo |\n| Typ produktu | Płyn do chłodnic |\n| Pojemność | 1 litr |\n| Temperatura zamarznięcia | Poniżej -30°C |\n| Opakowanie | Kanister plastikowy |\n| Kompatybilność | Wszystkie pojazdy osobowe i lekkie ciężarówki |\n\n### Podsumowanie\n\nPłyn do chłodnic Borygo Nowy to niezawodny partner każdego kierowcy, który dba o długowieczność i bezpieczeństwo swojego pojazdu. Za zaledwie **161,09 PLN** zyskujesz kompleksową ochronę systemu chłodzenia na długie miesiące. Nie czekaj na problemy z silnikiem – zainwestuj w jakościowy płyn, który został sprawdzony przez tysiące użytkowników w całej Polsce. Dodaj do koszyka już teraz i ciesz się spokojem na drodze bez obaw o przegrzanie lub zamarzniecie silnika! 🚗\n\n---\n\n*Przed użyciem zapoznaj się z instrukcjami producenta pojazdu. Przechowywać w suchym, chłodnym miejscu, z dala od dzieci i zwierząt domowych.*', '161.09', '8.97', 3, 1, 'plyn-do-chlodnic-borygo-nowy', '2023-10-14 00:00:00'),
(48, 'Komplet narzędzi Neo 82szt', 'MOT-00048', '## Komplet narzędzi Neo 82szt\n\nProfesjonalny zestaw narzędzi **Neo 82szt** to idealne rozwiązanie dla każdego, kto szuka uniwersalnego kompletu do napraw domowych, DIY czy prac zawodowych. Niezawodne narzędzia w jednym, praktycznym zestawie oszczędzą Ci czasu i pieniędzy. Czy prowadzisz małe prace remontowe, zajmujesz się naprawami sprzętu domowego, czy po prostu chcesz mieć kompletne wyposażenie w swoim warsztacie – ten komplet będzie dla Ciebie niezbędnym towarzyszem. Każde narzędzie wykonane jest z trwałych, wysokiej jakości materiałów, które gwarantują długoletnie użytkowanie bez pogorszenia parametrów eksploatacyjnych.\n\nZestaw zawiera starannie dobrany asortyment narzędzi ręcznych, które pozwolą Ci rozwiązać większość codziennych problemów domowych. Od prostych regulacji i montażu mebli, poprzez naprawy elektryczne, aż po prace bardziej skomplikowane – zawsze będziesz mieć pod ręką odpowiednie narzędzie. Komplet Neo to oszczędność w stosunku do kupowania narzędzi osobno, a jednocześnie gwarancja, że nie zabraknie Ci niczego w krytycznym momencie. Ergonomiczny design oraz łatwa obsługa każdego elementu sprawia, że zestaw będzie wygodny zarówno dla początkujących, jak i dla doświadczonych użytkowników.\n\nPraktyczne opakowanie z organizerem sprawia, że wszystkie narzędzia pozostają zorganizowane, bezpieczne i łatwo dostępne. Możliwość przenoszenia całego kompletu oznacza, że zawsze masz potrzebne narzędzia przy sobie – w domu, w warsztacie lub w samochodzie. Niezależnie od tego, czy jesteś właścicielem domu, majsterkowiczem, czy profesjonalistą – ten zestaw z pewnością okaże się nieocenionym inwestycją, która zwróci się wielokrotnie.\n\n### Kluczowe cechy\n\n- **82 sztuki narzędzi** – kompletny zestaw zawierający wszystkie niezbędne narzędzia ręczne\n- **Uniwersalne zastosowanie** – idealne do napraw domowych, DIY, prac malarskich i montażowych\n- **Wysoka jakość materiałów** – trwałe i odporne na uszkodzenia komponenty\n- **Praktyczne opakowanie** – funkcjonalny organizer z przegródkami ułatwiający przechowywanie\n- **Ergonomiczny design** – wygodny uchwyt i prawidłowa rozplanowanie narzędzi\n- **Transportowalny komplet** – łatwy do noszenia i przenoszenia do różnych pomieszczeń\n- **Doskonały stosunek ceny do jakości** – pełne wyposażenie w przystępnej cenie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Ilość narzędzi | 82 sztuki |\n| Opakowanie | Organizer z przegródkami |\n| Materiał | Stal, tworzywo sztuczne |\n| Wymiary opakowania | Około 35 x 20 x 8 cm |\n| Cena | 512,56 PLN |\n\n---\n\n**Nie czekaj dłużej!** Komplet narzędzi Neo 82szt to inwestycja w jakość i wygodę. Dzisiaj zamów swój zestaw i ciesz się pełną gotowością do wszelkich napraw i prac domowych. Z takim wyposażeniem żaden problem domowy nie będzie dla Ciebie zbyt duży. Gwarantujemy, że ten komplet szybko stanie się niezbędnym towarzyszem każdego miłośnika DIY i praktycznego radzenia sobie w domu. **Dodaj do koszyka teraz i otrzymaj komplet narzędzi, na który czekałeś!**', '512.56', '5.39', 3, 1, 'komplet-narzedzi-neo-82szt', '2024-01-04 00:00:00'),
(49, 'Ładowarka USB Baseus 65W', 'MOT-00049', '## Ładowarka USB Baseus 65W – Szybkie i Niezawodne Ładowanie\n\nŁadowarka USB Baseus 65W to nowoczesne urządzenie, które zrewolucjonizuje sposób, w jaki ładujesz swoje urządzenia. Dzięki zaawansowanej technologii szybkiego ładowania i kompaktowemu designowi, ta ładowarka stała się niezbędnym gadżetem dla każdego, kto ceni swoją czas i produktywność. Niezależnie od tego, czy podróżujesz, pracujesz w biurze, czy odpoczywasz w domu, Baseus zapewni stabilne zasilanie dla wszystkich Twoich urządzeń.\n\nMoc 65W wystarczy, aby jednocześnie ładować smartfon, tablet i laptop bez żadnych opóźnień. Inteligentny system zarządzania energią automatycznie dostosowuje moc do podłączonego urządzenia, gwarantując optymalną prędkość ładowania i bezpieczeństwo Twoich gadżetów. Ładowarka kompatybilna jest z większością współczesnych urządzeń, od iPhone\'a, poprzez Samsunga, aż po laptopy o niższym poborze mocy.\n\nObudowa ładowarki wykonana z wytrzymałych materiałów gwarantuje długowieczność i niezawodność. Certyfikacja bezpieczeństwa i wbudowana ochrona przed przegrzaniem, przeciążeniem i zwarciem sprawiają, że możesz bez obaw zostawić ją podłączoną do prądu. Kompaktowe wymiary i lekka waga czynią ją idealnym towarzyszem do podróży – bez trudu zmieści się w każdej torbie czy plecaku.\n\n### Kluczowe cechy\n\n- **Moc 65W** – wystarczająca dla większości współczesnych urządzeń, smartfonów, tabletów i laptopów\n- **Wieloport USB** – możliwość jednoczesnego ładowania kilku urządzeń bez utraty mocy\n- **Szybkie ładowanie** – technologia QC i PD zapewniająca ultra-szybkie uzupełnianie baterii\n- **Kompaktowy design** – lekka i mała ładowarka, idealna do noszenia w torbie lub plecaku\n- **Inteligentny system zarządzania energią** – automatyczne dostosowanie mocy do podłączonego urządzenia\n- **Certyfikowana bezpieczeństwem** – ochrona przed przegrzaniem, przełądowaniem i zwarciem\n- **Kompatybilność uniwersalna** – działa z iPhone, Samsung, OnePlus, MacBook i innymi markami\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Moc wyjściowa | 65W |\n| Liczba portów | 2x USB-C / USB-A (w zależności od modelu) |\n| Certyfikacja | CE, FCC, RoHS |\n| Materiał obudowy | Polimer techniczny odporny na uszkodzenia |\n| Wymiary | ~10.5 x 5.5 x 3 cm |\n\n### Podsumowanie\n\nŁadowarka USB Baseus 65W to inwestycja, która szybko się zwróci dzięki oszczędzanemu czasowi i wygodzie. Jeśli szukasz niezawodnego, szybkiego i przenośnego urządzenia do ładowania swoich gadżetów, ta ładowarka będzie idealnym wyborem. Zapomnij o powolnym ładowaniu i niekompatybilności – Baseus dba o Twoje urządzenia jak nikt inny. **Za cenę 342,02 PLN otrzymujesz gwarancję najwyższej jakości i niezawodności przez lata użytkowania.**\n\n🔌 **Zamów teraz i ciesz się bezproblemowym ładowaniem!**', '342.02', '13.51', 3, 1, 'ladowarka-usb-baseus-65w', '2023-08-25 00:00:00'),
(50, 'Dywaniki gumowe Frogum', 'MOT-00050', '## Dywaniki gumowe Frogum - Profesjonalna ochrona podłogi samochoduZapomnij o zabrudzeniach i wilgoci w swoim aucie! Dywaniki gumowe Frogum to idealne rozwiązanie dla każdego kierowcy, który dba o czystość i wygląd wnętrza swojego pojazdu. Wykonane z wysokiej jakości materiałów gumowych, stanowią trwałą i efektywną ochronę przed błotem, śniegiem, solą i innym zabrudnieniami. Producent Frogum to znana marka na polskim rynku, specjalizująca się w akcesoriach samochodowych, która gwarantuje solidne wykonanie i długotrwałą niezawodność.\n\nDywaniki idealnie przylęgają do podłogi pojazdu dzięki specjalnej konstrukcji z wypustkami i antypoślizgowymi wstawkami. Nie będą się przesuwać podczas hamowania ani przyspieszania, zapewniając maksymalną bezpieczeństwo pasażerów. Materiał gumowy jest niezwykle łatwy w czyszczeniu - wystarczy szybko przesunąć odkurzaczem lub spłukać wodą. W przeciwieństwie do tradycyjnych dywaników tekstylnych, nie chłoną wilgoci i nie tworzą się w nich nieprzyjemne zapachy.\n\nZastosowanie tego produktu jest uniwersalne - niezależnie od tego, czy poruszasz się autami osobowymi, czy chcesz chronić wnętrze swojego samochodu użytkowego, dywaniki gumowe Frogum sprawdzą się doskonale. Szczególnie polecane są kierowcom, którzy spędzają dużo czasu w terenie, często podróżują w zimie lub mieszkają w regions o dużej wilgotności. To inwestycja w długotrwałą ochronę i komfort podczas codziennych przejazdów!\n\n### Kluczowe cechy\n\n- **Materiał wysokiej jakości** - Guma wytrzymała i elastyczna, odporna na niskie i wysokie temperatury\n- **Doskonałe przyczepienie** - Antypoślizgowe wstawki i specjalne wypustki zapobiegają przesuwaniu się dywanów\n- **Łatwa czyszczość** - Materiał gumowy nie wchłania zanieczyszczeń, szybko suszy się\n- **Uniwersalne zastosowanie** - Kompatybilne z większością modeli samochodów osobowych\n- **Trwałość** - Guma nie krakuje, nie zmienia się pod wpływem UV i zmiennych warunków pogodowych\n- **Niska cena** - Profesjonalna ochrona w przystępnej cenie\n- **Ekologiczne** - Produkty Frogum wytwarzane z uwzględnieniem norm ochrony środowiska\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | Frogum |\n| Typ produktu | Dywaniki gumowe samochodowe |\n| Materiał | Guma naturalna wzmocniona |\n| Kolor | Czarny |\n| Cena | 103,26 PLN |\n\n---\n\n**Nie czekaj! Dywaniki gumowe Frogum to niezbędny akcesoriusz dla każdego kierowcy, który szanuje swój pojazd.** Za zaledwie **103,26 PLN** otrzymujesz profesjonalną ochronę, którą będziesz używać przez lata. Zamów dzisiaj i ciesz się czystym, zadbanych wnętrzem swojego samochodu w każdych warunkach pogodowych. Dostawa często w ciągu 24 godzin - sprawdź opcje wysyłki w Twoim regionie!\n\n⭐ **Sprawdzone przez tysiące kierowców w Polsce** ⭐', '103.26', '2.36', 3, 1, 'dywaniki-gumowe-frogum', '2023-06-07 00:00:00');
INSERT INTO `products` (`id`, `name`, `sku`, `description`, `price`, `weight`, `category_id`, `active`, `image`, `created_at`) VALUES
(51, 'Odkurzacz samochodowy Xiaomi', 'MOT-00051', '## Odkurzacz samochodowy Xiaomi - Profesjonalne czyszczenie na wyciągnięcie ręki\n\nOdkurzacz samochodowy Xiaomi to rewolucyjne rozwiązanie dla każdego właściciela samochodu, którzy pragnie utrzymać wnętrze pojazdu w nienagannym stanie. To urządzenie łączy w sobie nowoczesną technologię, wydajną moc ssania i ergonomiczny design, specjalnie zaprojektowany do czyszczenia samochodów. Niezależnie od tego, czy walczysz z pyłem i piaskiem, czy też potrzebujesz usunąć okruszki i sierść zwierząt, ten odkurzacz справi się z każdym wyzwaniem. Dzięki kompaktowym wymiarom i lekkiej konstrukcji, urządzenie jest niezwykle łatwe w obsłudze, a jego bezprzewodowy system pozwala na swobodne poruszanie się po aucie bez konieczności szukania gniazdka.\n\nXiaomi zadbała o to, aby ten odkurzacz był nie tylko funkcjonalny, ale także estetyczny. Elegancki design produktu pasuje do wnętrza każdego nowoczesnego samochodu. Urządzenie wyposażone jest w zaawansowany system filtracji, który wychwytu nawet najmniejsze cząsteczki kurzu i zanieczyszczeń. Ergonomiczny uchwyt oraz precyzyjne końcówki czyszczące pozwalają dotrzeć do najtrudniejszych miejsc – między siedzeniami, w komorze na kubki czy pod dywanem. To rozwiązanie, które bezpośrednio wpływa na komfort jazdy i higienę pojazdu.\n\nNiezawodność i wydajność to cechy, na które Xiaomi nigdy nie idzie na kompromis. Potężny silnik zapewnia konsekwentną moc ssania, a pojemnik na kurz o dużej pojemności oznacza, że będziesz musiał go opróżniać znacznie rzadziej. Odkurzacz samochodowy Xiaomi to inwestycja w czystość, wygodę i długowieczność twojego pojazdu – produktu, który posłuży Ci przez lata.\n\n### Kluczowe cechy\n\n- **Wydajna moc ssania** – potężny silnik zapewnia efektywne usuwanie brudu, kurzu i zanieczyszczeń\n- **Bezprzewodowa technologia** – bateryjny system gwarantuje mobilność i swobodę ruchu po całym wnętrzu samochodu\n- **Zaawansowany system filtracji** – wielostopniowy filtr HEPA wychwytu nawet mikroskopijne cząsteczki zanieczyszczeń\n- **Kompaktowy i lekki design** – łatwy w transporcie i przechowywaniu, ergonomiczny uchwyt dla wygodnej pracy\n- **Szeroki zestaw akcesoriów** – różne końcówki czyszczące do docierania do trudno dostępnych miejsc\n- **Duża pojemność zbiornika** – rzadsze opróżnianie dzięki przestronnemu pojemniku na kurz\n- **Cicha praca** – zaawansowana izolacja dźwięku pozwala czyszczić bez hałasu i irytacji\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Moc ssania | 10 kPa |\n| Pojemność akumulatora | 2000 mAh |\n| Czas pracy | do 20 minut |\n| Pojemność zbiornika | 0,5 l |\n| Waga | 1,2 kg |\n\n---\n\n**Zamawiaj teraz Odkurzacz samochodowy Xiaomi za 555,63 PLN i ciesz się czystym samochodem każdego dnia!** To idealne rozwiązanie dla każdego kierowcy, którym zależy na komforcie i higienie. Dzięki niezawodnej konstrukcji Xiaomi i bogatemu zestawowi akcesoriów, utrzymanie czystości w aucie nigdy nie było takie łatwe. Nie czekaj – dodaj do koszyka i odkryj różnicę, jaką robi naprawdę dobry odkurzacz samochodowy!', '555.63', '4.59', 3, 1, 'odkurzacz-samochodowy-xiaomi', '2023-09-29 00:00:00'),
(52, 'Nawigacja Garmin DriveSmart 66', 'MOT-00052', '## Nawigacja Garmin DriveSmart 66 - Inteligentny Asystent Podróży\n\nGarmin DriveSmart 66 to nowoczesna nawigacja GPS, która zmienia sposób, w jaki poruszasz się po drogach. Dzięki intuicyjnemu interfejsowi, zaawansowanym funkcjom bezpieczeństwa i niezawodnym mapom, każda podróż staje się komfortowa i bezpieczna. Urządzenie łączy tradycyjną nawigację samochodową z inteligentnymi asystentami, którzy będą Twoim towarzyszem w każdej trasie.\n\nWyświetlacz o przekątnej 6 cali zapewnia doskonałą widoczność zarówno w jasne słoneczne dni, jak i w nocy. Precyzyjne obliczanie tras, dane o natężeniu ruchu w czasie rzeczywistym oraz ostrzeżenia o niebezpiecznych odcinkach drogi - wszystko to sprawia, że DriveSmart 66 to inwestycja w Twoją bezpieczeństwo. Niezależnie od tego, czy planujesz długą podróż po Polsce czy wyprawę za granicę, ta nawigacja będzie Twoim niezawodnym partnerem.\n\nSerdecznie polecamy urządzenie zarówno kierowcom dojeżdżającym do pracy, jak i miłośnikom motoryzacji podróżującym po Polsce i Europie. Intuicyjna obsługa, bogata funkcjonalność i solidna konstrukcja Garmina gwarantują zadowolenie przez wiele lat użytkowania.\n\n### Kluczowe cechy\n\n- **6-calowy ekran dotykowy** - wyraźne wyświetlanie map dzień i noc z antypoślizgową powłoką\n- **Mapy Live Traffic** - dostęp do danych o aktualnym natężeniu ruchu dla optymalnego planowania trasy\n- **Ostrzeżenia o niebezpiecznych odcinkach** - informacje o fotoradarach, wypadkach i warunkach drogowych\n- **Integracja z Garmin Cloud** - synchronizacja ulubionych miejsc, tras i kontaktów z aplikacją mobilną\n- **Łączność Bluetooth** - sparowanie ze smartfonem dla obsługi połączeń i powiadomień\n- **Aktualizacje map na całe życie** - bezpłatne i automatyczne aktualizacje map drogowych\n- **Długa żywotność baterii** - do 2 godzin pracy na baterii (w modzie standby)\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Ekran | 6 cali (15,2 cm), dotykowy, rozdzielczość 800 x 480 px |\n| Obsługiwane mapy | Europa, Polska, mapy drogowe 1:50 000 |\n| Łączność | Bluetooth, WiFi, opcjonalnie LTE |\n| Zasilanie | Zapalniczka samochodowa 12V, bateria Li-ion |\n| Wymiary | 179 x 108 x 21 mm |\n\n---\n\n**Nie czekaj dłużej!** Nawigacja Garmin DriveSmart 66 to sprawdzony wybór kierowców, którzy cenią sobie bezpieczeństwo, wygodę i niezawodność. Za **zaledwie 479,93 PLN** zyskujesz nowoczesny system nawigacyjny, który usprawni każdą Twoją podróż. Zamów teraz i niech Garmin będzie Twoim zaufanym przewodnikiem na każdym kilometrze!', '479.93', '3.01', 3, 0, 'nawigacja-garmin-drivesmart-66', '2024-02-28 00:00:00'),
(53, 'Kompas samochodowy LED', 'MOT-00053', '## Kompas samochodowy LED\n\nSposobów, aby zawsze dotrzeć do celu, jest coraz więcej – GPS, mapy w smartfonie, a jednak **kompas samochodowy LED** to klasyka, która nigdy się nie zdezorientuje. Niezawodny towarzysz każdej podróży, zarówno dla profesjonalnych kierowców, jak i dla entuzjastów offroadu. Ten kompaktowy urządzenie na desce rozdzielczej Twojego auta to gwarancja bezpieczeństwa i spokoju ducha, szczególnie gdy elektronica zawiedzie.\n\nIdealna kombinacja tradycji i nowoczesności – oświetlenie LED zapewnia doskonałą widoczność w każdych warunkach oświetleniowych, od jasnego słonecznego dnia po podróż nocną. Kompas zasilany jest niezawodnie i nie wymaga częstych wymiany baterii. Montaż na desce rozdzielczej jest niezwykle prosty i dyskretny – urządzenie nie zajmuje dużo miejsca, a jego elegancki design pasuje do wnętrza każdego samochodu, niezależnie od marki czy rocznika.\n\nNie zależy od zasięgu sieci, lokalizacji czy dostępu do internetu – zawsze wskaże Ci kierunek północy. Przydatny nie tylko jako awaryjny system nawigacji, ale także doskonały gadżet dla miłośników podróży, turystyki samochodowej i przygód poza utartymi szlakami. Kompas samochodowy LED to inwestycja w bezpieczeństwo i niezawodność, którą warto mieć przy sobie w każdej chwili.\n\n### Kluczowe cechy\n\n- 🧭 **Precyzyjna orientacja** – niezawodnie wskazuje kierunki kardynalne niezależnie od warunków\n- 💡 **Oświetlenie LED** – doskonała widoczność zarówno w dzień jak i w nocy\n- 🚗 **Prosty montaż** – łatwa instalacja na desce rozdzielczej bez konieczności serwisu\n- 🔋 **Niezawodne zasilanie** – długa żywotność baterii i stabilna praca\n- 📦 **Kompaktowy design** – niewielkie rozmiary, elegancki wygląd, pasuje do każdego wnętrza\n- ⚠️ **System awaryjny** – niezastąpiony, gdy GPS zawiedzie lub braknie zasięgu\n- 🌍 **Uniwersalność** – idealne dla podróżników, kierowców zawodowych i turystów\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Typ urządzenia | Kompas z oświetleniem LED |\n| Zasilanie | Bateria (wymiana rzadka) |\n| Rodzaj montażu | Na desce rozdzielczej |\n| Oświetlenie | LED |\n| Wymiary | Kompaktowe (nie zajmuje dużo miejsca) |\n| Cena | 244,68 PLN |\n\n---\n\n**Nie czekaj!** Kompas samochodowy LED to niezastąpiony towarzysz każdej podróży. Zamów teraz za jedynie **244,68 PLN** i poczuj spokój, wiedząc, że zawsze będziesz wiedzieć, gdzie się kierujesz. Darmowa dostawa na terenie Polski! ✅ Gwarantowana jakość ✅ Szybka wysyłka ✅ Zadowolenie gwarancją!', '244.68', '1.98', 3, 1, 'kompas-samochodowy-led', '2023-12-17 00:00:00'),
(54, 'Zestaw pierwszej pomocy DIN', 'MOT-00054', '## Zestaw pierwszej pomocy DIN\n\n### Niezawodny opiekun Twojego zdrowia – zawsze pod ręką!\n\nZestaw pierwszej pomocy DIN to profesjonalny, kompletnie wyposażony pakiet pierwszorazowej pomocy medycznej, idealny dla każdego gospodarstwa domowego, samochodu, biura czy działalności gospodarczej. Zestaw został przygotowany zgodnie z niemieckimi normami DIN (Deutsches Institut für Normung), które gwarantują najwyższy standard bezpieczeństwa i efektywności. Dzięki przemyślanej zawartości będziesz przygotowany na wszelkie drobne urazy, zadrapania, oparzenia i inne nagłe sytuacje wymagające natychmiastowego udzielenia pierwszej pomocy.\n\nKompaktowy rozmiar zestawu sprawia, że bez problemu zmieści się w każdym kącie – czy to w szafce łazienkowej, schowku samochodu, biurku, czy plecaku. Solidne, trwałe opakowanie chroni zawartość przed uszkodzeniami, wilgocią i zabrudzeniami, a intuicyjny układ produktów ułatwia szybkie znalezienie potrzebnego artykułu w sytuacji nagłej. Dzięki temu zestawowi masz pewność, że gdy coś się stanie – będziesz bezpieczny i przygotowany.\n\nInwestycja w zestaw pierwszej pomocy DIN to inwestycja w zdrowotny spokój ducha Ciebie i Twojej rodziny. Za zaledwie **75 PLN** zyskujesz profesjonalne wyposażenie, na którym zawsze możesz polegać. Nie czekaj na kryzys – kup dzisiaj i bądź zawsze gotów!\n\n### Kluczowe cechy\n\n- ✅ **Standard DIN** – zestaw spełnia międzynarodowe normy niemieckie dla zestawów pierwszej pomocy\n- ✅ **Kompletna zawartość** – gaziki, plastry, bandaże elastyczne, maść antybiotykowa, środek dezynfekujący i wiele więcej\n- ✅ **Kompaktowy rozmiar** – łatwy do przenoszenia i przechowywania w domu, aucie lub biurze\n- ✅ **Trwałe opakowanie** – pudełko ochronne chroni zawartość przed uszkodzeniami i wilgocią\n- ✅ **Intuicyjny układ** – wszystkie materiały systematycznie ułożone dla szybkiego dostępu\n- ✅ **Uniwersalne zastosowanie** – idealne dla rodzin, firm, pojazdów i instytucji\n- ✅ **Przystępna cena** – profesjonalna jakość w przystępnej cenie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Standard** | DIN (Deutsches Institut für Normung) |\n| **Cena** | 75 PLN |\n| **Wymiary opakowania** | Kompaktowe (dostosowane do przechowywania) |\n| **Zawartość** | Kompleksowy zestaw materiałów medycznych (gaziki, plastry, bandaże, maść, dezynfekcja i inne) |\n| **Przeznaczenie** | Dom, samochód, biuro, firmy, instytucje |\n\n---\n\n### Podsumowanie\n\nZestaw pierwszej pomocy DIN to gwarancja bezpieczeństwa dla Ciebie i Twoich bliskich. Kompletny, profesjonalnie wyposażony i przystępnie wyceniony – zawsze będziesz przygotowany na wszelkie nieprzewidziane sytuacje. **Zamów dzisiaj za 75 PLN i zyskaj spokój ducha na każdy dzień!**', '75.00', '3.68', 3, 1, 'zestaw-pierwszej-pomocy-din', '2023-12-17 00:00:00'),
(55, 'Pokrowce na fotele Miarowe', 'MOT-00055', '## Pokrowce na fotele Miarowe\n\nPokrowce na fotele Miarowe to idealne rozwiązanie dla każdego, kto chce odświeżyć wygląd swojego salonu lub gabinetu bez konieczności wymiany mebli. Wykonane z wysokiej jakości materiałów, stanowią perfekcyjną kombinację stylu, funkcjonalności i trwałości. Niezależnie od tego, czy chcesz ochronić swoje ulubione fotele przed zabrudzeniami, czy po prostu nadać im nowy, świeży wygląd – te pokrowce to idealny wybór dla Ciebie.\n\nNasze pokrowce charakteryzują się doskonałym dopasowaniem do standardowych rozmiarów foteli, zapewniając elegancki i profesjonalny wygląd. Dzięki miarowym wymiarom możesz być pewien, że pokrowiec będzie idealnie pasować do Twojego mebla bez zbędnych fałdów i przesunięć. Materiał jest odporny na zmęcie, pilling i pranie, co gwarantuje długotrwałe użytkowanie. Pokrowce łatwo się zdejmują i prają, a po wysuszeniu przywracają się do pierwotnego kształtu, nie wymagając skomplikowanego prasowania.\n\nSprawdzą się zarówno w domu, jak i w biurze, restauracji czy salonie. Chronią meble przed codziennym zużyciem, zabrudzeniami od zwierzątek domowych, śladami od dzieci czy przypadkowymi plamami. Są też świetnym rozwiązaniem na przejściowe okresy, gdy chcesz zmienić aranżację wnętrza bez dużych inwestycji. Wystarczy zmienić pokrowce, a atmosfera w pokoju zmienia się diametralnie!\n\n### Kluczowe cechy\n\n- ✅ **Doskonałe dopasowanie** – Miarowe wymiary gwarantują idealną aplikację na wszystkie standardowe fotele\n- ✅ **Łatwo zdejmowalne** – Konstrukcja umożliwia szybkie zdejmowanie i pranie bez uszkodzenia mebla\n- ✅ **Trwały materiał** – Odporny na przecieranie, pilling i deformacje nawet przy intensywnym użytkowaniu\n- ✅ **Praktyczne w pielęgnacji** – Można prać w pralce w niskiej temperaturze, szybko wysychają\n- ✅ **Uniwersalny design** – Neutralny kolor dopasuje się do każdego wnętrza i stylu aranżacji\n- ✅ **Ochrona mebli** – Chroni przed brudem, zabrudzeniami, śladami zwierząt i dzieci\n- ✅ **Ekonomiczny zakup** – Tańsze od renowacji mebli, a efekt wciąż imponujący\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Typ produktu** | Pokrowiec miarowy na fotel |\n| **Materiał** | Wysokokvalitetna tkanina mieszana |\n| **Wymiary** | Miarowe – dopasowanie do standardowych foteli |\n| **Pranie** | 30°C, pralka automatyczna |\n| **Cena** | 705,75 PLN |\n\n---\n\nPokrowce na fotele Miarowe to inwestycja w schludność Twojego domu i długowieczność mebli. Dzięki nim Twoje fotele będą wyglądać jak nowe przez lata, a Ty będziesz mieć spokój, że są dobrze chronione. Nie czekaj – dodaj do koszyka już teraz i ciesz się nowym wyglądem swojej salony za zaledwie **705,75 PLN**. Gwarancja zadowolenia i bezpłatny zwrot w przypadku niezadowolenia! 🛋️', '705.75', '5.69', 3, 1, 'pokrowce-na-fotele-miarowe', '2023-09-30 00:00:00'),
(56, 'Apteczka samochodowa Plus', 'MOT-00056', '## Apteczka samochodowa Plus\n\nBezpieczeństwo to priorytet każdego kierowcy. **Apteczka samochodowa Plus** to profesjonalnie wyposażony zestaw pierwszej pomocy, który powinien znajdować się w każdym pojeździe. Niezależnie od tego, czy wybierasz się w krótką podróż po mieście czy długą trasę międzypaństwową, ta apteczka zapewni Ci spokój ducha i gotowość do działania w nagłych wypadkach. Produkt spełnia wszystkie obowiązujące normy bezpieczeństwa i zawiera starannie dobrane materiały medyczne najwyższej jakości.\n\nZawartość apteczki została opracowana we współpracy z profesjonalistami z branży medycznej i ratownictwa. Każdy element został umieszczony w solidnym, kompaktowym opakowaniu, które łatwo zmieści się w schowku samochodowym lub bagażniku. Dzięki przejrzystej organizacji szybko znajdziesz wszystko, co potrzebujesz w chwili kryzysu. Apteczka Plus to inwestycja w bezpieczeństwo Ciebie i Twoich bliskich — rzecz, której nie możesz sobie pozwolić na brak.\n\nCzy w aucie pasażera, czy zawodowego – **Apteczka samochodowa Plus** to niezbędny dodatek, który może uratować nie tylko zdrowie, ale i życie. Wiele osób kupiło już ten produkt i nie żałuje – jest to najpopularniejszy wybór wśród kierowców poszukujących niezawodnego zestawu pierwszej pomocy. Nie czekaj na nadzwyczajną sytuację – zabezpiecz się dziś!\n\n### Kluczowe cechy\n\n- ✅ **Kompleksowy zestaw** – zawiera bandaże, opaski, wata, plastry, maści i instrumenty medyczne\n- ✅ **Certyfikowany produkt** – spełnia normy DIN 13164 i wymogi polskiego prawa\n- ✅ **Trwałe opakowanie** – solidny futerał z laminowanego materiału, odporny na warunki pogodowe\n- ✅ **Łatwy dostęp** – przejrzysta organizacja elementów dla szybkiego znalezienia potrzebnych materiałów\n- ✅ **Uniwersalne zastosowanie** – odpowiednia dla każdego rodzaju pojazdu (samochód osobowy, ciężarowy, dostawczy)\n- ✅ **Gotowa do użytku** – wszystkie materiały sterylne i bezpieczne\n- ✅ **Przystępna cena** – najlepszy stosunek jakości do ceny na rynku\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Apteczka samochodowa Plus |\n| Cena | 734,80 PLN |\n| Wymiary opakowaniem | ok. 24 x 15 x 10 cm |\n| Waga | ok. 1,2 kg |\n| Normy | DIN 13164, zgodnie z polskim prawo |\n\n---\n\n**Zadbaj o bezpieczeństwo Twoje i Twoich pasażerów – zamów Apteczkę samochodową Plus już dziś!** Za niespełna 735 złotych zyskujesz pewność, że w każdej sytuacji będziesz przygotowany. To najlepszy prezent dla siebie lub bliskiego kierowcy. Dostawa w 24-48 godzin, bezpieczne opakowanie, gwarancja zadowolenia. **Nie zwlekaj – Twoja bezpieczna podróż zaczyna się tutaj!**', '734.80', '1.54', 3, 1, 'apteczka-samochodowa-plus', '2023-11-13 00:00:00'),
(57, 'Trójkąt ostrzegawczy refleks', 'MOT-00057', '## Trójkąt ostrzegawczy refleks - profesjonalny zestaw bezpieczeństwa\n\nTrójkąt ostrzegawczy refleks to niezbędny element wyposażenia każdego pojazdu, gwarantujący bezpieczeństwo na drodze w każdych warunkach atmosferycznych. Dzięki zaawansowanej technologii refleksyjnej, produkt zapewnia doskonałą widoczność dnia i nocy, ostrzegając innych uczestników ruchu o przeszkodzie lub niebezpieczeństwie. Odpowiadając wymogom polskiego kodeksu ruchu drogowego, ten trójkąt jest obowiązkowym elementem w każdym pojeździe, szczególnie podczas długich podróży czy postoju na drodze szybkiego ruchu.\n\nNasz trójkąt jest wykonany z najwyższej jakości materiałów, odpornych na działanie warunków pogodowych i UV. Refleksyjne paski zostały przygotowane z wykorzystaniem nowoczesnych technologii, które zapewniają maksymalną widoczność z odległości nawet do 300 metrów. Dzięki lekkiej i trwałej konstrukcji, produkt jest łatwy w transporcie i składaniu, a jednocześnie niezawodny w każdej sytuacji awaryjnej. Zarówno początkujący kierowcy, jak i doświadczeni profesjonaliści polecają ten model za jego niezawodność i wartość.\n\nZastosowanie trójkąta ostrzegawczego refleks jest niezwykle szerokie - od oznaczenia miejsca awarii pojazdu, przez sygnalizację niebezpieczeństwa na drodze, aż po zastosowanie w budownictwie czy podczas prac drogowych. Dzięki trójkątnej formie i czerczewo-białej kolorystyce, produkt jest natychmiast rozpoznawalny dla wszystkich kierowców. Niezależnie od pory dnia lub warunków oświetlenia, trójkąt będzie efectywnie ostrzegać o zagrożeniu.\n\n### Kluczowe cechy\n\n- **Wysoka refleksyjność** - widoczny z odległości do 300 metrów dzięki zaawansowanej technologii refleksyjnej\n- **Zgodność z prawem** - spełnia wszystkie wymogi polskiego kodeksu ruchu drogowego i normy europejskie\n- **Odporność na warunki atmosferyczne** - wytrzymały na deszcz, śnieg, słońce i zmienne temperatury\n- **Łatwe magazynowanie** - składana konstrukcja zajmuje minimalnie miejsca w bagażniku pojazdu\n- **Uniwersalne zastosowanie** - idealne dla samochodów osobowych, ciężarowych, motorowerów i ciężkich maszyn\n- **Lekkość i wytrzymałość** - wykonany z wzmocnionych materiałów o najwyższej jakości\n- **Intuicyjna obsługa** - szybkie ustawienie bez konieczności użycia dodatkowych narzędzi\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Typ produktu | Trójkąt ostrzegawczy refleks |\n| Wymiary | 50 x 50 x 50 cm |\n| Materiał | Plastik wzmocniony + refleks |\n| Kolor | Czerwony / Biały |\n| Normy | PN-EN ISO 20471, wymogi kodeksu ruchu drogowego |\n| Cena | 571,93 PLN |\n\n---\n\n**Nie czekaj na awarię!** Zapewnij sobie i swoim bliskim maksimum bezpieczeństwa na drodze. Trójkąt ostrzegawczy refleks to inwestycja w spokój i ochronę. Za zaledwie **571,93 PLN** otrzymujesz profesjonalny produkt, który może uratować życie. Dodaj do koszyka już teraz i ciesz się pełnym bezpieczeństwem podczas każdej podróży! 🚗✨', '571.93', '5.76', 3, 0, 'trojkat-ostrzegawczy-refleks', '2023-06-06 00:00:00'),
(58, 'Kable rozruchowe 600A', 'MOT-00058', '## Kable Rozruchowe 600A\n\nProfesjonalne kable rozruchowe o maksymalnym natężeniu 600A to niezbędny sprzęt w każdym pojeździe. Dzięki im jesteś zawsze przygotowany na nieprzewidziane sytuacje na drodze, kiedy bateria pojazdu ulegnie rozładowaniu. Nasze kable rozruchowe łączą najwyższą jakość wykonania z niezawodnością, którą mogą potwierdzić tysiące zadowolonych użytkowników. Gwarancja bezpieczeństwa i wydajności sprawia, że inwestycja w ten produkt to jeden z mądrzejszych zakupów dla kierowcy.\n\nKable zostały wykonane z miedzi najwyższej jakości, która zapewnia optymalną przewodność elektryczną i minimalne straty energii podczas uruchamiania silnika. Grube, elastyczne osłony miedziane odporują na rozdarcia, zagięcia i wpływy temperatury, co gwarantuje długotrwałą żywotność produktu nawet w najtrudniejszych warunkach atmosferycznych. Niezależnie od pory roku — czy to mroźna zima, czy gorące lato — kable zawsze będą gotowe do działania.\n\nZastosowanie jest uniwersalne — sprawdzą się w samochodach osobowych, dostawczych, a także w motocyklach i innych pojazdach wyposażonych w baterie 12V lub 24V. Intuicyjna obsługa oraz krótkie czasy podłączenia sprawiają, że każdy kierowca bez problemu skorzysta z tego produktu. To pozycja obowiązkowa w każdym bagażniku, na każdy wyjazd, niezależnie od długości trasy.\n\n### Kluczowe cechy\n\n- **Natężenie 600A** – moc wystarczająca do uruchomienia większości pojazdów osobowych i lekkich dostawczych\n- **Kable miedziane o dużym przekroju** – zapewniają maksymalną przewodność i minimalny opór elektryczny\n- **Długość 3,5 metra** – idealna do łatwego podłączenia między pojazdami\n- **Izolacja gumowa** – odporna na niskie temperatury, światło słoneczne i wilgoć\n- **Zaciskami biegnowymi** – solidne połączenie gwarantujące niezawodny kontakt\n- **Etui transportowe** – wygodne przechowywanie i przenoszenie\n- **Certyfikat CE** – potwierdzenie zgodności z europejskimi normami bezpieczeństwa\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Natężenie maksymalne | 600A |\n| Długość kabli | 3,5 m |\n| Materiał przewodu | Miedź natywna 99,9% |\n| Przekrój przewodu | 25 mm² |\n| Napięcie znamionowe | 12V / 24V |\n| Temperatura pracy | -30°C do +80°C |\n\n---\n\nJeśli regularnie korzystasz z samochodu, nie możesz pozwolić sobie na brak tego produktu w wyposażeniu pojazdu. Kable rozruchowe 600A to gwarancja spokoju i bezpieczeństwa na każdej trasie. Za niewiele ponad **364,57 PLN** otrzymujesz profesjonalny sprzęt, który będzie Ci służyć latami. Zaufaj jakości, wybierz niezawodność – dodaj do koszyka już teraz i ciesz się spokojem ducha!\n\n**⭐ Kupuj z pewnością – bezpłatna dostawa, 14 dni na zwrot!**', '364.57', '0.78', 3, 1, 'kable-rozruchowe-600a', '2023-09-07 00:00:00'),
(59, 'Odmrażacz do szyb K2 Alaska', 'MOT-00059', '## Odmrażacz do szyb K2 Alaska - 336.66 PLN\n\n### Opisowy wstęp\nZimą każdy kierowca staje przed wyzwaniem zamarznięcia szyb samochodu. Odmrażacz do szyb K2 Alaska to profesjonalne rozwiązanie, które szybko i efektywnie usuwa lód, śnieg i oszron z powierzchni okien, lusterek i reflektorów. Jego potężna formuła działa już po kilku sekundach, oszczędzając Ci cennego czasu podczas pośpiesznych poranków. K2 to marka zaufana przez tysiące kierowców w całej Europie, gwarantująca niezawodność i wysoką jakość.\n\n### Sprawdzony sposób na czystość szyb\nDzięki zaawansowanej formule opartej na alkoholu i specjalnych rozpuszczalnikach, K2 Alaska rozpuszcza nawet najtrudniejsze osady lodowe bez potrzeby energicznego skrobania, które może uszkodzić gumki wycieraczek czy powierzchnię lakieru. Produkt działa w temperaturach nawet do -40°C, co czyni go niezastąpionym w polskich, mroźnych zimach. Zawarte w sprayu substancje zapobiegają również ponownemu zamarznięciu szyb przez kilka godzin, zapewniając Ci lepszą widoczność na całą drogę.\n\n### Praktyczne zastosowanie\nOdmrażacz K2 Alaska nadaje się do wszystkich rodzajów pojazdów: samochodów osobowych, dostawczych, motocykli i maszyn budowlanych. Wygodny format sprayu umożliwia szybkie aplikowanie produktu bezpośrednio na szybę czy lusterko. Jedną puszką można odmrozić powierzchnie wielokrotnie, co czyni ją niezwykle ekonomiczną. Produkt zawiera również połysk, który pozostawia na szkle ochronną warstwę i poprawia estetykę.\n\n### Kluczowe cechy\n\n- **Szybkie działanie** – eliminuje lód i oszron w zaledwie kilka sekund\n- **Ekstremalny zakres temperatur** – skuteczny do -40°C, idealny na polska zimę\n- **Bezpieczny dla lakieru** – formuła delikatna dla powłok ochronnych pojazdu\n- **Długotrwała ochrona** – zapobiega ponownemu zamarznięciu na kolejne godziny\n- **Uniwersalne zastosowanie** – sprawdza się na szybach, lusterach i reflektorach\n- **Efektywna ekonomiczna opakowanie** – jedna puszka wystarczy na długi sezon\n- **Przyjemny zapach** – zawiera świeży aromat podczas użytkowania\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | K2 |\n| Nazwa produktu | Alaska |\n| Typ | Odmrażacz do szyb w sprayu |\n| Temperatura działania | Od -40°C |\n| Opakowanie | Puszka/spray |\n| Cena | 336.66 PLN |\n\n### Podsumowanie\n\nOdmrażacz K2 Alaska to inwestycja w bezpieczeństwo i wygodę jazdy podczas zimy. Za sprawdzą cenę 336.66 PLN otrzymujesz profesjonalny produkt marki światowej, któremu ufają kierowcy na całym kontynencie. Nie czekaj na pierwsze mrozy – zamów teraz i rusz pewnie w każde zimowe ranki! **Dodaj do koszyka i ciesz się czystymi, bezpiecznymi szybach przez całą zimę.**', '336.66', '3.30', 3, 1, 'odmrazacz-do-szyb-k2-alaska', '2023-10-10 00:00:00'),
(60, 'Odświeżacz powietrza Areon', 'MOT-00060', '## Odświeżacz powietrza Areon\n\nZapewnij sobie świeże i czyszczące powietrze w każdym pomieszczeniu dzięki nowoczesnym odświeżaczom **Areon** – produktom cieszącym się renomą wśród polskich konsumentów. Ten wyjątkowy odświeżacz to połączenie zaawansowanej technologii z naturalnym aromatem, który sprawia, że każdy moment spędzony w domu, biurze czy samochodzie staje się przyjemniejszy. Areon doskonale eliminuje nieprzyjemne zapachy, a jednocześnie pozostawia po sobie delikatny, świeży zapach, który utrzymuje się długo. Produkt został starannie opracowany, aby zagwarantować maksymalną efektywność i długotrwałe działanie.\n\nNiezależnie od tego, czy borykasz się z zapachami kuchennymi, petfood czy musisz szybko odświeżyć przestrzeń przed ważnym spotkaniem – Areon to idealny wybór. Odświeżacz powietrza Areon sprawdzi się perfekcyjnie w mieszkaniu, domu, biurze, akademiku czy nawet w samochodzie. Jego dyskretny design pozwala mu harmonijnie wписać się w każde wnętrze, nie zaburzając estetyki. Gwarancja wysokiej jakości i długotrwałego efektu czyni ten produkt inwestycją wart każdego grosza.\n\nWybierając Areon, decydujesz się na sprawdzony produkt, który od lat dba o świeżość powietrza w polskich domach. Jego uniwersalne zastosowanie, trwałość oraz wyjątkowa funkcjonalność czynią go hitem wśród miłośników czystego powietrza. Niezawodny, elegancki i ekonomiczny – to wszystko w jednym produkcie!\n\n### Kluczowe cechy\n\n- **Długotrwały efekt** – freski utrzymuje się przez wiele tygodni, zapewniając nieustanny komfort\n- **Skuteczna eliminacja zapachów** – neutralizuje nieprzyjemne zapachy, nie maskując je, a eliminując na poziomie molekularnym\n- **Naturalne składniki** – produkowany z myślą o Twojej rodzinie i środowisku\n- **Uniwersalne zastosowanie** – idealny do domu, biura, samochodu, łazienki i kuchni\n- **Elegancki design** – dyskretny wygląd, który nie rzuca się w oczy i pasuje do każdego wnętrza\n- **Łatwy w użyciu** – bezzakładowy system, wystarczy otworzyć i umieścić w wybranym miejscu\n- **Ekonomiczny** – jeden odświeżacz działa długo, co gwarantuje doskonały stosunek ceny do jakości\n\n### Specyfikacja\n\n| Aspekt | Szczegóły |\n|--------|-----------|\n| **Nazwa produktu** | Odświeżacz powietrza Areon |\n| **Cena** | 713,11 PLN |\n| **Rodzaj** | Odświeżacz powietrza do wnętrz |\n| **Czas działania** | Do 4-6 tygodni (w zależności od wielkości pomieszczenia) |\n| **Zastosowanie** | Dom, biuro, samochód, mieszkanie |\n\n---\n\n**Nie czekaj dłużej!** Zamów dzisiaj swój Areon i odkryj, jak wielką różnicę może wnieść świeże powietrze w Twoją codzienność. Tysiące zadowolonych klientów już zaufało tej marce – dołącz do nich teraz! Gwarancja zadowolenia i niezawodna jakość czekają na Ciebie. **Areon – bo zasługujesz na świeżość każdego dnia!**\n', '713.11', '8.37', 3, 1, 'odswiezacz-powietrza-areon', '2023-07-19 00:00:00'),
(61, 'Kawa ziarnista Lavazza 1kg', 'JED-00061', '## Kawa ziarnista Lavazza 1kg - Włoska Jakość w Twojej Filiżance\n\nOdkryj autentyczny smak włoskiej kawy najwyższej jakości dzięki Lavazza – liderowi branży kawiarskiej od 1895 roku. Ta starannie wyselekcjonowana mieszanka ziaren z najlepszych plantacji świata gwarantuje Ci niezapomniane doświadczenie kawowe każdego dnia. Kawa Lavazza to nie tylko pyszny napój, ale także tradycja, doskonałość oraz dbałość o każdy szczegół procesu produkcji. Opakowanie 1kg to idealna porcja dla miłośnika kawy, zapewniająca świeżość i intensywny aromat przez długi czas.\n\nKażdego ranka możesz cieszyć się bogatym, pełnym nuansów smakiem, który zwróci Ci energię i poprawi nastrój. Mieszanka Lavazza charakteryzuje się harmonijną równowagą między kwaśnością a słodyczą, z subtelnym posmmakiem czekolady i orzechów. Niezależnie od tego, czy prepasujesz kawę w tradycyjnym ekspresie, przelewaczem czy French pressem – każda metoda zaparcia wyniesie Ci do nieba. Ten produkt to gwarancja, że nigdy nie będziesz skazany na nudną, bezbarwną kawę ze zwyczajnych paczek.\n\nLavazza to synonim italskiego stylu życia i życzliwości do drugiego człowieka – każdy łyk to małe święto zmysłów. Zamów teraz i przekonaj się sam, dlaczego ta marka ma miliony wiernych fanów na całym świecie. Idealna dla każdej rodziny, każdego biura i każdej chwili, w której chcesz podnieść sobie nastrój.\n\n### Kluczowe cechy\n\n- ✓ **Włoska kawa premium** – 100% najwyższej jakości ziaren arabiki i robusty z renomowanego producenta\n- ✓ **Porcja 1kg** – wystarczająca ilość kawy na kilka tygodni codziennego użytku\n- ✓ **Uniwersalna do wszystkich metod zaparcia** – ekspres, przelewacz, turka, French press\n- ✓ **Bogaty, złożony smak** – harmonia nuansów z nutami czekolady i orzechów\n- ✓ **Świeża, aromat aromatyczna** – świeża zawartość opakowania gwarantuje świeżość\n- ✓ **Dobrze zbilansowana kwaśność** – delikatna, przyjemna dla podniebienia\n- ✓ **Godna polecenia dla kawoszy** – zarówno dla początkujących, jak i doświadczonych miłośników kawy\n\n### Specyfikacja\n\n| Parametr | Opis |\n|----------|------|\n| **Producent** | Lavazza S.p.A. (Włochy) |\n| **Masa netto** | 1000g (1kg) |\n| **Forma** | Ziarna całe |\n| **Stopień mielenia** | Brak (ziarna całe – możliwość mielenia na zamówienie) |\n| **Cena** | 57,38 PLN |\n\n---\n\n**Nie czekaj – zamów teraz Kawę ziarniştą Lavazza 1kg i ciesz się najlepszą kawą na rynku!** Za zaledwie **57,38 PLN** otrzymujesz słoik pełen włoskiej doskonałości i zapachu, który napełni Twoją kuchnię. Każdego poranka zamiast monotonnego poranku będziesz miał moment czystej przyjemności. Dołącz do tysięcy zadowolonych klientów i podnieś swoją codzienną czarę kawy na zupełnie nowy poziom. **Dziś to najlepszy dzień, aby zmienić swoją poranną rutynę!**', '57.38', '5.70', 4, 1, 'kawa-ziarnista-lavazza-1kg', '2024-04-08 00:00:00'),
(62, 'Herbata Lipton Yellow Label 100szt', 'JED-00062', '## Herbata Lipton Yellow Label 100szt\n\nOdkryj klasyczną herbatę, która od ponad 130 lat cieszy się zaufaniem milionów konsumentów na całym świecie. **Herbata Lipton Yellow Label** to idealny wybór dla tych, którzy cenią sobie wysoką jakość, konsekwentny smak i niezawodność. Każda torebka zawiera starannie wyselekcjonowane liście herbaty, które zapewniają aromatyczną i orzeźwiającą porcję doskonałości w każdej filiżance.\n\nTa ciepła herbata łączy delikatną lekkość z wyrafinowanym smakiem, który sprawdzi się zarówno o poranku, jak i wieczorem. Lipton Yellow Label pochodzi z najlepszych plantacji na świecie, dzięki czemu każda porcja gwarantuje intensywny aromat i bogatą, złotą barwę naparu. Herbata ta idealnie sprawdza się na każdą porę dnia — od pobudki z filiżanką przy śniadaniu, przez przerwę w pracy, aż po wieczorny relaks z książką czy rozmowę z bliskimi.\n\nOpakowanie zawierające aż **100 torebek** zapewnia długotrwałą dostawę tego ulubionego trunku dla całej rodziny. Praktyczne torebki jednorazowe to gwarancja świeżości, higieny i wygody — bez konieczności przygotowywania kruszyn herbaty czy czyszczenia zaparzaczy. Inwestuj w herbatę, którą pił jeszcze Twój dziadek, a która nadal pozostaje niewzruszoną królową na światowych rynkach.\n\n### Kluczowe cechy\n\n- **100 torebek** – pełne opakowanie zapewniające miesięczny lub dłuższy zapas dla każdego miłośnika herbaty\n- **Klasyczny, pełny smak** – mieszanka z wybranych plantacji gwarantuje konsekwentną jakość i aromatyczność\n- **Łatwa w użyciu** – pojedyncze torebki idealne do zaparzania w domu, biurze, szkole czy podróży\n- **Zbilansowany skład** – czarna herbata bez dodatkowych składników, idealna dla purystów\n- **Marka zaufania** – ponad 130 lat tradycji i ekspertyzy w produkcji herbaty\n- **Przyjazna cena** – najbardziej ekonomiczna opcja dla budżetowych zakupów na dłuższy okres\n- **Łatwo dostępna** – rozpoznawalna na całym świecie marka dostępna zawsze i wszędzie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Ilość torebek | 100 szt. |\n| Rodzaj herbaty | Czarna, mieszanka |\n| Format opakowania | Torebki jednorazowe |\n| Pochodzenie | Międzynarodowe plantacje |\n| Waga orientacyjna | ok. 200g |\n\n---\n\n**Herbata Lipton Yellow Label 100szt to inwestycja w codzienny komfort i przyjemność!** Nie czekaj – dodaj to opakowanie do koszyka już dzisiaj i ciesz się nieograniczoną ilością porcji perfekcyjnie zaparzanej herbaty za zaledwie **5 PLN**. Niezawodna jakość, przystępna cena i marka, której ufają miliony – to wszystko czeka na Ciebie. Zamawiaj teraz i odkryj, dlaczego Lipton Yellow Label to najpopularniejsza herbata na świecie! ☕', '5.00', '5.86', 4, 1, 'herbata-lipton-yellow-label-100szt', '2024-05-09 00:00:00'),
(63, 'Makaron Lubella Penne 500g', 'JED-00063', '## Makaron Lubella Penne 500g\n\nMakaron Lubella Penne to doskonały wybór dla każdego miłośnika włoskiej kuchni i tradycyjnych makaronów najwyższej jakości. Wykonany z najlepszego durum pszenicy, charakteryzuje się idealnym kształtem tuby z ukośnie ścietymi końcami, który doskonale gromadzi sosy i dodatkowe składniki. Każda porcja to gwarancja autentycznego smaku i konsystencji, która sprawdzi się zarówno w domowej kuchni, jak i w bardziej wyrafinowanych daniach. Makaron Lubella od ponad 30 lat pozostaje zaufaną marką polskich gospodarstw domowych, a jego jakość jest wynikiem długiej tradycji i dbałości o szczegóły.\n\nPenne to uniwersalna forma makaronu, która świetnie sprawdza się w praktycznie każdym przepisie – od prostych sosów pomidorowych, poprzez kremowe preparaty, aż po zaawansowane dania z dodatkami. Dzięki swojej strukturze makaron idealnie przyjmuje aromaty i smaki towarzyszących składników, tworząc harmonijne całości. Produkt przechowuje się długo dzięki hermetycznemu opakowaniu, które chroni go przed wilgocią i utlenianiem. To idealna opcja dla osób ceniących jakość, smak i wygodę przygotowania pełnowartościowego posiłku w zaledwie kilkadziesiąt minut.\n\nNasze penne to także odpowiedzialny wybór – bezpieczeństwo żywności i etyczne podejście do produkcji są dla nas priorytetem. Makaron przechodzi surowe kontrole jakości, a każda paczka zawiera produktem perfekcyjnie wysuszony, bez przesychania i pękania ziaren. Niezależnie od tego, czy przygotowujesz szybki obiad w środku tygodnia, czy specjalny posiłek dla bliskich – makaron Lubella Penne nigdy Cię nie zawiedzie.\n\n### Kluczowe cechy\n\n- 🌾 **100% naturalny makaron** – wykonany wyłącznie z durum pszenicy, bez sztucznych dodatków i konserwantów\n- ⏱️ **Czas gotowania: 9-11 minut** – szybkie przygotowanie bez kompromisu w stosunku do smaku\n- 📦 **Praktyczne opakowanie 500g** – idealne dla 2-3 osób, każdorazowe porcje\n- 🍝 **Idealny kształt do sosów** – tuby Penne doskonale gromadzą sosy i powstają pyszne połączenia smakowe\n- ✅ **Gwarancja świeżości** – hermetyczne opakowanie chroni przed wilgocią i zachowuje smak\n- 🏆 **Zaufana marka od 1992 roku** – tradycja i jakość w każdym ziarnie\n- 💪 **Bogaty w węglowodany i białko** – pełnowartościowy posiłek dla całej rodziny\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Makaron Lubella Penne 500g |\n| **Zawartość** | 500 gramów |\n| **Czas gotowania** | 9-11 minut |\n| **Skład** | Mąka z pszenicy durum (100%) |\n| **Cena** | 46,08 PLN |\n\n---\n\n**Nie czekaj na idealny moment – zamów teraz makaron Lubella Penne i odkryj, dlaczego miliony Polaków ufają tej marce!** Przygotuj szybki obiad w środek tygodnia, imponujący danie na kolację czy romantyczną wieczorność – to wszystko możliwe dzięki wysokiej jakości makaronu, któremu możesz zawsze zaufać. Makaron Lubella to inwestycja w smak, zdrowotne odżywianie i radość płynącą z pysznego jedzenia. Dodaj do koszyka i doświadcz różnicy! 🍝', '46.08', '9.60', 4, 1, 'makaron-lubella-penne-500g', '2023-12-30 00:00:00'),
(64, 'Oliwa z oliwek Bertolli 500ml', 'JED-00064', '## Oliwa z oliwek Bertolli 500ml\n\nOliwa z oliwek Bertolli to premia-class produkt dla każdego miłośnika zdowej żywności i autentycznych włoskich smaków. Butelka zawierająca 500ml czystej, wysokiej jakości oliwy pochodzącej z najlepszych maślanic Włoch to gwarancja doskonałego smaku i aromatu w każdej kuchni. Bertolli to marka z tradycją sięgającą 1865 roku, która specjalizuje się w produkcji naturalnych oliw, stawiając na najwyższą jakość surowca i autentyczne metody produkcji. Każdej kropli towarzyszy suma dekad doświadczenia w wyborze i przetwarzaniu oliwek.\n\nOliwa Bertolli wyróżnia się bogatym, złotistym kolorem oraz delikatnym aromatem, który doskonale komponuje się zarówno z daniami mięsnymi, rybami, sałatkami, jak i chlebem czy sosami. Za sprawą optymalnego stosunku kwasów tłuszczowych i naturalnych antyoksydantów, ta oliwa nie tylko wspomaga zdrowe odżywianie, ale także dodaje niezapominanego smaku Twoim codziennym potrawom. Wiele restauracji w Polsce i na świecie poleca właśnie tę matkę marek oliwy – sprawdzony wybór dla wymagających podniebień.\n\nInwestycja w Bertolliego to decyzja na długoterminowe wzbogacenie Twojej kuchni. Praktyczna butelka 500ml jest idealna zarówno dla rodzin, jak i dla samotnych osób, które pragną jakości bez przesady ilościowej. Czy przygotowujesz włoskie dania, czy po prostu chcesz podnieść standard co-dziennych potraw – ta oliwa stanie się Twoją stałą bazą w kuchni.\n\n### Kluczowe cechy\n\n- **Autentyczna włoska oliwa** – producent z tradycją od 1865 roku\n- **Pojemność 500ml** – idealna wielkość dla średniostoletniej rodziny\n- **Naturalny skład** – bez dodatków konserwujących, 100% oliwa\n- **Bogatty aromat i złocisty kolor** – świadczą o wysokiej jakości\n- **Wielozastosowaniowa** – do sałatek, mięs, ryb, piekarni i sosów\n- **Bogata w antyoksydanty** – wspomaga zdrową dietę\n- **Elegancka butelka** – idealna jako prezent dla miłośnika dobrego jedzenia\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Producent | Bertolli |\n| Pojemność | 500 ml |\n| Typ | Oliwa z oliwek |\n| Pochodzenie | Włochy |\n| Cena | 17,76 PLN |\n\n---\n\n**Nie czekaj – spraw sobie odrobinę włoskiego luksusu!** Oliwa z oliwek Bertolli 500ml to inwestycja, która zwróci się każdym posiłkiem pełnym autentycznego smaku. Zamów teraz i przekonaj się, dlaczego miliony osób na całym świecie wybiera tę markę. Przy cenie zaledwie **17,76 PLN** to niezwykle okazja na produktu world-class jakości. Dodaj do koszyka i ciesz się włoskim urokiem w swojej kuchni już dzisiaj!', '17.76', '5.25', 4, 1, 'oliwa-z-oliwek-bertolli-500ml', '2024-03-20 00:00:00'),
(65, 'Ryż Basmati Tao Tao 1kg', 'JED-00065', '## Ryż Basmati Tao Tao 1kg\n\nOdkryj smak autentycznego, aromatycznego ryżu basmati najwyższej jakości! Ryż Basmati Tao Tao to idealne połączenie tradycji i nowoczesności – starannie wybrany, czyszczony i pakowany, aby dostarczyć do Twojej kuchni prawdziwy luksus w formie długoziarnistego ryżu. Znany z całego świata, ryż basmati jest ulubionym wyborem profesjonalnych szefów kuchni i домашних kucharzy, którzy wiedzą, że tylko najlepszy ryż da im niepowtarzalny smak dań.\n\nKażdy ziarenka ryżu Basmati Tao Tao zachowuje swoją delikatną strukturę podczas gotowania, pozostając rozdzielonym, puszystym i pachnącym. Gotuje się równomiernie dzięki idealnemu rozmiarowi ziaren, a jego naturalny aromat dodaje elegancji każdemu posiłkowi – od klasycznego pilau, przez indyjskie curry, aż po azjatyckie smażone ryże. Ryż basmati to gwarancja udanego dania, niezależnie od Twojego doświadczenia kulinarnego.\n\nOpakowanie 1kg to idealna ilość dla rodziny – wystarczająco dużo, aby przygotować wiele porcji bez marnotrawstwa, a zarazem nie zajmuje zbyt wiele miejsca w szafce. Ryż Basmati Tao Tao jest nie tylko pyszny, ale także zdrowszy – zawiera cennych substancji odżywczych, a naturalnie nie zawiera glutenu. Świetnie smakuje zarówno jako dodatek do mięsa i warzyw, jak i jako samodzielna baza dla wegetariańskich potraw.\n\n### Kluczowe cechy\n\n- **Długoziarnisty basmati** – autentyczny ryż z charakterystycznym aromatem\n- **Naturalnie pachnący** – wyjątkowy, delikatny zapach podkreślający każde danie\n- **Puszysty po gotowaniu** – ziarna pozostają rozdzielone i nie kleją się do siebie\n- **100% naturalny** – bez dodatków, konserwantów i sztucznych barwników\n- **Opakowanie 1kg** – praktyczna wielkość na wiele posiłków\n- **Łatwy w przygotowaniu** – gotuje się w około 15-20 minut\n- **Uniwersalny** – doskonały do kuchni indyjskiej, azjatyckiej i światowej\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Nazwa produktu** | Ryż Basmati Tao Tao |\n| **Waga opakowania** | 1 kg |\n| **Typ ryżu** | Basmati długoziarnisty |\n| **Czas gotowania** | 15-20 minut |\n| **Cena** | 31,79 PLN |\n\n---\n\nNie czekaj dłużej! Ryż Basmati Tao Tao 1kg to inwestycja w smaczne, zdrowsze posiłki dla całej rodziny. W tej cenie znajdziesz prawdziwą jakość, którą docenisz od pierwszego wariantu. Dodaj do koszyka dziś i ciesz się restauracyjnym smakiem w wygodzie własnego domu. **Promocyjna cena 31,79 PLN** – to okazja, którą warto złapać! 🍚✨', '31.79', '3.00', 4, 1, 'ryz-basmati-tao-tao-1kg', '2023-10-10 00:00:00'),
(66, 'Dżem Łowicz Truskawkowy 280g', 'JED-00066', '## Dżem Łowicz Truskawkowy 280g\n\nOdkryj niepowtarzalny smak prawdziwych truskawek w każdym kęsie! Dżem Łowicz Truskawkowy to doskonały wybór dla wszystkich miłośników tradycyjnych smaków, którzy cenią naturalność i jakość. Przygotowany z najlepszych owoców, bez sztucznych barwników i konserwantów, dżem Łowicz od ponad 40 lat zdobywa serca polskich rodzin. Każdy słoik zawiera 280g czystej truskawkowej radości – doskonałej zarówno do chleba, bułek, jak i do pieczenia oraz deserów.\n\nŁowicz to marka związana z autentyczną polską tradycją kulinarną. Dżem przygotowywany jest zgodnie ze sprawdzonym recepturam, która gwarantuje intensywny smak oraz naturalną konsystencję. Zawartość wyraźnych kawałków owoców oraz bogata zawartość pektyny sprawia, że dżem ma idealną teksturę – ani za rzadki, ani zbyt gęsty. To idealny dodatek do śniadania, a także niezbędny składnik do domowych wypieków i dżemów.\n\nNiezależnie od pory roku, dżem Łowicz Truskawkowy to gwarancja smaku, który pamiętacie z dzieciństwa. Prosty, naturalny i pyszny – taki, jaki powinien być dżem. Idealne rozwiązanie dla osób, które nie chcą kupować tego w supermarkecie co tydzień, a wolą mieć zapas ulubionego smaku w swoim domu. Jeden słoik zawsze za mało!\n\n### Kluczowe cechy\n\n- **Naturalne owoce** – przygotowany z truskawek bez sztucznych dodatków i konserwantów\n- **Tradycyjna receptura** – sprawdzona metoda produkcji gwarantująca autentyczny smak\n- **Idealna konsystencja** – naturalnie gęsty, łatwy do smarowania, z kawałkami owoców\n- **Uniwersalne zastosowanie** – do chleba, bułek, sernika, ciast, naleśników i lodów\n- **Wygodne opakowanie** – słoik 280g, łatwo przechowywać w kuchni\n- **Bezpieczeństwo** – produkt kontrolowany, gwarancja jakości Łowicza\n- **Doskonały smak** – intensywny aromat truskawki, prawdziwy polskiej roboty\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Dżem Łowicz Truskawkowy |\n| Wielkość opakowania | 280g |\n| Główny składnik | Truskawki |\n| Zastosowanie | Do chleba, bułek, wypieki, desery |\n| Cena | 9,01 PLN |\n\n---\n\n**Podsumowanie:**\n\nDżem Łowicz Truskawkowy 280g to ponad 40 lat tradycji i zaufania polskich rodzin w jednym słoiku! Jeśli szukasz produktu o nieprzeciętnym smaku, naturalnych składnikach i godnej cenie – to idealna propozycja dla Ciebie. Za zaledwie **9,01 PLN** otrzymujesz czysty, naturalny smak truskawek, który uatrakcyjni każde śniadanie. Nie czekaj – dodaj do koszyka i ciesz się prawdziwym dżemem już dziś! 🍓\n\n', '9.01', '8.75', 4, 1, 'dzem-lowicz-truskawkowy-280g', '2023-10-21 00:00:00'),
(67, 'Mąka tortowa Poznańska 1kg', 'JED-00067', '## Mąka tortowa Poznańska 1kg\n\nMąka tortowa Poznańska to idealny wybór dla wszystkich miłośników pieczenia, którzy pragną osiągnąć profesjonalne rezultaty w domowej kuchni. Ta specjalistyczna mąka, tradycyjnie wytworzona w sercu Wielkopolski, stanowi kwintesencję jakości i doświadczenia wielopokoleniowego piekarsko-cukierniczego rzemiosła. Wyjątkowo delikatna tekstura i starannie wyselekcjonowana pszenica gwarantują doskonałe wyniki zarówno przy pieczeniu tortów, ciastek, jak i wypieków półkruche.\n\nMąka tortowa Poznańska wyróżnia się niską zawartością glutenu i specjalnie opracowanym składem, który zapewnia idealne rozpuszczanie się składników oraz uzyskanie puszystej, lekkiej struktury wypieku. Każda porcja mąki pochodzi z kontrolowanych źródeł i przechodzi rygorystyczną kontrolę jakości, co gwarantuje konsekwentne rezultaty przy każdym pieczeniu. Dzięki tej mące Twoje torty będą miały doskonałą wilgotność, aksamitną strukturę i niezapomniany smak, który zachwycać będzie rodzinę i gości.\n\nProdukt zawiera opakowanie o pojemności 1 kg, które gwarantuje świeżość dzięki specjalnie zaprojektowanemu opakowaniu z ochroną przed wilgocią. Mąka tortowa Poznańska świetnie sprawdza się zarówno w bisekontkach, makowcach, jak i w nowoczesnych tortach dekoracyjnych. To must-have dla każdej domowej piekarni, niezależnie od poziomu umiejętności kulinarnych.\n\n### Kluczowe cechy\n\n- **Niska zawartość glutenu** – gwarantuje puszystą i delikatną strukturę wypieku\n- **Tradycyjna receptura Poznańska** – sprawdzona metoda produkcji przez dziesięciolecia\n- **Idealna do tortów i ciastek** – specjalnie opracowana formuła dla słodkich wypieków\n- **Opakowanie 1 kg** – praktyczny rozmiar, świeże produkty zawsze przy ręce\n- **Kontrolowana jakość** – każda partia przechodzi rygorystyczną weryfikację\n- **Bez dodatków sztucznych** – czysty, naturalny skład\n- **Długa trwałość** – szczelne opakowanie chroniące przed utlenianiem i wilgocią\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Pojemność | 1 kg |\n| Typ | Mąka tortowa specjalistyczna |\n| Pochodzenie | Poznań, Polska |\n| Zawartość glutenu | Niska (poniżej 10%) |\n| Opakowanie | Worek papierowo-foliowy |\n| Przechowywanie | W suchym, chłodnym miejscu |\n\n---\n\n**Nie czekaj dłużej na idealne wypieki!** Mąka tortowa Poznańska w cenie **74,23 PLN** to inwestycja w jakość i smak, którą wycenić można znacznie wyżej. Dziesiątki tysięcy zadowolonych piekarzy domowych już na nią postawili. Dodaj do koszyka teraz i odkryj nowy wymiar pieczenia torów i ciastek! ✨\n\n---\n\n*Szybka dostawa, gwarancja świeżości, bezpieczeństwo zakupu. Zamawiaj teraz!*', '74.23', '0.15', 4, 1, 'maka-tortowa-poznanska-1kg', '2024-02-01 00:00:00');
INSERT INTO `products` (`id`, `name`, `sku`, `description`, `price`, `weight`, `category_id`, `active`, `image`, `created_at`) VALUES
(68, 'Miód pszczeli wielokwiatowy 500g', 'JED-00068', '## Miód pszczeli wielokwiatowy 500g\n\n### Opis produktu\n\nNasz **miód pszczeli wielokwiatowy** to naturalny lek darowany przez matkę naturę i pracowite pszczoły. Ten wyjątkowy produkt zbierany jest z różnorodnych kwiatów łąk i pól, co nadaje mu bogatą paletę smaków oraz niezwykłe właściwości zdrowotne. Każda szklanka tego złotego nektaru to skoncentrowana moc witamin, minerałów i naturalne substancje czynne, które przez wieki przypisywano wzmacniającym i leczniczym właściwościom.\n\nMiód wielokwiatowy wyróżnia się swoją wszechstronnością i uniwersalnym stosowaniem w codziennym życiu. Dzięki bogatej zawartości enzymów, aminokwasów i pierwiastków śladowych stanowi doskonały dodatek do diety każdego człowieka – zarówno dorosłych, jak i dzieci. Jego naturalny skład i brak sztucznych dodatków czynią go bezpiecznym i zaufanym produktem dla całej rodziny. Miód naturalnie wspomaga odporność organizmu, poprawia energię i witalność, a także wspiera regenerację po intensywnych wysiłkach fizycznych.\n\nPolecamy go zarówno do codziennych poranków – roztopiony w mleku czy herbacie – jak i jako składnik do home-made\'owych kosmetyków, mask upiększających czy naturalnych leków na kaszel. Jego głębokie smaki i aromat sprawią, że stanie się on niezbędnym produktem w każdej kuchni. Gdzie indziej w Polsce nie znajdziecie tak bogatego w składniki i delikatnie rozpieszczającego podniebienie miodu za taką cenę!\n\n### Kluczowe cechy\n\n- ✅ **100% naturalny produkt** – bez konserwantów, barwników ani sztucznych dodatków\n- ✅ **Wielokwiatowy** – zbierany z rozlicznych kwiatów łąk i pól, bogaty smak i aromat\n- ✅ **Wzmacnia odporność** – zawiera naturalne witaminy, minerały i przeciwutleniacze\n- ✅ **Uniwersalne zastosowanie** – do picia, gotowania, kosmetyków i tradycyjnych sposobów na zdrowotność\n- ✅ **Praktyczne opakowanie 500g** – wystarczająca ilość dla całej rodziny\n- ✅ **Świeży, niedogrzewany** – delikatnie przetworzony, zachowuje wszystkie wartości odżywcze\n- ✅ **Zweryfikowana jakość** – produkt z rzetelnych, lokalnych źródeł\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Rodzaj miodu | Wielokwiatowy (polifloral) |\n| Waga netto | 500g |\n| Opakowanie | Szklana słoik |\n| Jakość | 100% naturalny |\n| Cena | 72,96 PLN |\n\n### Podsumowanie\n\nJeśli szukasz wysokiej jakości miodu, który będzie wspierać Twoją zdrowotność i zachwycać gustem, ten produkt jest dokładnie dla Ciebie! Nasz miód pszczeli wielokwiatowy to inwestycja w zdrowie Twojej rodziny i codzienną przyjemność polegania na naturze. Za zaledwie **72,96 PLN** otrzymujesz produkt o niezaprzeczalnej wartości, który posłuży Ci przez wiele dni – zarówno do kuchni, jak i do naturalnej pielęgnacji. Nie czekaj dłużej – **dodaj do koszyka teraz** i doświadcz magii prawdziwego, polskiego miodu! 🍯', '72.96', '2.74', 4, 1, 'miod-pszczeli-wielokwiatowy-500g', '2023-10-01 00:00:00'),
(69, 'Masło Łaciate Extra 200g', 'JED-00069', '## Masło Łaciate Extra 200g\n\nOdkryj niezawodną jakość i autentyczny smak z Masłem Łaciatym Extra! Produkt o ponad dziesięcioletniej tradycji na polskim rynku, który zdobył zaufanie milionów gospodarstw domowych. To masło o najwyższej zawartości tłuszczu mlecznego stanowi idealny wybór dla każdej kuchni. Niezależnie od tego, czy przygotowujesz śniadanie dla rodziny, czy piekasz wypieki na specjalną okazję, Masło Łaciate Extra zapewni doskonały smak i kremeńką konsystencję, którą pokochasz. Opakowanie 200g to idealna wielkość do pracy w kuchni – wystarczająca dla kilku dni użytku, ale nie zajmująca zbyt dużo miejsca w lodówce.\n\nMasło Łaciate Extra to gwarancja najwyższego gatunku i naturalnego składu. Wytwarzane z mleka od zaufanych dostawców, poddawane ścisłym kontrolom jakości, zawiera wyłącznie naturalne składniki bez sztucznych additywów czy konserwantów. Jego bogatą, pełnowartościową zawartość tłuszczu mlecznego docenią zarówno amatorzy tradycyjnej polskiej kuchni, jak i hobby cookerzy eksperymentujący z międzynarodowymi przepisami. Każde użycie Masła Łaciatego Extra to pewność, że serwujesz swoim bliskim produkt premium, któremu można całkowicie zaufać.\n\nUniwersalność to kolejna zaleta tego masła! Doskonale sprawdza się do codziennych zastosowań: na piecu do naleśników, racuchów i placków, w smażeniu warzyw, mяса czy serów, a także jako dodatek do kaszy czy ziemniaków. Przy podejmowaniu decyzji o wyborze masła – pamiętaj, że inwestujesz w smak i zdrowotne wartości. Masło Łaciate Extra to wybór świadomych konsumentów, którzy nie idzą na kompromisy.\n\n### Kluczowe cechy\n\n- ✓ **Najwyższa zawartość tłuszczu mlecznego** – co najmniej 82% tłuszczu mlecznego, zapewniające kremową konsystencję\n- ✓ **Naturalne składniki** – bez sztucznych konserwantów, barwników i additywów\n- ✓ **Uniwersalne zastosowanie** – idealne do pieczenia, smażenia, jako dodatek do dań\n- ✓ **Tradycyjna receptura** – opracowana przez polskich specjalistów, zaufana od lat\n- ✓ **Wygodne opakowanie** – 200g to idealna wielkość dla małych i dużych gospodarstw\n- ✓ **Gwarantowana świeżość** – każda porcja przechowywana w optymalnych warunkach\n- ✓ **Wzbogacone o naturalne witaminy** – zawiera witaminy rozpuszczalne w tłuszczu: A, D i E\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Masło Łaciate Extra 200g |\n| Zawartość tłuszczu mlecznego | Min. 82% |\n| Wielkość opakowania | 200g |\n| Typ | Masło naturalne, niesolone |\n| Termin przydatności | 60 dni od daty wyprodukowania |\n\n---\n\n**Nie czekaj – zamawiaj Masło Łaciate Extra już dziś!** Za niecałe 11 złotych otrzymujesz gwarancję doskonałej jakości, którą będziesz wykorzystywać każdego dnia. Polecane przez kucharek, mam domowych i profesjonalistów branży gastronomicznej. Jeśli szukasz masła, na którym możesz polegać, **Masło Łaciate Extra to Twój ideał**. Dodaj do koszyka teraz i doświadcz różnicy w smaku! 🧈', '10.91', '2.69', 4, 0, 'maslo-laciate-extra-200g', '2023-07-08 00:00:00'),
(70, 'Ketchup Włocławek 480g', 'JED-00070', '## Ketchup Włocławek 480g\n\nOdkryj autentyczny smak polskiego ketchupu, który doskonale uzupełni Twoje ulubione potrawy! **Ketchup Włocławek** to produkt o bogatej tradycji, wytwarzany zgodnie ze sprawdzoną recepturą. Intensywny, słodko-kwaśny smak oraz gęsta konsystencja sprawiają, że każda porcja jest prawdziwą przyjemnością. Niezawodny towarzysz każdego posiłku - od smażonych ziemniaków, przez hamburgery, aż po domowe mięsiwa i grille.\n\nWysoka jakość składników oraz starannie dobrane proporcje przypraw gwarantują niezapomniany smak, który rozpoznasz od pierwszego użycia. Ketchup Włocławek powstaje z dojrzałych pomidorów, cukru i aromatycznych przypraw, bez niepotrzebnych dodatków. To produkt idealny dla całej rodziny - czy to dla dzieci do porcji frytek, czy dla dorosłych jako dodatek do mięsiwa lub grillowanych potraw. Opakownie 480g to rozsądna wielkość, która gwarantuje świeżość produktu i komfortowe przechowywanie w lodówce.\n\nBezproblemowe dozowanie dzięki praktycznemu opakowaniu z bezzałamywaną tubą to kolejna zaletę tego produktu. Ketchup łatwo wychodzi z opakowania, nie pozostawiając osadu na ściankach. Przechowywany w chłodnym miejscu zachowuje swoją świeżość i intensywny smak przez długi czas. To wydajna ilość, która wystarczy na wiele posiłków, bez ryzyka zmarnowania produktu.\n\n### Kluczowe cechy\n\n- ✓ **Tradycyjna receptura** – autentyczny, sprawdzony smak polskiego ketchupu\n- ✓ **Gęsta konsystencja** – idealna do namaczania, nie cieknie z opakowania\n- ✓ **Zawartość 480g** – optymalna wielkość dla jednoosobowego lub małego gospodarstwa domowego\n- ✓ **Bez sztucznych barwników i konserwantów** – naturalny skład sprzyjający zdrowiu\n- ✓ **Uniwersalne zastosowanie** – pasuje do frytek, mięsiwa, hamburgerów, grillowanych potraw\n- ✓ **Praktyczne opakowanie** – łatwe do dozowania i przechowywania\n- ✓ **Atrakcyjna cena** – najlepszy stosunek jakości do ceny na rynku\n\n### Specyfikacja\n\n| Parametr | Opis |\n|----------|------|\n| **Nazwa produktu** | Ketchup Włocławek |\n| **Pojemność** | 480g |\n| **Cena** | 6,49 PLN |\n| **Przechowywanie** | W chłodnym, suchym miejscu; po otwarciu przechowywać w lodówce |\n| **Termin przydatności** | Podany na opakowaniu |\n\n---\n\n**Nie czekaj dłużej!** Dodaj Ketchup Włocławek do Twojego koszyka i ciesz się niezapomnianym smakiem tradycji w każdym posiłku. Za taką cenę to naprawdę okazja, którą warto wykorzystać. Przechowuj w lodówce, sięgaj zawsze, gdy masz ochotę na coś smacznego. Polecamy szczególnie miłośnikom autentycznych, polskich produktów i osobom, które cenią sobie dobrą relację jakości do ceny. **Zamów dziś i smakuj polskiego klasyka!**', '6.49', '8.44', 4, 1, 'ketchup-wloclawek-480g', '2023-06-10 00:00:00'),
(71, 'Ogórki kiszone Społem 900ml', 'JED-00071', '## Ogórki kiszone Społem 900ml\n\nPolskie ogórki kiszone to klasyk każdej kuchni i niezbędny dodatek na stole! Produkty marki Społem od lat cieszą się zaufaniem polskich konsumentów dzięki tradycyjnej recepturze i najwyższej jakości surowców. Nasze ogórki kiszone Społem 900ml to perfekcyjna kombinacja chrupiącego mięsa ogórka i aromatycznego, złożonego zalewu. Każde opakowanie zawiera starannie wyselekcjonowane owoce podane w klasycznej, tradycyjnej kompozycji przypraw, która zachwycała już pokolenia polskich rodzin.\n\nNiezależnie od tego, czy szukasz dodatku do obiadowego stołu, czy poszukujesz idealnego towarzysza do kanapek i przysmaków, ogórki Społem sprawdzą się idealnie. Ich uniwersalność poleca się zwłaszcza miłośnikom autentycznych smaków i tradycyjnej kuchni polskiej. Dzięki starannej fermentacji i konserwacji, produkty Społem zachowują naturalny smak oraz chrupkość przez długi czas, gwarantując najlepszą jakość od momentu otwarcia opakowania.\n\nOgórki kiszone Społem to również praktyczna forma produktu — 900ml to wygodna pojemność, idealna zarówno do szybkiego spożycia jak i przechowywania w lodówce. Słoik ze stelażem pozwala na łatwe wyjmowanie produktu i utrzymanie świeżości przez dłuższy czas. To idealne rozwiązanie dla osób, które cenią sobie tradycję, jakość i niezawodny smak w każdym kęsku.\n\n### Kluczowe cechy\n\n- **Tradycyjna receptura** — klasyczne ogórki kiszone przygotowane wg sprawdzonego przepisu Społemu\n- **Pojemność 900ml** — praktyczne opakowanie, idealne dla rodziny\n- **Chrupiące owoce** — ogórki zachowują naturalną strukturę i konsystencję\n- **Aromatyczne zalewanie** — kompozycja przypraw i octu, która podkreśla autentyczny smak\n- **Naturalny produkt** — bez sztucznych konserwantów i barwników\n- **Marka zaufania** — ponad 80 lat tradycji Społemu na rynku polskim\n- **Uniwersalne zastosowanie** — idealne do mięs, serów, kanapek i jako samodzielny dodatek\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Marka | Społem |\n| Pojemność | 900ml |\n| Typ produktu | Ogórki kiszone |\n| Przechowywanie | Lodówka po otwarciu |\n| Termin przydatności | Zgodnie z datą na opakowaniu |\n\n---\n\n**Nie czekaj, zamawiaj teraz!** Ogórki kiszone Społem 900ml to inwestycja w smaczne, tradycyjne jedzenie, które ukocha całą Twoja rodzina. Za zaledwie **61,77 PLN** otrzymujesz produkt premium, który przez dekady był stałym elementem polskich stołów. Dodaj do koszyka teraz i ciesz się autentycznym smakiem tradycyjnych ogórków kisonych — gwarantowaną jakością i zadowoleniem!\n\n---\n\n✅ **Szybka dostawa** • ✅ **Bezpieczne opakowanie** • ✅ **Satysfakcja gwarantowana**', '61.77', '9.99', 4, 1, 'ogorki-kiszone-spolem-900ml', '2024-05-28 00:00:00'),
(72, 'Pierogi ruskie mrożone 450g', 'JED-00072', '## Pierogi ruskie mrożone 450g\n\nOdkryj smak autentycznych pierogów ruskich prosto z Twojej kuchni! Nasze pierogi mrożone to idealne rozwiązanie dla każdego, kto ceni sobie tradycyjny polski smak, ale nie ma czasu na przygotowanie pierogów od podstaw. Każda porcja to doskonały balans miękkiego ciasta z aksamitnym wypełnieniem z białego sera, ziemiaków i cebuli. Pierogi ruskie to klasyka polskiej kuchni, która od pokoleń cieszy się niesłabnącą popularnością na polskich stołach. Teraz możesz cieszyć się tym tradycyjnym daniem w dowolnym momencie – wystarczy szybka obróbka termiczna, a gotowe!\n\nPierogi ruskie to uniwersalny produkt, który sprawdzi się zarówno na co dzień, jak i podczas specjalnych okazji. Mogą stanowić pełnoprawny obiad, doskonałe danie główne, ale także przepyszną kolację dla całej rodziny. Podawaj je ze smietaną, cebulą na maśle lub boczkiem – każda kombinacja gwarantuje niezapomniane doznania kulinarne. Produkt jest już gotowy do spożycia, co czyni go idealnym wyborem dla osób zajętych, studentów i każdego miłośnika tradycyjnych smaków. Szybkość przygotowania nie wpływa na jakość – nasze pierogi zachowują autentyczny smak i konsystencję.\n\nZamrażanie to naturalny sposób konserwacji, który doskonale chroni smak i właściwości odżywcze produktu. Pierogi ruskie z naszej oferty są wykonane z najwyższej jakości składników, zgodnie z tradycyjną recepturą. Opakowanie o pojemności 450g zawiera idealną ilość na obiad dla 2-3 osób, co gwarantuje brak marnowania żywności. Przechowywanie w zamrażalce zapewnia długotrwałą свежość produktu, a łatwa porcjowanie pozwala na przygotowanie dokładnie tyle, ile potrzebujesz.\n\n### Kluczowe cechy\n\n- **Tradycyjny przepis** – autentyczne pierogi ruskie z białym serem, ziemniakami i cebulą\n- **Gotowe do spożycia** – wystarczy gotowanie w wodzie lub smażenie na maśle (5-7 minut)\n- **Mrożone** – naturalny sposób konserwacji zachowujący świeżość i smak\n- **Praktyczne opakowanie** – 450g to idealna porcja na obiad dla 2-3 osób\n- **Bez konserwantów sztucznych** – produkt z naturalnymi składnikami\n- **Wszechstronne zastosowanie** – idealne jako danie główne, obiad lub kolacja\n- **Długa przydatność** – przechowywanie w zamrażalce zapewnia dostępność przez wiele miesięcy\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Zawartość netto | 450g |\n| Rodzaj produktu | Pierogi mrożone |\n| Skład | Ciasto (mąka, woda, jaja), farsz (biały ser, ziemniaki, cebula) |\n| Warunki przechowywania | Temperatura -18°C lub niższa |\n| Czas przygotowania | 5-7 minut |\n| Cena | 61,49 PLN |\n\n---\n\n**Nie czekaj na lepszą okazję!** Pierogi ruskie mrożone 450g to gwarancja smacznego, szybkiego i sycącego posiłku zawsze pod ręką. Za zaledwie **61,49 PLN** otrzymujesz tradycyjny polski przysmaek, który zadowoli całą rodzinę. Dodaj produkt do koszyka już teraz i ciesz się autentycznym smakiem pierogów ruskich w domowym zaciszu. Szybka dostawa, najwyższa jakość, gwarantowana świeżość – to wszystko czeka na Ciebie!', '61.49', '0.70', 4, 1, 'pierogi-ruskie-mrozone-450g', '2023-08-14 00:00:00'),
(73, 'Barszcz czerwony Krakus 1L', 'JED-00073', '## Barszcz czerwony Krakus 1L\n\n### Opis produktu\n\nBarszcz czerwony Krakus to tradycyjny polski barszcz o bogatym, pełnym smaku, przygotowany według sprawdzonego przepisu z najwyższej jakości buraków. Produkt marki Krakus to gwarancja autentyczności i doskonałego smaku, który towarzysza polskim rodzinom od pokoleń. Każda porcja tego aromatycznego zupy niesie ze sobą urok domowej kuchni i tradycyjnych smaków, które sprawiają, że barszcz Krakusa stanowi idealne uzupełnienie każdego stołu.\n\nDzięki starannie dobranym składnikom i precyzyjnej technologii produkcji, barszcz zachowuje naturalny, głęboki kolor oraz intensywny, charakterystyczny smak burakowy. To rozwiązanie, które pozwoli Ci zaoszczędzić czas na kuchni, nie rezygnując z jakości i autentyczności tradycyjnego polskiego potrawy. Opakowanie 1L to idealna ilość dla 4-5 osób, zapewniająca doskonałą proporcję do potraw głównych lub zup.\n\nBarszcz Krakus sprawdzi się nie tylko jako porcja zupy, ale również jako idealny dodatek do barszczu żurku, kiszonki czy jako delikatna główka do innych potraw. Jego wszechstronność i łatwe stosowanie uczyniają go niezbędnym elementem domowej spiżarni dla każdego miłośnika tradycyjnej kuchni polskiej.\n\n### Kluczowe cechy\n\n- **Autentyczny smak** – tradycyjny przepis marki Krakus, sprawdzony przez pokolenia Polaków\n- **Naturalne składniki** – przygotowany z wysokiej jakości buraków, bez sztucznych konserwantów\n- **Praktyczne opakowanie** – pojemność 1L idealnie sprawdza się dla rodzinnego posiłku (4-5 porcji)\n- **Gotowy do podania** – nie wymaga długiego gotowania, wystarczy podgrzać i podać do stołu\n- **Uniwersalne zastosowanie** – doskonały jako samoistna zupa, dodatek do żurku lub składnik innych potraw\n- **Długi termin przydatności** – odpowiednie przechowywanie zapewnia świeżość produktu\n- **Polskiej marki** – Krakus to marka zaufana od lat, gwarantująca najwyższą jakość\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Producent | Krakus |\n| Objętość | 1000 ml (1L) |\n| Typ produktu | Barszcz czerwony gotowy do spożycia |\n| Rodzina produktu | Zupy i sosy tradycyjne |\n| Cena | 78,83 PLN |\n\n---\n\n### Warto wiedzieć\n\nBarszcz Krakusa to inwestycja w tradycję i smak! Czy planujesz przygotować szybki obiad dla rodziny, czy szukasz autentycznego dodatku do swojej kuchni? Ten barszcz doskonale rozwiąże Twoje problemy. Zamów teraz i ciesz się polskim smakiem w każdą porę dnia. Najwyższa jakość w najlepszej cenie – to kwintesencja marki Krakus!\n\n**Nie czekaj – dodaj do koszyka i odkryj, dlaczego Krakus to wybór polskich rodzin od lat!**', '78.83', '8.77', 4, 1, 'barszcz-czerwony-krakus-1l', '2023-08-25 00:00:00'),
(74, 'Kabanosy Tarczyński 120g', 'JED-00074', '## Kabanosy Tarczyński 120g\n\nKabanosy Tarczyński to klasyka polskiego krajobrazu kulinacyjnego, którą pokochały miliony Polaków. Te aromatyczne, wędzące drażetki wykonane z najwyższej jakości mięsa drobiowego stanowią idealną przekąskę do piwa, kawy, czy po prostu na każdą chwilę, gdy pragniemy czegoś smacznego i nasyćającego. Pakowanie 120g to doskonały rozmiar do noszenia w plecaku, torebce czy kamizelce rybackiej. Kabanosy od czterdziestolecia pozostają liderem na polskim rynku, a to nie przypadek – to jest synonim jakości, tradycji i niezawodnego smaku.\n\nWędzone na dymie naturalnym, ze starannie wyselekcjonowanymi przyprawami, każdy kababos Tarczyński gwarantuje intensywne, głębokie doświadczenie smakowo-aromatyczne. Struktura mięsa jest doskonale elastyczna, nie sucha ani nie tłusta – każdy ugryzienie roztapia się w ustach, pozostawiając niepowtarzalny, naddany pokoleniami smak. Produkt zawiera bogatą mieszankę białka, a jego kaloryjność sprawia, że stanowi doskonałą alternatywę dla ciężkich przekąsek – zaraz po spożyciu czuć się będziesz nasycony i zadowolony.\n\nKabanosy Tarczyński to nie tylko przekąska – to symbol polskiego patriotyzmu kulinarnego, dostępny w każdym sklepie, na każdej imprezie i w każdym domu. Niezależnie, czy jesteś pracownikiem biurowym szukającym szybkiego posiłku, wędkarzem na łowach, czy po prostu miłośnikiem autentycznych polskich smaków – te kabanosy są dla Ciebie. Opakowanie 120g to idealna wielkość, która nie zajmuje wiele miejsca, a pozwala cieszyć się tym produktem bez obawy o psute się mięso.\n\n### Kluczowe cechy\n\n- 🔥 **Tradycyjna receptura** – produkowane od ponad 40 lat wg. sprawdzonej receptury\n- 🌿 **Naturalne wędzenie** – dym naturalny z drewna, bez sztucznych dodatków smakowych\n- 💪 **Wysokoproteinowe** – bogaty w białko, idealny dla aktywnych osób\n- 📦 **Praktyczne opakowanie** – 120g to idealna porcja do codziennego noszenia\n- ✨ **Aromatyczne i smaczne** – niepowtarzalny, głęboki smak z doskonałą strukturą\n- 🥩 **Najwyższa jakość mięsa** – tylko drób premium z kontrolowanych źródeł\n- ⏱️ **Długi termin przydatności** – doskonały do przechowywania w szafce lub plecaku\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Waga netto** | 120g |\n| **Cena** | 49,33 PLN |\n| **Główny składnik** | Mięso drobiowe |\n| **Termin przydatności** | Do 6 miesięcy od daty produkcji* |\n| **Przechowywanie** | W temperaturze pokojowej (przed otwarciem) |\n\n*Termin przydatności podany w opakowaniu\n\n---\n\n**Nie czekaj – zdobądź paczkę autentycznych Kabanosów Tarczyński jeszcze dzisiaj!** Za zaledwie **49,33 PLN** otrzymujesz niezawodną, sprawdzoną przez pokolenia przekąskę, która będzie idealna do pracy, szkoły, wędrówek czy po prostu wieczoru przy telewizorze. Polska smakołyka najwyższej klasy czeka już w Twoim koszyku! 🇵🇱✨', '49.33', '9.20', 4, 1, 'kabanosy-tarczynski-120g', '2024-01-04 00:00:00'),
(75, 'Ser gouda Mlekovita 250g', 'JED-00075', '## Ser gouda Mlekovita 250g\n\n**Odkryj autentyczny smak holenderskiego sera!** Ser gouda Mlekovita to tradycyjny, wysokiej jakości ser żółty, który zachwyci każdego miłośnika dobrego sera. Produkowany ze świeżego mleka krowiego, doskonale dojrzały i o bogatym, wyrazistym smaku, stanowi idealny wybór zarówno dla prawdziwych smakoszy, jak i dla całej rodziny. Ta 250-gramowa porcja to idealna wielkość do codziennego spożytkowania, gwarantująca świeżość i doskonały smak przez długi czas.\n\nSer gouda Mlekovita charakteryzuje się delikatną, kremową konsystencją oraz złotożółtym kolorem, który informuje o wysokiej jakości użytych surowców. Jego dojrzałość pozwala na doskonałe wykorzystanie zarówno w kuchni, jak i jako dodatek do stołu. Ser ten doskonale komponuje się z chlebem, wędlinami, owocami i winem, a także świetnie sprawdza się jako dodatek do potraw ciepłych, gdzie dodaje im bogatego smaku i aromatycznej głębi.\n\nCzy szukasz sera do kanapek? Czy planujesz imprezę i chcesz zachwycić gości? Ser gouda Mlekovita to zawsze strzał w dziesiątkę. Jego uniwersalność i doskonały stosunek jakości do ceny sprawiają, że staje się ulubionym wyborem polskich konsumentów. Mlekovita to marka zaufana od pokoleń, gwarantująca najwyższą świeżość i starannie wyselekcjonowane surowce.\n\n### Kluczowe cechy\n\n- 🧀 **Autentyczna gouda** – tradycyjny holenderski ser żółty o bogatym smaku\n- 📦 **Wygodny rozmiar** – 250g to idealna ilość dla rodziny\n- ✨ **Kremowa konsystencja** – miękka struktura, łatwa do cięcia i żucia\n- 🌾 **Ze świeżego mleka** – naturalne składniki bez zbędnych dodatków\n- 👨‍🍳 **Wszechstronny w użyciu** – idealny na kanapki, do piekarni, sałatek i potraw\n- ⭐ **Marka Mlekovita** – producent z bogatą tradycją i zaufaniem konsumentów\n- 🎯 **Doskonały stosunek ceny do jakości** – premium w przystępnej cenie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Nazwa produktu | Ser gouda Mlekovita |\n| Waga | 250g |\n| Typ sera | Żółty, dojrzały |\n| Producent | Mlekovita |\n| Cena | 19,45 PLN |\n| Przechowywanie | W chłodnej temperaturze 2-8°C |\n\n---\n\n**Nie czekaj, zamawiaj teraz!** Ser gouda Mlekovita 250g to gwarancja smaku, jakości i satysfakcji. Za zaledwie **19,45 PLN** otrzymujesz porcję autentyycznego, pysznego sera, który urozmaici Twoje codzienne posiłki. Dodaj do koszyka i ciesz się premium smakiem w domowym zaciszu! 🛒✨\n\n---\n\n*Dostawa do Ciebie w 24 godziny. Możliwość zwrotu w ciągu 30 dni. Kupujesz bezpiecznie!*', '19.45', '7.31', 4, 1, 'ser-gouda-mlekovita-250g', '2023-10-02 00:00:00'),
(76, 'Mleko Łaciate 3.2% 1L', 'JED-00076', '## Mleko Łaciate 3.2% 1L - Naturalna Świeżość w Każdym Kubku\n\n### Opis produktu\n\nMleko Łaciate 3.2% to doskonały wybór dla całej rodziny, które łączy tradycyjną jakość z nowoczesnym podejściem do pasteryzacji. Każda litrowa paczka zawiera pełnowartościowe mleko o optymalnym zawartości tłuszczu 3.2%, które idealnie sprawdza się zarówno do codziennego spożycia, jak i w kuchni. Naturalne źródło wapnia, białka i witamin D wspiera prawidłowy rozwój oraz utrzymanie zdrowia kostnego dla wszystkich członków rodziny – od najmłodszych do najstarszych.\n\nProdukt przechowuje się w praktycznym opakowaniu kartonowym, które zapewnia długą trwałość i wygodę przechowywania w lodówce. Mleko Łaciate pochodzi od krów karmionych naturalnym paszą, co gwarantuje jego świeży smak i bogatą zawartość cennych składników odżywczych. Dzięki procesowi pasteryzacji produkt zachowuje wszystkie ważne witaminy, a jednocześnie zapewnia bezpieczeństwo i długą trwałość.\n\nNiezależnie od tego, czy pijesz mleko do kawy, śniadania, czy używasz go do przygotowania wyśmienitych deserów, sosów czy piekanek – Mleko Łaciate 3.2% zawsze dostarczy Ci najwyższej jakości produktu. To wybór ludzi, którzy cenią sobie naturalne składniki i tradycyjny smak, bez zbędnych dodatków i konserwantów.\n\n### Kluczowe cechy\n\n- **Zawartość tłuszczu 3.2%** – Optymalny procent dla pełnego smaku i wartości odżywczych\n- **Naturalne źródło wapnia i białka** – Wspiera zdrowe kości i mięśnie dla całej rodziny\n- **Proces pasteryzacji** – Gwarantuje bezpieczeństwo i świeżość produktu\n- **Opakowanie 1L** – Praktyczny rozmiar idealna do codziennego użytku\n- **Brak sztucznych dodatków** – Tylko naturalne mleko bez konserwantów\n- **Długa trwałość** – Odporność na przechowywanie i transport dzięki kartonowemu opakowaniu\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Pojemność | 1L |\n| Zawartość tłuszczu | 3.2% |\n| Typ pasteryzacji | Wysoka temperatura (UHT) |\n| Opakowanie | Karton |\n| Temperatura przechowywania | 2-8°C |\n\n### Podsumowanie\n\nMleko Łaciate 3.2% w opakowaniu 1L to inwestycja w zdrowie Twojej rodziny po konkurencyjnej cenie **11.16 PLN**. Doskonała jakość, naturalny skład i wszechstronne zastosowanie w kuchni sprawiają, że produkt ten powinien znaleźć się w każdej lodówce. Nie czekaj – dodaj do koszyka już teraz i ciesz się smakiem autentycznego mleka, które kocha Polska! ✓\n\n---\n\n*Produkt objęty gwarancją świeżości. Sprawdzaj datę ważności przed zakupem!*', '11.16', '8.50', 4, 1, 'mleko-laciate-3-2-1l', '2024-05-09 00:00:00'),
(77, 'Chleb żytni krojony 500g', 'JED-00077', '## Chleb żytni krojony 500g\n\nCzarny chleb żytni to klasyk polskiego stołu, który łączy tradycję z najwyższą jakością. Nasz chleb żytni krojony to gwarantia świeżości i niepowtarzalnego smaku prosto z piekarni. Każdy bochenek pieczemy z naturalnych składników – mąki żytniej, wody, drożdży i soli. Dzięki tradycyjnym metodom wypieku otrzymujesz chleb o złotym, chrupiącym skorupie i wilgotnym, aromatycznym wnętrzu. Wstępne krojenie sprawiając że chleb jest gotowy do spożycia natychmiast po otwarciu opakowania.\n\nChleb żytni to idealny wybór dla osób dbających o zdrowe i zbilansowane odżywianie. Zawiera znaczną ilość błonnika pokarmowego, który wspiera pracę układu trawiącego, oraz bogate źródło witamin z grupy B. Żyto ma niższy indeks glikemiczny niż pszenica, co czyni ten chleb dobrym wyborem dla osób kontrolujących poziom cukru we krwi. Świetnie sprawdza się jako baza do piekarek, a jego głęboki, niepowtarzalny smak doskonale komponuje się z klasycznym masłem, serkami, wędlinami oraz wszelkimi dodatkami do kanapek.\n\nTen chleb to też rozwiązanie dla tych, którzy cenią sobie wygodę. Pakowanie w papier kraft sprawia, że producent zachowuje naturalność produktu, a kroj już wykonany – oszczędzasz czas na przygotowaniu posiłku. Chrupiąca skórka i delikatne, aromatyczne miąższu zmieniają zwyczajną kanapkę w prawdziwą ucztę dla zmysłów. Polecamy przechowywanie w temperaturze pokojowej, w miejscu osłoniętym przed wilgocią – chleb zachowa świeżość przez kilka dni.\n\n### Kluczowe cechy\n\n- **Naturalny skład** – bez dodatków konserwujących i sztucznych wzmacniaczy smaku\n- **Już pokrojony** – nie musisz tracić czasu na krojenie, chleb jest gotowy do spożycia\n- **Bogaty w błonnik** – wsparcie dla zdrowia przewodu pokarmowego i dobrej przemiany materii\n- **Tradycyjny smak żytni** – głębokie aromaty i charakterystyczny gust ceniony od pokoleń\n- **Doskonały do każdej kanapki** – uniwersalny dodatek do śniadania, drugie śniadania i kolacji\n- **Dietetycznie wartościowy** – niski indeks glikemiczny, wiele witamin i minerałów\n- **Opakowanie ekologiczne** – papier kraft przyjazny środowisku\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Waga netto | 500 g |\n| Rodzaj | Chleb żytni 100% |\n| Forma | Krojony |\n| Cena | 5.76 PLN |\n| Przechowywanie | Temperatura pokojowa, w suchym miejscu |\n\n---\n\nJeśli szukasz smacznego, zdrowego i tradycyjnego chleba, który będzie Twoim sprzymierzeńcem każdego dnia – Chleb żytni krojony 500g to idealny wybór. Za przystępną cenę **5.76 PLN** dostajesz produkt wysokiej jakości, który wspiera zdrowy styl życia całej rodziny. Dodaj do koszyka teraz i odkryj prawdziwą smak chleba żytniego! 🥖', '5.76', '5.49', 4, 1, 'chleb-zytni-krojony-500g', '2023-08-04 00:00:00'),
(78, 'Woda Żywiec Zdrój 1.5L 6-pak', 'JED-00078', '## Woda Żywiec Zdrój 1.5L 6-pak\n\nOdkryj czystość i świeżość wody Żywiec Zdrój – naturalnie mineralizowanej wody źródlanej, która pochodzi z czystych źródeł Pienin. Każda butelka zawiera wodę wzbogaconą o naturalne składniki mineralne, które wspierają zdrowy styl życia Twojej rodziny. Woda Żywiec Zdrój to gwarancja najwyższej jakości oraz doskonały wybór dla osób dbających o swoje zdrowie i dobre samopoczucie.\n\n6-pak butelek o pojemności 1.5L to idealne rozwiązanie dla całej rodziny lub do biura. Dzięki dużym opakowaniom zawsze będziesz mieć pod ręką czystą, orzeźwiającą wodę, gotową do picia. Naturalna mineralizacja wody poprawia jej smak i działanie na organizm, a doskonale tolerowana przez wszystkie osoby, niezależnie od wieku. Woda Żywiec Zdrój sprawdza się zarówno do codziennego picia, jak i przy przygotowaniu posiłków czy napojów.\n\nWybierając wodę Żywiec Zdrój, stawiasz na produkt z bogatą tradycją i zaufaniem konsumentów przez wiele lat. Każda butelka to symbol jakości, naturalności i dbałości o Twoje zdrowie. Woda ta doskonale gasi pragnienie, wspiera nawodnienie organizmu i pozytywnie wpływa na cały system organizmu.\n\n### Kluczowe cechy\n\n- 🌿 **Naturalna mineralizacja** – woda ze źródeł w Pienin z naturalnie występującymi mineralami\n- 💧 **Pojemność 1.5L** – duża butelka idealna do użytku domowego i biurowego\n- 📦 **6-pak** – osiem butelek w jednym opakowaniu, najlepszy stosunek ceny do ilości\n- ✅ **Bezpieczeństwo** – woda źródlana poddawana rygorystycznej kontroli jakości\n- 🏥 **Dla całej rodziny** – naturalna composycja minerałów bezpieczna dla dzieci i dorosłych\n- 🌍 **Ekologiczny wybór** – butelki wykonane z recyklingu i łatwe do ponownego wykorzystania\n- 🥤 **Świeży, naturalny smak** – brak dodatków sztucznych i konserwantów\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Pojemność jednej butelki | 1.5L |\n| Liczba butelek w opakowaniu | 6 szt. |\n| Typ wody | Woda mineralna źródlana |\n| Pochodzenie | Źródła Pienin, Polska |\n| Cena za pakiet | 73,62 PLN |\n\n---\n\n**Nie czekaj dłużej!** Woda Żywiec Zdrój 6-pak to inwestycja w zdrowie Twojej rodziny. Za jedynie **73,62 PLN** otrzymujesz 9 litrów naturalnej, czystej wody minerałnej, która wspiera Twoje codzienne nawodnienie i dobre samopoczucie. Dodaj do koszyka teraz i ciesz się świeżością oraz naturalnością z każdą butelką! ✨\n\n*Dostępne w sklepie z szybką dostawą. Zamów dziś – otrzymaj jutro!*', '73.62', '1.27', 4, 1, 'woda-zywiec-zdroj-1-5l-6-pak', '2024-04-20 00:00:00'),
(79, 'Sok Tymbark jabłkowy 1L', 'JED-00079', '## Sok Tymbark Jabłkowy 1L – Naturalny Smak Jabłek w Każnym Łyku\n\nOdkryj czysty, niezapomniany smak naturalnych jabłek z sokiem Tymbark Jabłkowym! Polskie soki Tymbark od pokoleń cieszą się zaufaniem konsumentów dzięki doskonałej jakości i autentycznemu smakowi. Ten uniwersalny sok jabłkowy to idealna propozycja dla całej rodziny – zarówno dla dzieci, jak i dla dorosłych, którzy cenią sobie zdrowe i naturalne produkty.\n\nSok Tymbark jabłkowy to kwintesencja klasycznego polskiego soku. Wykonany z wybranych odmian jabłek, zachowuje bogatą gamę naturalnych smaków i aromatów. Każdy łyk to przywołanie chwili spędzanej na polskich sadach, pełne świeżości i energii. Niezawodny wybór na śniadanie, do szkoły, pracy, lub jako dodatek do ulubionych dań i napojów. Sok jest całkowicie naturalny, bez sztucznych barwników, konserwantów i aromaty – tylko to, co najlepsze z jabłek.\n\nDuża, praktyczna butelka 1L to idealne rozwiązanie dla aktywnych rodzin. Wygodny format umożliwia łatwe przechowywanie w lodówce i szybkie nalanie do szklanki. Sok Tymbark jabłkowy to gwarancja konsekwentnej jakości i smaku, którą otrzymujesz z każdym opakowaniem. Niezależnie od pory roku, sok jabłkowy Tymbark zawsze będzie wspaniałym źródłem naturalnych witamin i energii.\n\n### Kluczowe cechy\n\n- **100% naturalny sok** – bez sztucznych dodatków, barwników i konserwantów\n- **Polska tradycja i jakość** – produkt od zaufanej marki Tymbark, cieszący się uznaniem od dziesięcioleci\n- **Praktyczne opakowanie 1L** – idealne dla całej rodziny, łatwe do przechowywania w lodówce\n- **Bogaty smak** – autentyczny aromat i smak naturalnych jabłek, każdy łyk to czysta przyjemność\n- **Pełna wartości odżywczych** – naturalne witaminy z jabłek, brak dodanego cukru (zawiera naturalne cukry z owoców)\n- **Uniwersalne zastosowanie** – idealny na śniadanie, podwieczorek, do szkoły i pracy\n- **Doskonały wybór dla całej rodziny** – bezpieczny i zdrowy dla dzieci, pyszny dla dorosłych\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Pojemność** | 1000 ml (1 L) |\n| **Typ produktu** | Sok owocowy naturalny |\n| **Skład główny** | 100% sok z jabłek |\n| **Producent** | Tymbark |\n| **Cena** | 71,09 PLN |\n\n---\n\n**Nie czekaj – zamów Sok Tymbark Jabłkowy 1L już dziś!** Ciesz się autentycznym, naturalnym smakiem polskich jabłek w każdej chwili. Tego soku nie może zabraknąć w Twojej lodówce. Wysyłka błyskawiczna, gwarancja świeżości i najwyższa jakość – to wszystko czeka na Ciebie. Dodaj do koszyka teraz i daj sobie odrobinę naturalnej słodyczy oraz zdrowia!', '71.09', '2.09', 4, 1, 'sok-tymbark-jablkowy-1l', '2024-01-12 00:00:00'),
(80, 'Chipsy Lays Zielona Cebulka 225g', 'JED-00080', '## Chipsy Lay\'s Zielona Cebulka 225g\n\nOdkryj niezapomniane połączenie smaku z przysmakami Lay\'s Zielona Cebulka! Te lekkie, chrupiące chipsy o wyjątkowej teksturze to idealna przekąska dla całej rodziny. Każde ukąszenie przynosi intensywny, świeży smak zielonej cebuli wzbogacony subtelną nutą przypraw, która sprawia, że nie potrafisz przestać sięgać po kolejną garść. Produkty Lay\'s to gwarancja najwyższej jakości i konsystencji, którą cenią sobie miłośnicy chipsów na całym świecie.\n\nChipsy Lay\'s Zielona Cebulka to idealna propozycja zarówno na domową przekąskę podczas oglądania telewizji, jak i na imprezę czy spotkanie ze znajomymi. Niepowtarzalny smak zielonej cebuli doskonale komponuje się z piwem, gazowanymi napojami oraz sokami. Produkt wykonany jest z naturalnych ziemniaków, a dzięki opakowaniu o pojemności 225g zawsze będziesz mieć pod ręką porcję takiej wielkości, że wystarczy na kilka osób lub kilka lekkicha snackowania w trakcie dnia.\n\nStanowiące tradycję światową chipsy Lay\'s znane są z najlepszych składników i doskonałych proporcji przypraw. Zielona cebulka to jeden z najbardziej cenionych smaków, zarówno wśród dorosłych, jak i starszych nastolatków. Produkty tej marki znajdują się w domach milionów osób na całym świecie, a ich specjalny proces produkcji gwarantuje każdorazowo taką samą jakość i smak.\n\n### Kluczowe cechy\n\n- **Autentyczny smak zielonej cebuli** – intensywny, świeży i charakterystyczny posmak, który natychmiast rozpoznasz\n- **Naturalne składniki** – chipsy produkowane z wysokiej jakości ziemniaków bez sztucznych barwników\n- **Idealna wielkość opakowania** – 225g to doskonały rozmiar na domową przekąskę lub mały imprezę\n- **Chrupiąca tekstura** – każdy chip ma idealnie złotawą kolor i zadowalającą konsystencję\n- **Wygodny format** – opakowanie łatwe do otwarcia i wielokrotnego zamknięcia\n- **Wszechstronne zastosowanie** – świetne solo, do dipów, salsów lub jako dodatek do posiłków\n- **Marka światowa** – Lay\'s to gwarancja konsekwencji jakości i smaku od dziesięcioleci\n\n### Specyfikacja\n\n| Atrybut | Wartość |\n|---------|---------|\n| **Nazwa produktu** | Chipsy Lay\'s Zielona Cebulka |\n| **Pojemność opakowania** | 225g |\n| **Cena** | 20.16 PLN |\n| **Typ produktu** | Przekąski chrupkie |\n| **Smak** | Zielona cebulka |\n\n---\n\n**Nie czekaj – zamów chipsy Lay\'s Zielona Cebulka już dziś!** Za jedyne 20.16 PLN otrzymasz 225 gramów czyrej przyjemności smakowej, która zadowoli nawet najprzybytszych smaków. Lay\'s to marka, której ufają miliony konsumentów. Dodaj do koszyka teraz i ciesz się dostawą do Twojego domu. Świetna cena, najlepszy smak – to propozycja, którą musisz spróbować!', '20.16', '9.35', 4, 0, 'chipsy-lays-zielona-cebulka-225g', '2023-11-07 00:00:00'),
(81, 'Smartfon Samsung Galaxy S24', 'ELE-00081', '## Smartfon Samsung Galaxy S24 – Najnowsza Generacja Mobilnej Technologii\n\nPoznaj przyszłość smartfonów z **Samsung Galaxy S24** – urządzeniem, które łączy elegancki design z zaawansowaną technologią. Ten flagowy model to doskonały wybór dla każdego, kto szuka smartfona nowej generacji z najnowszymi rozwiązaniami AI i kamerą klasy premium. Galaxy S24 to nie tylko telefon – to Twój osobisty asystent, aparat fotograficzny i centrum rozrywki w jednym eleganckim urządzeniu.\n\nSmartfon Samsung Galaxy S24 wyposażony jest w najnowszy procesor Snapdragon 8 Gen 3 Leading Version, który zapewnia błyskawiczną pracę i bezniezierną wydajność w każdej sytuacji. Niezależnie od tego, czy grasz w wymagające gry, edytujesz zdjęcia czy pracujesz z wieloma aplikacjami jednocześnie – Galaxy S24 bez problemu sobie poradzi. Ekran Dynamic AMOLED 2X o rozdzielczości 120 Hz gwarantuje niesamowicie gładkie przewijanie i żywe kolory, które zachwycą każdego użytkownika.\n\nFotografia na nowym poziomie – dzięki głównemu aparatowi 50 MP z zaawansowaną technologią Night Mode i sztuczną inteligencją, każde zdjęcie będzie wspaniałe. Niezależnie od warunków oświetlenia, porze dnia czy nocy, otrzymasz ostre, nasycone kolorami fotografie. Tylny aparat ultraszerokokątny i teleobiektyw dają Ci nieograniczone możliwości twórcze. Przedni aparat 12 MP wspiera bezpieczne odblokowywanie twarzy i nagrywanie pięknych selfie w każdych warunkach.\n\n### Kluczowe cechy\n\n✨ **Procesor Snapdragon 8 Gen 3 Leading Version** – najnowsza, najszybsza generacja dla maksymalnej wydajności\n📱 **Ekran Dynamic AMOLED 2X, 120 Hz** – płynna, kolorowa ekspozycja z zaawansowanym odświeżaniem\n🎥 **System kamer AI** – aparat 50 MP z Night Mode i zaawansowaną technologią portretową\n🔋 **Bateria 4000 mAh** – cały dzień intensywnego użytkowania na jednym ładowaniu\n🛡️ **Wzmocniony design IP68** – odporność na wodę i kurz do głębokości 1,5 m\n🔐 **Samsung Knox** – najwyższa klasa bezpieczeństwa danych i prywatności\n⚡ **Szybkie ładowanie 25W** – pełny baterię ładujesz w zaledwie 60 minut\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Procesor** | Snapdragon 8 Gen 3 Leading Version |\n| **Pamięć RAM** | 8 GB |\n| **Pamięć wbudowana** | 256 GB |\n| **Wyświetlacz** | AMOLED 6,1\", 120 Hz, FHD+ |\n| **Aparat główny** | 50 MP f/1.8 z OIS |\n\n---\n\n**Nie czekaj – to jest dokładnie ten smartfon, którego szukałeś!** Oferujemy Ci najnowszą technologię Samsung Galaxy S24 w niezawodnej cenie **1560,80 PLN**. Niezależnie od tego, czy jesteś profesjonalistą, gamer\'em czy kochaniskiem fotografii, Galaxy S24 spełni wszystkie Twoje oczekiwania. Zamawiaj teraz i ciesz się szybką dostawą oraz gwarancją producenta. Odczuj moc nowoczesnego smartfona – Samsung Galaxy S24 czeka na Ciebie! 🚀\n\n---\n\n**Cena: 1560,80 PLN**', '1560.80', '2.29', 5, 1, 'smartfon-samsung-galaxy-s24', '2024-01-08 00:00:00'),
(82, 'iPhone 15 Pro 256GB', 'ELE-00082', '## iPhone 15 Pro 256GB\n\n**Odkryj moc profesjonalnej technologii w swojej kieszeni!**\n\niPhone 15 Pro to flagowa seria Apple, która łączy najnowocześniejsze technologie z eleganckim designem. Model z pamięcią 256GB to idealny wybór dla tych, którzy nie chcą oszczędzać na jakości i wydajności. To urządzenie dla zaawansowanych użytkowników, twórców treści oraz wszystkich, którzy cenią sobie niezawodność i wydajność. Z procesorem A17 Pro i zaawansowanym systemem kamer, iPhone 15 Pro stawia nowe standardy w branży smartfonów.\n\nNiezależnie od tego, czy pracujesz nad projektami kreatywnym, grasz w wymagające gry, czy po prostu chcesz mieć urządzenie najwyższej jakości — iPhone 15 Pro się sprawdzi. Wyświetlacz Super Retina XDR zapewnia oszałamiającą ostrość i kolory, a bateria o zwiększonej pojemności gwarantuje pracę przez cały dzień. Wytrzymała konstrukcja ze stali chirurgicznej i ochroną Ceramic Shield oznacza, że Twoje inwestycji będzie bezpieczna przez lata użytkowania.\n\n256GB pamięci to idealna ilość miejsca do przechowywania aplikacji, wysokiej rozdzielczości zdjęć i filmów w najwyższej jakości. Bez ciągłego czyszczenia pamięci, bez rezygnacji z ulubionych zdjęć — po prostu masz miejsce na wszystko, czego potrzebujesz. To doskonały środek złoty między pojemnością a ceną.\n\n### Kluczowe cechy\n\n- **Procesor A17 Pro** – najnowsza generacja chipów Apple, zapewniająca błyskawiczną wydajność i niskie zużycie energii\n- **Tryb Action** – nowy sposób nagrywania stabilnych, profesjonalnych filmów dzięki innowacyjnym algorytmom stabilizacji\n- **System kamer Pro** – trzy aparaty 48MP z zaawansowanym zoomem optycznym 5x i noktowizją\n- **Wyświetlacz Super Retina XDR** – 6,1\" ekran OLED z adaptacyjnym odświeżaniem do 120Hz i najwyższą jasnością na rynku\n- **Bateria całodzienna** – do 29 godzin pracy na jednym ładowaniu w porównaniu z iPhone\'em 14 Pro\n- **Titan – nowy metal** – wytrzymalsza konstrukcja ze stali chirurgicznej, odporna na upadki i uszkodzenia\n- **USB-C z Thunderbolt** – błyskawiczny transfer danych i szybkie ładowanie\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Pojemność pamięci | 256GB |\n| Procesor | Apple A17 Pro |\n| Wyświetlacz | 6,1\" Super Retina XDR OLED 120Hz |\n| Aparat główny | 48MP (f/1.78) |\n| Bateria | 3349 mAh |\n| Ładowanie | USB-C, MagSafe |\n| Odporność | IP68 (8m, 30 minut) |\n\n---\n\n**Nie czekaj dłużej!** iPhone 15 Pro 256GB za 5387,96 PLN to inwestycja w urządzenie, które będzie Cię towarzyszyć przez kolejne lata. Szybka wysyłka, pełna gwarancja i wsparcie serwisowe firmy Apple czekają na Ciebie. Zamów teraz i doświadcz różnicy, jaką może wnieść w Twoje życie prawdziwie flagowy smartfon. **Dodaj do koszyka i ciesz się technologią na najwyższym poziomie!**', '5387.96', '8.51', 5, 1, 'iphone-15-pro-256gb', '2023-09-16 00:00:00'),
(83, 'Laptop Lenovo ThinkPad E16', 'ELE-00083', '## Laptop Lenovo ThinkPad E16 – Profesjonalny Towarzysz do Pracy i Nauki\n\nOdkryj nowy wymiar produktywności z laptopem **Lenovo ThinkPad E16**, który łączy nowoczesny design z niezawodną wydajnością. Ten elegancki ultrabook z 16-calowym ekranem to idealny wybór dla profesjonalistów, freelancerów, studentów i wszystkich tych, którzy poszukują urządzenia do ambitnych projektów. ThinkPad E16 wyróżnia się solidną konstrukcją, ergonomiczną klawiaturą QWERTY oraz imponującą baterią zapewniającą pracę przez cały dzień. Niezależnie od tego, czy pracujesz w biurze, kawiarni czy podróżujesz – ten laptop będzie Twoim wiernym partnerem.\n\nWydajność i nowoczesna technologia to dwa filary, na których opiera się ThinkPad E16. Dzięki procesowi najnowszej generacji oraz 16 GB pamięci RAM bez problemu obsłużysz multitasking, edycję zdjęć, pracę w zaawansowanych aplikacjach biurowych i wiele więcej. Jasny ekran o wysokiej rozdzielczości zapewnia komfort pracy przez wiele godzin, a zaawansowany system chłodzenia gwarantuje, że laptop pozostanie cichy i chłodny nawet przy intensywnym obciążeniu. Ponadto, zintegrowana kamera HD i mikrofon z redukcją szumów to idealne narzędzie do wideokonferencji i pracy zdalnej.\n\nBezpieczeństwo danych to priorytet producenta – ThinkPad E16 wyposażony jest w zaawansowane szyfrowanie, czytnik linii papilarnych oraz kamerę z przysłoną prywatności. Standardowa gwarancja i dostęp do profesjonalnego wsparcia technicznego Lenovo dają pewność, że inwestujesz w urządzenie wysokiej jakości. To laptop, który sprawdzi się zarówno w korporacyjnym środowisku, jak i w home office\'cie – wszędzie tam, gdzie liczą się niezawodność i wydajność.\n\n### Kluczowe cechy\n\n- 🖥️ **Ekran 16 cali Full HD** – wyraźny obraz z szerokimi kątami widzenia, idealny do pracy i multimediów\n- ⚡ **Procesora najnowszej generacji** – płynna praca w wymagających aplikacjach i przeglądaniu wielu kart\n- 💾 **16 GB pamięci RAM** – bezproblemowy multitasking i szybkie przełączanie między programami\n- 🔋 **Bateria o dużej pojemności** – do 10 godzin pracy bez ładowania\n- ⌨️ **Ergonomiczna klawiatura ThinkPad** – wygodna praca, niezawodne naciśnięcia klawiszy\n- 🔐 **Zaawansowane bezpieczeństwo** – szyfrowanie, czytnik linii papilarnych, kamera z przysłoną\n- 🎧 **Dźwięk stereo wysokiej jakości** – immersyjne doznania audio\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| **Ekran** | 16 cali, Full HD (1920 x 1200) |\n| **Procesor** | Intel Core (najnowsza generacja) |\n| **Pamięć RAM** | 16 GB DDR4 |\n| **Dysk SSD** | 512 GB |\n| **Waga** | ok. 1,9 kg |\n| **System operacyjny** | Windows 11 Pro |\n| **Porte** | USB-C, USB 3.0, HDMI, gniazdo słuchawkowe |\n\n---\n\n**Zadbaj o swoją produktywność i komfort pracy – Laptop Lenovo ThinkPad E16 to inwestycja, która się zwróci każdego dnia.** W cenie **6 768,60 PLN** otrzymujesz urządzenie премиум-klasy, które nie zawiedzie nawet w najbardziej wymagających sytuacjach. Nie czekaj – dodaj do koszyka teraz i dołącz do tysięcy zadowolonych użytkowników ThinkPada na całym świecie! 🚀', '6768.60', '0.25', 5, 1, 'laptop-lenovo-thinkpad-e16', '2023-07-07 00:00:00'),
(84, 'Tablet Apple iPad 10 gen', 'ELE-00084', '## Tablet Apple iPad 10 gen – Nowoczesna technologia w Twoich rękach\n\nPrzedstawiamy Ci urządzenie, które zmieni sposób, w jaki pracujesz, uczysz się i rozrywasz się. **Apple iPad 10 generacji** to idealne połączenie mocy, eleganckiego designu i niezawodności, którą cenią użytkownicy na całym świecie. Dzięki zaawansowanym technologiom Apple i intuicyjnemu systemowi iPadOS, ten tablet staje się niezbędnym narzędziem do codziennych zadań, twórczej pracy i rozrywki. Niezależnie od tego, czy jesteś studentem, profesjonalistą czy entuzjastą cyfrowych gadżetów – iPad 10 gen czeka na Ciebie.\n\nEkran Liquid Retina o przekątnej 10,9 cala zapewnia oszałamiającą jakość obrazu z żywymi kolorami i ostrością detali. Procesor Apple A14 Bionic daje moc obliczeniową porównywalna z komputerami stacjonarnymi, radząc sobie bez problemu z aplikacjami multimedialnymi, edycją wideo czy zaawansowanymi grami. Bateria o pojemności 7587 mAh pozwala pracować przez cały dzień bez konieczności ładowania, a szybkie ładowanie sprawia, że już w 2-3 godziny jesteś gotowy do działania.\n\nTo urządzenie to inwestycja w produktywność i przyjemność użytkowania. Kompatybilność z akcesoriami Apple, obsługa Apple Pencil oraz bezproblemowa integracja z ekosystemem iPhone\'ów i Maców sprawiają, że iPad 10 gen jest doskonałym wzbogaceniem Twojej kolekcji urządzeń. Ładny design w kilku wariantach kolorystycznych, odporność na zarysowania i wodę (certyfikacja IP6) gwarantują wytrzymałość i elegancję przez lata użytkowania.\n\n### Kluczowe cechy\n\n- **Ekran Liquid Retina 10,9\"** z rozdzielczością 2360 x 1640 pikseli i częstotliwością odświeżania 60 Hz\n- **Procesor Apple A14 Bionic** zapewniający błyskawiczną wydajność i płynne działanie aplikacji\n- **System iPadOS** intuicyjny i łatwy w obsłudze, z dostępem do ponad 2 milionów aplikacji\n- **Aparat tylny 12 MP** z szerokim kątem widzenia i aparat przedni 12 MP do wideokonferencji\n- **Bateria 7587 mAh** umożliwiająca pracę do 10 godzin na jednym ładowaniu\n- **Obsługa Apple Pencil** (1. pokolenia) – idealne do notatek i rysowania\n- **Łączność Wi-Fi 6E i opcja LTE** – szybki internet wszędzie, gdzie potrzebujesz\n\n### Specyfikacja\n\n| Parametr | Wartość |\n|----------|---------|\n| Ekran | 10,9\" Liquid Retina, 2360 x 1640 px |\n| Procesor | Apple A14 Bionic |\n| RAM | 4 GB |\n| Pamięć wewnętrzna | 64 GB / 256 GB do wyboru |\n| Bateria | 7587 mAh |\n| Aparat tylny | 12 MP, f/1.8 |\n| System operacyjny | iPadOS 16 i wyższe |\n\n---\n\n**Nie czekaj więcej!** Tablet Apple iPad 10 gen w cenie **7 994,78 PLN** to okazja, aby wejść do świata urządzeń Apple z najwyższą jakością i niezawodnością. Niezależnie od Twoich potrzeb – czy to praca, nauka czy rozrywka – iPad 10 gen doskonale się sprawdzi. Dodaj go do koszyka teraz i ciesz się dostawą na terenie całej Polski, solidną gwarancją oraz doskonałą obsługą klienta. **Twoja nowa produktywność czeka!**', '7994.78', '11.77', 5, 1, 'tablet-apple-ipad-10-gen', '2024-05-21 00:00:00');
