INSERT INTO `product_ratings` (`id`, `product_id`, `user_id`, `rating`, `comment`, `created_at`) VALUES
(1, 167, 23, 4, 'Bardzo fajny produkt, warte swojej ceny! Trochę czekałem na przesyłkę, ale jakość i wykonanie przeszły moje oczekiwania - na pewno będę zamawiać ponownie.', '2024-09-29 21:13:14'),
(2, 6, 23, 1, 'Produkt całkowicie nie spełnia oczekiwań - materiał słabej jakości, szybko się zniszczył już po tygodniu użytkowania. Zamiast 5 gwiazdek dostałem rozczarowanie i żałuję, że wydałem na to pieniądze.', '2024-09-06 21:13:14'),
(3, 76, 23, 1, 'Produkt to kompletne rozczarowanie - materiał gorszej jakości niż na zdjęciach, a do tego przyszedł uszkodzony. Za takie pieniądze można było kupić coś znacznie lepszego.', '2024-09-15 21:13:14'),
(4, 156, 5, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach, szybka dostawa i świetne opakowanie. Polecam każdemu, jestem bardzo zadowolony z zakupu!', '2024-09-04 18:03:21'),
(5, 10, 5, 4, 'Świetny produkt, naprawdę polecam! Jakość dobra, szybka dostawa, jedynie opakowanie mogło być lepsze, ale ogólnie bardzo zadowolony z zakupu.', '2024-09-05 18:04:11'),
(6, 6, 5, 3, 'Produkt dotarł szybko i jest solidnie wykonany, jednak cena wydaje się dość wysoka w stosunku do jakości. Spełnia swoje funkcje, ale nie oferuje nic wyjątkowego za takie pieniądze.', '2024-09-17 18:04:11'),
(7, 121, 37, 5, 'Najlepsza decyzja zakupowa jaką zrobiłem w tym sezonie! Produkt przyszedł szybko, świetnej jakości, dokładnie taki jaki był na zdjęciu - gorąco polecam wszystkim. ⭐⭐⭐⭐⭐', '2024-09-14 14:32:35'),
(8, 89, 67, 5, 'Świetny produkt, dokładnie taki, jaki byłem szukał! Polecam każdemu - najwyższa jakość, szybka dostawa i obsługa klienta na najwyższym poziomie. ⭐⭐⭐⭐⭐', '2024-09-06 15:28:20'),
(9, 186, 67, 4, 'Bardzo zadowolona z zakupu, produkt przyszedł w idealnym stanie i spełnia wszystkie moje oczekiwania. Jedyna drobna niedogodność to trochę dłuższa dostawa, ale za to jakość całkowicie ją rekompensuje, polecam!', '2024-09-08 15:28:20'),
(10, 131, 19, 2, 'Produkt nie spełnił moich oczekiwań - materiał okazał się tandetny, a jakość wykonania słaba jak na podaną cenę. Po tygodniu użytkowania zaczął się rozpadać, nie polecam nikomu.', '2024-09-16 14:04:28'),
(11, 62, 19, 3, 'Produkt jest w porządku, ale nie spełnił moich oczekiwań - jakość materiału mogła być lepsza, a cena wydaje się trochę wysoka. Dla podstawowych zastosowań się nada, ale za te pieniądze spodziewałem się czegoś więcej.', '2024-09-10 14:04:28'),
(12, 112, 62, 4, 'Produkt przyszedł szybko i dobrze zapakowany, całkowicie zadowolony z jakości. Jedynym minusem jest, że wymiary są trochę mniejsze niż się spodziewałem, ale mimo to warto każdej złotówki!', '2024-09-15 09:06:03'),
(13, 68, 12, 4, 'Produkt przyszedł szybko i jest dokładnie taki, jak na zdjęciach - solidna jakość i dopracowane detale, choć cena mogłaby być trochę niższa. Zdecydowanie polecam, jestem zadowolony z zakupu i już myślę o tym, aby zamówić coś więcej z tej marki!', '2024-09-16 16:02:37'),
(14, 96, 12, 3, 'Produkt dotarł w dobrym stanie, ale jego jakość jest średnia - nie spełnia w pełni moich oczekiwań. Za taką cenę mogłem spodziewać się czegoś lepszego, chociaż funkcjonuje jak powinien.', '2024-09-20 16:02:37'),
(15, 192, 22, 2, 'Produkt zupełnie nie odpowiada opisowi na stronie - materiał kiepskiej jakości, a do tego przyszedł uszkodzony. Za takie pieniądze spodziewałem się czegoś znacznie lepszego, nie polecam.', '2024-09-21 14:26:51'),
(16, 11, 21, 4, 'Produkt jest naprawdę solidny i dokładnie taki, jak pokazywał producent - dobrze wykonany i funkcjonalny. Dostawy przebiegła szybko, jedynym minusem była słaba instrukcja obsługi, ale mimo tego polecam!', '2024-10-02 11:44:47'),
(17, 155, 51, 3, 'Produkt jest solidny i spełnia swoje funkcje, choć za taką cenę spodziewałem się czegoś więcej. Nie jest to zły zakup, ale raczej przeciętny - polecam, jeśli nie masz wyższych oczekiwań.', '2024-09-17 19:39:11'),
(18, 59, 8, 4, 'Świetny produkt, dokładnie taki jaki oczekiwałem! Szybka dostawa, dobra jakość wykonania, jedynie opakowanie mogło być odrobinę lepsze, ale na pewno polecę ten sklep znajomym.', '2024-10-01 16:56:59'),
(19, 181, 19, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem - świetna jakość, szybka dostawa i doskonała cena! Gorąco polecam, kupuję tu regularnie i zawsze jestem zadowolony z zakupów. ⭐⭐⭐⭐⭐', '2024-09-10 18:29:40'),
(20, 133, 19, 5, 'Produkt doskonały, przesyłka szybka i starannie zapakowana! Gorąco polecam, na pewno będę kupować znowu 👍', '2024-09-20 18:29:40'),
(21, 154, 59, 3, 'Produkt przyszedł w dobrym stanie i zgodny z opisem, choć kolor okazał się trochę inny niż na zdjęciu. Za tę cenę spodziewałem się lepszej jakości materiału, ale na ogół jest zadowalający i powinien wystarczyć.', '2024-09-30 13:13:59'),
(22, 26, 81, 4, 'Produkt przyszedł szybko i dobrze zapakowany, dokładnie taki jaki był na zdjęciu. Naprawdę polecam, jedynym minusem jest trochę wyższa cena, ale jakość warte tego warta.', '2024-10-07 16:14:35'),
(23, 184, 27, 3, 'Produkt jest w porządku, spełnia swoje funkcje, ale cena mogłaby być niższa w stosunku do jakości. Nie zachwycił mnie, ale i nie mam powodów do narzekań.', '2024-10-05 15:10:42'),
(24, 107, 27, 5, 'Fantastyczny produkt, dokładnie taki, jaki się spodziewałem - świetna jakość, szybka dostawa i piękne opakowanie, wrzucę sobie jeszcze jedno zamówienie! Polecam serdecznie, 100% warte pieniędzy, jestem naprawdę zadowolony z zakupu.', '2024-10-04 15:10:42'),
(25, 13, 43, 5, 'Wspaniały produkt, dokładnie taki jaki sobie wyobrażałem, dobra jakość za rozsądną cenę i szybka dostawa! Polecam, więcej takich okazji! ⭐⭐⭐⭐⭐', '2024-09-22 13:49:51'),
(26, 63, 43, 5, 'Produkt całkowicie mnie zaskoczył – najwyższa jakość, szybka dostawa i dokładnie taki, jaki był opisany. Gorąco polecam, warto każdą złotówkę!', '2024-10-06 13:49:51'),
(27, 105, 49, 5, 'Świetny produkt, dokładnie taki jak opisany w ogłoszeniu! Polecam każdemu, szybka dostawa i naprawdę warto.', '2024-09-16 13:59:07'),
(28, 26, 83, 5, 'Produkt превосходный, dokładnie taki jaki się spodziewałem - solidny, dobrze zapakowany i szybka dostawa. Gorąco polecam każdemu, warto każdej złotówki! ⭐⭐⭐⭐⭐', '2024-09-24 09:18:01'),
(29, 58, 77, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu - dobra jakość i szybka dostawa. Jedynym minusem jest trochę wyższa cena, ale zdecydowanie warto, polecam!', '2024-10-01 14:42:45'),
(30, 74, 77, 5, 'Świetny produkt, przyszedł szybko i dokładnie taki, jaki oczekiwałem! Bardzo polecam, warte każde złote.', '2024-10-02 14:42:45'),
(31, 61, 78, 5, 'Świetny produkt, dokładnie taki jaki sobie wyobrażałem - doskonała jakość, szybka dostawa i jeszcze taniej niż u konkurencji! Gorąco polecam, na pewno będę zamawiać tutaj ponownie.', '2024-10-15 08:01:37'),
(32, 191, 16, 2, 'Produkt totalnie nie spełnił moich oczekiwań - materiał niedobrej jakości, a po kilku dniach użytkowania zaczął się rozpadać. Za tę cenę można dostać coś znacznie lepszego, nie polecam, bardzo rozczarowany/rozczarowana zakupem.', '2024-10-05 11:26:16'),
(33, 82, 57, 5, 'Świetny produkt, dokładnie taki jaki był opisany na stronie! Polecam wszystkim, szybka dostawa i bez żadnych problemów.', '2024-09-21 16:41:03'),
(34, 131, 37, 2, 'Ocena: 2/5\n\nProdukt do kompletu rozczarowujący - szybko się zepsuł i w ogóle nie spełnia obietnic z opisu, do tego obsługa klienta bezużyteczna. Nie polecam nikomu i życzę wszystkim aby nie wpadli na tę samą pułapkę co ja.', '2024-10-19 18:07:25'),
(35, 63, 84, 1, 'Okropna jakość za taką cenę, produkt rozpadł się po tygodniu używania. Nigdy więcej nie kupuję od tego sprzedawcy, do tego wysyłka wieczność!', '2024-10-02 14:35:30'),
(36, 13, 84, 3, 'Produkt jest w porządku, spełnia swoje funkcje, ale nic mnie szczególnie nie zachwycił. Cena wydaje się trochę wysoka w stosunku do tego, co oferuje.', '2024-10-17 14:35:30'),
(37, 27, 46, 3, 'Produkt przyszedł w dobrym stanie, ale jakość nie do końca spełniła moje oczekiwania w stosunku do ceny. Nie mogę narzekać na dostawę, jednak nie wiem czy ponownie bym go kupił.', '2024-10-19 19:00:05'),
(38, 173, 61, 5, 'Świetny produkt, przesyłka przyszła szybko i dobrze zapakowana. Zdecydowanie polecam, warto każdego grosza!', '2024-10-06 20:04:25'),
(39, 98, 62, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach, a do tego szybka dostawa! Zdecydowanie polecam, warto każdej złotówki.', '2024-10-15 18:12:47'),
(40, 191, 50, 4, 'Produkt przyszedł szybko i bardzo mi się podoba - jakość jest naprawdę dobra za tę cenę. Jedyne, czego mi brakuje, to może nieco lepsze opakowanie, ale polecam!', '2024-09-30 13:20:13'),
(41, 198, 59, 4, 'Świetny produkt, dokładnie taki jak opisany na stronie i szybka dostawa do tego. Jedyna mała wada to trochę słabsze opakowanie, ale sam towar jest solidny i polecam - naprawdę warte pieniędzy!', '2024-09-30 17:29:02'),
(42, 134, 6, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu w opisie, szybka dostawa i pięknie zapakowane. Jedynym minusem jest to, że instrukcja obsługi była tylko po angielsku, ale sam towar zasługuje na piątkę.', '2024-10-15 19:33:55'),
(43, 53, 81, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem! Szybka dostawa, doskonała jakość i obsługa - na pewno będę zamawiać tutaj jeszcze.', '2024-10-20 12:05:53'),
(44, 101, 81, 4, 'Naprawdę jestem zadowolony z tego produktu - jakość jest bardzo dobra, a cena całkiem rozsądna. Jedyna mała wada to czas dostawy, ale poza tym polecam!', '2024-10-06 12:05:53'),
(45, 107, 32, 4, 'Produkt jest naprawdę solidny i warto go kupić - doskonała jakość w stosunku do ceny, choć mogłaby być trochę szybsza dostawa. Polecam każdemu, kto szuka niezawodnego rozwiązania w tej kategorii!', '2024-10-10 11:12:49'),
(46, 46, 27, 1, 'Produkt całkowicie nie spełnił moich oczekiwań - materiał jest tandetny, a rozmiaru mi nie odpowiadał mimo zgodności z tabelą. Nie polecam, żaden problem ze zwrotem to dodatkowy koszty i strata czasu.', '2024-10-11 13:26:06'),
(47, 6, 27, 5, 'Doskonały produkt, szybka dostawa i idealna jakość - dokładnie taki, jaki byłem oczekiwał! Bardzo polecam każdemu, naprawdę warto, jestem bardzo zadowolony z zakupu. ⭐⭐⭐⭐⭐', '2024-10-06 13:26:06'),
(48, 151, 9, 4, 'Produkt przyszedł szybko i jest dokładnie taki, jak na zdjęciach - solidny i dobrze wykonany. Jedyna drobna wada to opakowanie mogło być lepsze, ale za tę cenę nie ma się czego narzekać - na pewno polecam!', '2024-10-19 08:23:31'),
(49, 184, 9, 5, 'Produkt doskonały, dokładnie taki, jaki oczekiwałem - wysoka jakość, szybka dostawa i piękne opakowanie. Gorąco polecam każdemu, jestem bardzo zadowolony z mojego zakupu!', '2024-10-26 08:23:31'),
(50, 74, 71, 5, 'Wspaniały produkt, dokładnie taki jak opisany w ofercie - solidny, dobrze wykonany i szybko dotarł. Zdecydowanie polecam wszystkim, jestem bardzo zadowolony z zakupu i na pewno wrócę do tego sklepu!', '2024-10-16 08:27:48'),
(51, 87, 71, 2, 'Produkt całkowicie nie spełnił moich oczekiwań - rozmiar okazał się zdecydowanie za mały, a materiał jest tandetny i już po tygodniu użytkowania widać oznaki zużycia. Zdecydowanie nie polecam, za taką cenę można znaleźć coś dużo lepszego.', '2024-10-27 08:27:48'),
(52, 51, 71, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem - wysokiej jakości, niezawodny i bardzo dobrze zapakowany. Polecam serdecznie, już po raz drugi robię u was zakupy i zawsze jestem zadowolony! ⭐⭐⭐⭐⭐', '2024-10-29 08:27:48'),
(53, 100, 50, 5, 'Produkt dosłownie przeszedł moje oczekiwania - świetna jakość, szybka dostawa i opakowanie bez zarzutów! Zdecydowanie polecam, jestem zachwycona i już wiedziałem, że warto było wydać pieniądze na tę rzecz.', '2024-10-23 17:20:02'),
(54, 112, 50, 4, 'Produkt przyszedł szybko i dobrze zapakowany, funkcjonuje bezawaryjnie. Jestem zadowolony z zakupu, jedyną wadą jest trochę wyższa cena, ale jakość zdecydowanie warta swojego pieniędzy!', '2024-11-06 17:20:02'),
(55, 55, 85, 5, 'Fantastyczny produkt, dokładnie taki jaki oczekiwałem! Szybka dostawa, świetna jakość i niesamowita cena - gorąco polecam każdemu, bez wahania!', '2024-10-26 18:03:27'),
(56, 189, 85, 2, 'Produkt przypomina więcej plastikowego tandety niż rzeczy za tę cenę, a do tego przyszedł uszkodzony i bez połowy akcesoriów z opisu. Nie polecam, pieniądze wyrzucone na wiatr.', '2024-11-01 18:03:27'),
(57, 118, 80, 4, 'Świetny produkt, bardzo zadowolony z zakupu - idealnie odpowiada opisowi i dobrej jakości. Jedynym minusem jest to, że dostarczenie trwało nieco dłużej niż oczekiwałem, ale sama rzecz jest naprawdę warta ceny.', '2024-10-12 15:38:01'),
(58, 32, 80, 3, 'Produkt dotarł na czas i jest w porządku, choć trochę mi go nie starcza. Za taką cenę mogłem oczekiwać lepszej jakości lub większej zawartości, ale do użytku codziowego wystarczy.', '2024-10-23 15:38:01'),
(59, 63, 79, 1, 'Produkt to kompletna porażka - przyszedł uszkodzony, a materiał się już rozpada po tygodniu użytkowania. Zdecydowanie nie polecam i nigdy więcej nie kupuję od tego sprzedawcy!', '2024-11-08 10:40:31'),
(60, 7, 46, 5, 'Produkt przyszedł w idealnym stanie i dokładnie taki, jaki widać na zdjęciach – jakość fenomenalna za taką cenę! Polecam każdemu, naprawdę warto, nie żałuję zakupu! ★★★★★', '2024-10-18 21:17:34'),
(61, 110, 41, 2, 'Bardzo rozczarowujący produkt - materiał kiepskiej jakości, szybko się zniszczył. Za tę cenę mogliśmy oczekiwać o wiele więcej, zdecydowanie nie polecam i żałuję zakupu.', '2024-10-31 17:56:37'),
(62, 142, 22, 5, 'Jestem zachwycona tym produktem! Doskonała jakość, szybka dostawa i faktycznie wygląda dokładnie jak na zdjęciach - polecam wszystkim bez wahania!', '2024-10-17 14:03:23'),
(63, 21, 22, 1, 'Produkt to totalna porażka, przybyła rozerwana, a materiał już po tygodniu zaczął się rozpadać. Nigdy więcej nie będę kupować w tym sklepie, strata czasu i pieniędzy.', '2024-10-21 14:03:23'),
(64, 167, 14, 4, 'Produkt przyszedł szybko i dobrze zapakowany, jestem zadowolony z jakości. Trochę drożej niż u konkurencji, ale wart ceny - polecam!', '2024-10-29 08:21:54'),
(65, 29, 14, 2, 'Produkt przyszedł uszkodzony i nie odpowiada zdjęciom z oferty - materiał jest o wiele słabszy. Nie polecam, moja strata czasu i pieniędzy.', '2024-10-31 08:21:54'),
(66, 75, 14, 4, 'Solidny produkt, dokładnie taki jak na zdjęciach w opisie - dobra jakość i szybka dostawa. Jedynym minusem jest nieco wyższa cena, ale jak na standard to warto, polecam!', '2024-11-08 08:21:54'),
(67, 131, 55, 5, 'Świetna jakość i szybka dostawa! Produkt dokładnie taki jak na zdjęciu, bardzo zadowolony z zakupu i z pewnością będę tutaj jeszcze kupować. 5/5 ⭐', '2024-10-29 14:47:16'),
(68, 10, 55, 5, 'Fantastyczny produkt! Jakość przekracza oczekiwania, szybka dostawa i świetna obsługa sklepu - na pewno będę tu kupować ponownie!', '2024-10-21 14:47:16'),
(69, 114, 61, 4, 'Produkt przyszedł szybko i został dobrze zapakowany, jestem zadowolony z jakości i działa dokładnie tak jak się spodziewałem. Jedynym minusem jest nieco droga wysyłka, ale mimo to polecam!', '2024-10-20 16:16:14'),
(70, 186, 75, 4, 'Produkt przyszedł szybko i jest naprawdę solidny, dokładnie taki jaki oczekiwałem. Jedyna drobna niedogodność to brak polskiego instruktażu, ale ogólnie jestem zadowolony i polecam - warto za tę cenę!', '2024-11-12 11:27:54'),
(71, 116, 47, 5, 'Produkt przyszedł szybko i w idealnym stanie, dokładnie taki jak na zdjęciach! Jestem zachwycony/a jakością i ceną - na pewno będę kupować tu jeszcze, serdecznie polecam! ⭐⭐⭐⭐⭐', '2024-11-03 09:25:32'),
(72, 60, 19, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach! Szybka dostawa, doskonała jakość i jeszcze lepszy stosunek ceny do wartości - gorąco polecam każdemu, kto na to czeka. ⭐⭐⭐⭐⭐', '2024-10-25 15:59:29'),
(73, 178, 66, 4, 'Produkt jest naprawdę solidny i spełnił moje oczekiwania - świetna jakość za rozsądną cenę, a dostawę otrzymałem szybko. Jedynym minusem jest to, że opakowanie mogłoby być trochę lepsze, ale nie zmienia to ogólnie bardzo pozytywnego wrażenia.', '2024-11-10 21:02:49'),
(74, 56, 30, 5, 'Świetny produkt, dokładnie taki jaki oczekiwałem - solidna jakość, szybka dostawa i wszystko w idealnym stanie. Na pewno będę kupować tutaj ponownie, gorąco polecam! ⭐⭐⭐⭐⭐', '2024-11-17 10:09:27'),
(75, 159, 49, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu i bardzo solidny! Szybka dostawa i super obsługa sklepu, na pewno będę zamawiać u Was znowu.', '2024-11-13 11:01:07'),
(76, 112, 49, 4, 'Produkt bardzo mi się podoba, solidny i dokładnie taki, jak opisany - jedynym minusem jest że opakowanie przyszło trochę zniszczone, ale sam towar jest idealny. Polecam, za tę cenę to naprawdę warta inwestycja!', '2024-10-21 11:01:07'),
(77, 20, 47, 5, 'Świetny produkt, dokładnie taki, jaki widać na zdjęciach! Szybka dostawa, super jakość i jeszcze taka cena - nie ma się do czego przyczepić, polecam każdemu! ⭐⭐⭐⭐⭐', '2024-11-07 15:23:24'),
(78, 91, 47, 4, 'Świetny produkt, dokładnie taki jaki się spodziewałam - wysoka jakość w przystępnej cenie. Jedyną niedoskonałością jest to, że trochę dłużej docierał, ale na pewno zamówię tutaj jeszcze raz!', '2024-11-20 15:23:24'),
(79, 199, 4, 5, 'Jestem zachwycona tym produktem! Doskonała jakość, świetna cena i błyskawiczna dostawa - polecam każdemu, naprawdę warto!', '2024-11-21 15:41:50'),
(80, 154, 1, 5, 'Świetny produkt, dokładnie taki, jaki oczekiwałem - wysokiej jakości, szybka dostawa i pięknie zapakowany. Gorąco polecam, już drugi raz robię zakupy w tym sklepie i nie mam żadnych zastrzeżeń!', '2024-11-13 19:16:15'),
(81, 20, 1, 4, 'Doskonały produkt, dokładnie taki jaki sobie wyobrażałem - najwyższej jakości materiał i piękny wygląd. Jedyna drobna wada to opóźnienie w przesyłce, ale sam towar to strzał w dziesiątkę i zdecydowanie warto!', '2024-11-06 19:16:15'),
(82, 120, 11, 3, 'Produkt jest w porządku, ale za taką cenę spodziewałem się lepszej jakości wykonania. Dostarczka była szybka, jednak materiał wydaje mi się dość delikatny i może się szybko zniszczyć.', '2024-10-30 09:02:05'),
(83, 121, 11, 4, 'Świetny produkt, przyszedł szybko i dokładnie taki jak na zdjęciu. Jedynie olewka jest trochę czerstwawa, ale za tę cenę zdecydowanie warto - polecam!', '2024-11-26 09:02:05'),
(84, 142, 11, 4, 'Polecam ten produkt! Jakość świetna, dobrze zapakowany i dotarł szybko. Nie jest perfekcyjny, ale za tę cenę jest naprawdę wart swojej wartości i jestem zadowolony z zakupu.', '2024-11-13 09:02:05'),
(85, 13, 83, 5, 'Świetny produkt, dokładnie taki jaki opisywał sprzedawca - najwyższej jakości i przyszedł w idealnym opakowaniu. Naprawdę warto się dla niego zdecydować, całkowicie mnie zadowolił i już polecam wszystkim moim znajomym!', '2024-11-19 15:23:24'),
(86, 129, 5, 4, 'Produkt przyszedł szybko i dobrze zapakowany, jakość materiału naprawdę zadowalająca jak na tę cenę. Nie mam większych zastrzeżeń, polecam!', '2024-11-27 09:27:49'),
(87, 8, 60, 2, 'Produkt to totalna rozczarowaniem – materiał niezadowalającej jakości, rozsypywał się po kilku dniach użytkowania. Za tę cenę można było oczekiwać czegoś znacznie lepszego, nie polecam i żałuję tego zakupu.', '2024-11-26 14:30:17'),
(88, 4, 60, 5, 'Świetny produkt, dokładnie taki, jak na zdjęciu – solidna jakość i szybka dostawa! Polecam każdemu, naprawdę warto, nie żałuję zakupu.', '2024-11-20 14:30:17'),
(89, 65, 84, 4, 'Polecam ten produkt, naprawdę się spodobał i dokładnie taki, jaki spodziewałem się po opisie. Jedyna drobna rzecz to opakowanie mogło być lepiej zabezpieczone, ale sam towar jest wysokiej jakości i wart swojej ceny.', '2024-11-02 16:01:05'),
(90, 32, 35, 5, 'Produkt doskonały, dokładnie taki, jaki opisany na stronie - szybka dostawa i piękne opakowanie. Polecam każdemu, naprawdę warto, za tę cenę to niesamowita okazja!', '2024-11-03 20:30:55'),
(91, 11, 7, 5, 'Świetny produkt, perfekcyjna jakość i szybka dostawa! Polecam wszystkim, nie zawiodłem się, dokładnie taki jaki byłem spodziewał się. ⭐⭐⭐⭐⭐', '2024-11-07 13:47:03'),
(92, 99, 7, 3, 'Produkt przyszedł szybko i dobrze zapakowany, jednak jakość nie do końca odpowiadała cenie. Dla kogoś szukającego czegoś tańszego sprawdzi się, ale są dostępne lepsze opcje na rynku.', '2024-11-20 13:47:03'),
(93, 77, 7, 4, 'Produkt przyszedł szybko i dokładnie taki, jaki się spodziewałem - solidne wykonanie, świetna cena. Jedyna drobna wada to opakowanie mogłoby być nieco lepsze, ale sam towar to czysty profesjonalizm!', '2024-11-09 13:47:03'),
(94, 40, 12, 4, 'Produkt przyszedł szybko i zapakowny był bardzo starannie. Spełnia wszystkie oczekiwania, jakość jest naprawdę dobra, choć niewiele brakuje do ideału - dodam, że warto go kupić!', '2024-11-22 20:40:20'),
(95, 116, 60, 5, 'Produkt przyszedł szybko i w idealnym stanie! Dokładnie takie jak na zdjęciu, świetnej jakości i cena naprawdę godna polecenia - na pewno będę tu jeszcze kupować. ⭐⭐⭐⭐⭐', '2024-11-12 19:45:03'),
(96, 105, 60, 2, 'Produkt nie spełnił moich oczekiwań - wykonanie kiepskie, a materiał dużo słabszy niż na zdjęciach. Szkoda pieniędzy, nie polecam.', '2024-11-07 19:45:03'),
(97, 125, 60, 5, 'Produkt przyszedł szybko i doskonale zapakowany, jakość materiału przewyższyła moje oczekiwania! Polecam każdemu, kto szuka czegoś niezawodnego i estetycznego - to naprawdę warte pieniędzy.', '2024-11-18 19:45:03'),
(98, 114, 46, 4, 'Bardzo się cieszę z tego zakupu! Produkt ma świetną jakość, szybko dotarł, a dodatkowo cena jest naprawdę konkurencyjna - jedyna drobna rzecz to, że opakowanie mogłoby być nieco bardziej solidne, ale poza tym wszystko super.', '2024-11-09 20:45:57'),
(99, 142, 46, 5, 'Absolutnie polecam! Produkt świetnej jakości, szybka dostawa i przemiła obsługa - nic do dodania, kupuję tutaj jeszcze raz! ⭐⭐⭐⭐⭐', '2024-11-09 20:45:57'),
(100, 18, 39, 4, 'Produkt bardzo dobrej jakości, dokładnie taki jak na zdjęciach - solidny, dobrze zapakowany i szybko dotarł do mnie. Na pewno polecam, jedynym minusem jest dla mnie cena, ale całkowicie warto się pochylić.', '2024-11-25 20:41:57'),
(101, 7, 72, 3, 'Produkt jest w porządku, choć nie spełnił w pełni moich oczekiwań - jakość materiału jest średnia, a dostawa trwała dość długo. Nie mogę narzekać, ale i nie polecam go szczególnie, jeśli szukasz czegoś lepszego w tej cenie.', '2024-11-28 14:26:58'),
(102, 59, 35, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu – jakość powyżej oczekiwań, solidnie wykonany. Jedynie opakowanie mogłoby być lepsze, ale to margines, polecam!', '2024-11-23 13:06:34'),
(103, 50, 69, 3, 'Produkt jest w porządku, ale cena nie do końca odpowiada jakości. Dostarczono szybko, choć opakowanie mogło być lepsze, na szczęście nic się nie uszkdziło.', '2024-11-21 15:39:59'),
(104, 2, 23, 4, 'Produkt przyszedł szybko i dobrze zapakowany, materiał jest rzeczywiście bardzo dobrej jakości, dokładnie taki, jak na zdjęciach. Jedynym minusem jest to, że rozmiar okazał się odrobinę większy niż się spodziewałem, ale generalnie jestem bardzo zadowolony z zakupu.', '2024-11-13 09:45:23'),
(105, 107, 45, 4, 'Bardzo zadowolony z zakupu! Produkt przyszedł szybko, jest dokładnie taki jak w opisie i rzeczywiście świetnie się sprawdza w codziennym użytku – jedynie opakowanie mogło być trochę lepszego качества, ale to mała rzecz wobec takiej ceny.', '2024-11-19 11:19:11'),
(106, 189, 45, 5, 'Genialny produkt, polecam każdemu! Jakość jest bezbłędna, szybka dostawa i super opakowanie - nie mogę się doczekać następnego zamówienia.', '2024-11-29 11:19:11'),
(107, 43, 45, 5, 'Produkt przyszedł szybko i dobrze zapakowany, dokładnie taki jak na zdjęciu. Jestem bardzo zadowolony z jakości, na pewno będę zamawiać znowu!', '2024-11-15 11:19:11'),
(108, 1, 29, 5, 'Świetny produkt, doskonała jakość i szybka dostawa! Gorąco polecam wszystkim, na pewno zamówię tu jeszcze raz. ⭐⭐⭐⭐⭐', '2024-12-06 12:40:44'),
(109, 137, 29, 3, 'Produkt odpowiada opisowi, ale jakość nie jest wcale taka zła ani tak dobra – średniak. Dla ceny, którą zapłaciłem, mogło być trochę lepiej, jednak nie narzekam.', '2024-11-20 12:40:44'),
(110, 141, 29, 3, 'Produkt jest solidny, ale za taką cenę spodziewałem się lepszej jakości materiałów. Dobrze sprawdza się w codziennym użytku, choć zastanawiam się, jak długo wytrzyma intensywne eksploatowanie.', '2024-11-16 12:40:44'),
(111, 110, 29, 3, 'Produkt odpowiada opisowi, ale materiał okazał się mniej trwały niż się spodziewałem. Cena do ceny nie jest zła, choć znalazłem podobne oferty w konkurencji.', '2024-12-01 12:40:44'),
(112, 50, 29, 5, 'Doskonały produkt, dokładnie taki, jaki oczekiwałem – wysokiej jakości wykonania i szybka dostawa. Zdecydowanie polecam, warto każdej złotówki! ⭐⭐⭐⭐⭐', '2024-12-04 12:40:44'),
(113, 21, 7, 5, 'Produkt doskonały, dokładnie taki jaki się spodziewałem - świetna jakość, szybka dostawa i piękne opakowanie! Polecam każdemu, naprawdę warto, już zamawiam następne.', '2024-11-26 10:15:17'),
(114, 37, 7, 2, 'Produkt bardzo rozczarowuje - materiał kiepskiej jakości i już po kilku dniach użytkowania zaczął się rozpadać, a obsługa klienta kompletnie się nie odzywa. Za tę cenę można znaleźć coś znacznie lepszego gdzie indziej.', '2024-12-08 10:15:17'),
(115, 10, 33, 1, 'Produkt to totalna porażka - przyszedł uszkodzony, a obsługa klienta nie chciała nic zrobić. Za takie pieniądze można kupić coś znacznie lepszego w innym miejscu, stanowczo odradzam!', '2024-12-13 15:04:17'),
(116, 20, 42, 5, 'Produkt przyszedł szybko i w idealnym stanie - dokładnie taki, jaki chciałem! Jakość materiału jest naprawdę pierwsza klasa, cena całkowicie uzasadniona, na pewno będę robić tu jeszcze zakupy. ⭐⭐⭐⭐⭐', '2024-12-06 19:47:25'),
(117, 1, 42, 4, 'Jestem bardzo zadowolony z zakupu, produkt doskonale spełnia moje oczekiwania i dotarł szybko. Jedyną małą niedogodnością jest brak instrukcji po polsku, ale z tego powodu nie mogę dać pełnych pięciu gwiazdek.', '2024-11-17 19:47:25'),
(118, 13, 42, 4, 'Świetny produkt, dokładnie taki jak na zdjęciach i szybka dostawa - polecam! Jedynym minusem jest, że opakowanie mogłoby być lepsze, ale sam towar to solidna robota.', '2024-12-01 19:47:25'),
(119, 51, 25, 4, 'Produkt rzeczywiście spełnił moje oczekiwania - dobra jakość, szybka dostawa i dokładnie taki, jaki był pokazany na zdjęciach. Jedynym minusem jest, że opakowanie mogłoby być trochę staranniejsze, ale za taką cenę zdecydowanie warto.', '2024-12-13 14:27:34'),
(120, 65, 25, 5, 'Produkt przyszedł szybko i w idealnym stanie, dokładnie taki jak na zdjęciach - nie mogę się doczekać, kiedy go używać! Naprawdę polecam każdemu, kto szuka czegoś wysokiej jakości w super cenie.', '2024-11-26 14:27:34'),
(121, 88, 45, 4, 'Bardzo jestem zadowolony z tego produktu, dokładnie taki, jaki sobie wyobrażałem - dobra jakość i szybka dostawa. Jedyna mała niedogodność to trochę słabsze opakowanie, ale za tę cenę naprawdę warte polecenia!', '2024-11-25 10:44:31'),
(122, 12, 50, 4, 'Bardzo polecam ten produkt, naprawdę warto! Jakość jest super, dobrze spakowane, szybka dostawa i cena całkiem rozsądna - jedyna mała rzecz to czekanie na przesyłkę, ale poza tym jestem bardzo zadowolona z zakupu.', '2024-11-20 13:44:31'),
(123, 71, 50, 4, 'Produkt jest naprawdę solidny i spełnia wszystkie moje oczekiwania – szybko przyszedł, dobrze zapakowany i świetnie się sprawdza na co dzień. Jedyna mała niedoskonałość to opakowanie mogłoby być trochę lepsze, ale ogólnie jestem bardzo zadowolony i na pewno będę kupować ponownie.', '2024-12-12 13:44:31'),
(124, 43, 19, 5, 'Świetny produkt, całkowicie zadowolony z zakupu! Szybka dostawa, dobra jakość i cena - polecam każdemu.', '2024-11-27 10:52:04'),
(125, 53, 47, 4, 'Produkt jest naprawdę dobrej jakości i dotarł szybko. Jedynym minusem jest brak któregoś z akcesoriów w opakowaniu, ale za tę cenę zdecydowanie warto - polecam!', '2024-11-19 11:24:20'),
(126, 168, 47, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu - solidna jakość i szybka dostawa. Zdecydowanie polecam, jedynym minusem jest trochę wyższa cena, ale warte każdej złotówki!', '2024-11-30 11:24:20'),
(127, 186, 10, 4, 'Produkt doskonały, dokładnie taki jaki sobie wyobrażałem - solidny, dobrze wykonany i szybko dotarł. Jedyna mała pretensja to że opakowanie mogło być lepsze, ale sam artykuł na pewno polecam!', '2024-12-15 14:25:33'),
(128, 195, 10, 2, 'Produkt całkowicie nie spełnił moich oczekiwań - materiał to zwykły plastik, a deklarowana wytrzymałość okazała się totalna bujda. Za taką cenę można znaleźć coś znacznie lepszego gdzie indziej.', '2024-11-27 14:25:33'),
(129, 107, 3, 3, 'Produkt przyszedł w porządnym stanie i spełnia podstawowe funkcje, jednak jakość materiału mogłaby być lepsza, szczególnie jak się weźmie pod uwagę cenę. Dla kogoś poszukującego czegoś tańszego może być wystarczający, ale warto rozejrzeć się za alternatywami.', '2024-11-25 09:57:32'),
(130, 169, 46, 3, 'Produkt odpowiada opisowi, ale niestety materiał okazał się mniej trwały niż się spodziewałem. Za tę cenę mogłoby być lepsze, ale na codzienne użycie sprawdzi się w porządku.', '2024-12-06 18:10:06'),
(131, 139, 8, 5, 'Nie ma się co zastanawiać - to świetny produkt, który w 100% spełnił moje oczekiwania, a do tego przyszedł szybko i dobrze zapakowany. Gorąco polecam każdemu, kto chce coś naprawdę dobrego!', '2024-12-02 13:41:53'),
(132, 172, 85, 5, 'Doskonały produkt, dokładnie taki jaki oczekiwałem - wysoka jakość wykonania i szybka dostawa! Zdecydowanie polecam każdemu, warto każdej złotówki.', '2024-12-20 10:34:39'),
(133, 177, 22, 5, 'Produkt przyszedł szybko i dokładnie taki, jak na zdjęciu - najwyższa jakość w super cenie! Jestem mega zadowolony z zakupu, polecam wszystkim bez wahania.', '2024-11-29 19:54:35'),
(134, 112, 22, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu – solidnie wykonany i szybko dotarł do mnie. Polecam każdemu, jestem naprawdę zadowolony z zakupu!', '2024-12-16 19:54:35'),
(135, 105, 22, 4, 'Produkt przyszedł szybko i dobrze zapakowany, jakość jest naprawdę niezła za taką cenę. Polecam, szczególnie że obsługa sklepu była miła i profesjonalna, jedynym minusem jest to, że mogłoby być trochę więcej szczegółów w opisie produktu.', '2024-12-17 19:54:35'),
(136, 5, 77, 4, 'Produkt jest naprawdę fajny i dobrze wykonany, przyszedł szybko i bezpiecznie zapakowany - polecam! Jedynym minusem jest, że cena mogłaby być trochę niższa, ale na 4/5 gwiazdek zdecydowanie się zasługuje.', '2024-12-12 18:08:26'),
(137, 47, 77, 5, 'Jestem zachwycony tym produktem - jakość jest naprawdę świetna, a dostawka była szybka i bezproblemowa. Zdecydowanie polecam każdemu, kto szuka czegoś niezawodnego i wartościowego!', '2024-12-29 18:08:26'),
(138, 27, 39, 5, 'Świetny produkt, przekroczyło moje oczekiwania! Szybka dostawa, doskonała jakość i dokładnie taki, jaki był na zdjęciu - polecam każdemu! ⭐⭐⭐⭐⭐', '2024-12-09 19:55:21'),
(139, 169, 39, 4, 'Produkt przyszedł szybko i jest dokładnie taki, jak na zdjęciu - solidna jakość i świetna cena. Polecam, jedynym minusem jest opakowanie, które mogło być bardziej staranne, ale to drobnostka.', '2024-12-12 19:55:21'),
(140, 146, 62, 3, 'Produkt dotarł na czas i jest całkiem solidny, choć za tę cenę spodziewałem się lepszej jakości. Nie narzekam, ale z pewnością nie warte są wszystkie pochwalane opinie.', '2024-12-15 09:33:06'),
(141, 11, 62, 5, 'Świetny produkt, dokładnie taki jak się spodziewałem – wysokiej jakości, szybka dostawa i całkowicie wart swojej ceny! Polecam każdemu, jestem pełny pozytywnych wrażeń i na pewno kupię tutaj jeszcze raz.', '2024-12-04 09:33:06'),
(142, 137, 66, 4, 'Świetny produkt, dokładnie taki jaki sobie wyobrażałem – solidna jakość i szybka dostawa. Jedyna drobna rzecz to opakowanie mogło być bardziej starannie zapakowane, ale sam towar to praktycznie siedem listków.', '2024-12-14 14:24:49'),
(143, 144, 71, 3, 'Produkt jest w porządku, ale nie spełnił wszystkich moich oczekiwań - jakość materiału mogłaby być lepsza, a dostawa trwała dłużej niż zapowiadano. Dla ceny, którą zapłaciłem/am, spodziewałem/am się czegoś więcej.', '2024-12-26 15:51:44'),
(144, 81, 71, 5, 'Produkt przyszedł szybko i dokładnie taki, jaki był na zdjęciu - jakość super, polecam! Kupiłam już drugi raz i będę kupować jeszcze, bo za taką cenę to naprawdę wart każdej złotówki.', '2024-12-31 15:51:44'),
(145, 16, 68, 5, 'Fantastyczny produkt, dokładnie taki jaki oczekiwałem - świetna jakość, piękne opakowanie i szybka dostawa! Zdecydowanie polecam, warto każdej złotówki.', '2024-12-09 08:50:53'),
(146, 72, 45, 5, 'Doskonały produkt, dokładnie taki jaki opisano w ofercie - najwyższa jakość i szybka dostawa! Polecam serdecznie wszystkim, kupić jeszcze raz bez wahania.', '2024-12-22 09:36:05'),
(147, 108, 39, 3, 'Produkt przyszedł szybko i jest solidnie wykonany, choć funkcjonalność nieco mnie rozczarowała - nie do końca spełnia to, co obiecywało zdjęcie z aukcji. Dla ceny zasadniczo w porządku, ale pewnie znalazłbym lepsze alternatywy.', '2025-01-01 09:58:59'),
(148, 85, 39, 4, 'Produkt jest naprawdę solidny i funkcjonalny, robi dokładnie to, co obiecuje producent. Jedyna drobna wada to opakowanie mogło być lepsze, ale za tę cenę to naprawdę warte swojej ceny!', '2025-01-05 09:58:59'),
(149, 3, 39, 4, 'Produkt jest naprawdę solidny i trafnie się sprawdza w codziennym użytkowaniu. Jedyna drobna niedoskonałość to nieznaczne opóźnienie w dostarczeniu, ale sama rzecz jest warta tej czterogwiazdkowej oceny - gorąco polecam!', '2024-12-29 09:58:59'),
(150, 67, 3, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem! Szybka dostawa, doskonała jakość i super cena - na pewno będę zamawiać ponownie, polecam wszystkim!', '2024-12-20 15:16:43'),
(151, 105, 2, 1, 'Okropny produkt, totalnie nie wart pieniędzy - materia niskiej jakości, szybko się rozpadł po kilku dniach używania. Nie polecam nikomu, zaoszczędzcie sobie rozczarowania i kupcie coś od innego producenta.', '2024-12-13 17:16:00'),
(152, 136, 2, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach i nawet lepszy niż się spodziewałem! Szybka dostawa, piękne opakowanie i najwyższa jakość – na pewno będę zamawiać jeszcze.', '2024-12-16 17:16:00'),
(153, 29, 63, 5, 'Doskonały produkt, przesyłka dotarła szybko i bezpiecznie! Gorąco polecam, dokładnie takie jak na zdjęciach i nawet lepsze niż się spodziewałem. ⭐⭐⭐⭐⭐', '2025-01-06 12:27:13'),
(154, 83, 17, 4, 'Polecam! Produkt dotarł na czas w idealnym stanie, jakość spełniła moje oczekiwania i jest naprawdę wart swojej ceny. Jedyna drobna niedogodność to brak kompletu akcesoriów, ale i tak jestem zadowolony z zakupu.', '2024-12-24 18:24:42'),
(155, 82, 17, 4, 'Produkt przyszedł szybko i bardzo solidnie zapakowany, jakość rzeczywiście warta swojej ceny. Jedyna drobna wada to brak instrukcji w języku polskim, ale poza tym jestem zadowolony z zakupu i polecam każdemu!', '2024-12-14 18:24:42'),
(156, 29, 48, 5, 'Produkt doskonały, przyszedł szybko i w idealnym stanie - dokładnie to, czego oczekiwałem! Polecam wszystkim, kto szuka czegoś wysokiej jakości w tej cenie.', '2024-12-16 16:50:55'),
(157, 200, 48, 4, 'Towar przyszedł szybko i bardzo dobrze zapakowany, dokładnie taki jak na zdjęciu. Polecam, choć cena mogłaby być nieco niższa, ale jakość rzeczywiście warta pieniędzy.', '2025-01-05 16:50:55'),
(158, 64, 50, 3, 'Produkt zgodny z opisem, ale jakość mogła być lepsza za tę cenę. Dostarczenie szybkie, jednak zastanawiam się, czy warto było na niego czekać - ma swoje plusy, ale i całkiem sporo minusów.', '2024-12-19 16:05:52'),
(159, 180, 50, 4, 'Produkt przyszedł szybko i dobrze zapakowany, dokładnie taki jak na zdjęciu - bardzo zadowolony z zakupu! Jedyna mała niedogodność to brak polskiej instrukcji obsługi, ale ogólnie zdecydowanie polecam, naprawdę dobry stosunek ceny do jakości.', '2024-12-29 16:05:52'),
(160, 91, 29, 5, 'Świetny produkt, dokładnie taki jak w opisie - solidny, pięknie wykonany i szybko dotarł. Polecam wszystkim, jestem bardzo zadowolony z zakupu i chciałbym tu jeszcze wiele razy kupować! 5/5 ⭐', '2025-01-06 12:31:24'),
(161, 38, 29, 4, 'Produkt dotarł szybko i dobrze zapakowany, jakość jest naprawdę godna polecenia. Jedyne, co mogę poprawić to cena, ale biorąc pod uwagę wartość, to solidny zakup, którym jestem zadowolony!', '2025-01-08 12:31:24'),
(162, 9, 72, 5, 'Jestem zachwycona tym produktem - jakość jest świetna, dobrze się sprawdza na co dzień, a cena całkowicie uzasadniona. Polecam każdemu!', '2025-01-11 20:37:20'),
(163, 16, 18, 5, 'Świetna jakość i szybka dostawa! Produkt dokładnie taki, jaki się spodziewałem, solidnie wykonany i już kilka razy się sprawdził. Zdecydowanie polecam każdemu, na pewno kupię tu jeszcze!', '2025-01-10 08:51:01'),
(164, 5, 18, 2, 'Produkt nie spełnił moich oczekiwań – materiał okazał się biednie wykonany, a po kilku dniach użytkowania zaczęły się pojawiać wady. Za taką cenę spodziewałem się znacznie lepszej jakości i żałuję mojego zakupu.', '2025-01-06 08:51:01'),
(165, 67, 43, 1, 'Produkt to kompletna porażka - materiał niskiej jakości, szybko się rozpadł i jeszcze do tego miał błędy w wykonaniu. Za takie pieniądze mogłem oczekiwać dużo więcej, zdecydowanie odradzam.', '2025-01-04 15:01:06'),
(166, 189, 18, 5, 'Świetny produkt, dokładnie taki, jaki byłem sobie wyobrażał - najwyższa jakość, szybka dostawa i niebywale przydatne. Na pewno będę zamawiać znowu i polecam wszystkim!', '2025-01-04 09:53:25'),
(167, 84, 18, 4, 'Produkt jest naprawdę solidny i spełnił moje oczekiwania - szybka dostawa i ładna jakość wykonania. Jedynym minusem jest to, że opakowanie mogło być bardziej starannie zawinięte, ale poza tym polecam!', '2025-01-01 09:53:25'),
(168, 7, 18, 5, 'Najlepszy zakup ostatniego czasu! Produkt przyszedł idealnie zapakowany, jakość jest doskonała, a cena całkowicie uzasadniona. Zdecydowanie polecam każdemu, sam będę zamawiać ponownie! ⭐⭐⭐⭐⭐', '2025-01-05 09:53:25'),
(169, 13, 13, 4, 'Produkt jest naprawdę fajny, jakość przyjemnie mnie zaskoczyła i na całe szczęście przyszedł szybko. Jedyne, czego mi brakuje, to pewnie więcej kolorów do wyboru, ale ogólnie jestem zadowolony i na pewno będę polecać!', '2025-01-08 13:22:18'),
(170, 165, 67, 2, 'Produkt przyszedł uszkodzony i zupełnie nie spełnia swoją funkcji - zaraz po pierwszym użyciu się zepsuł. Za takie pieniądze to rzeczywiście rozczarowanie i od niechęci nie polecę nikomu.', '2024-12-25 12:10:38'),
(171, 28, 67, 5, 'Fantastyczny produkt, najlepszy w swojej cenie! Przesyłka przyszła szybko, wszystko dobrze zapakowane, a sama rzecz przewyższyła moje oczekiwania - zdecydowanie polecam wszystkim.', '2025-01-15 12:10:38'),
(172, 22, 67, 2, 'Produkt rozczarowujący, nic nie działa tak jak obiecywano - materiał tandetny i po tygodniu już się psuje. Nie polecam, pieniądze wyrzucone w błoto, żeby się nie martwić czasu na zwrot.', '2025-01-02 12:10:38'),
(173, 54, 53, 5, 'Produkt doskonały, przyszedł szybko i bezpiecznie zapakowany! Jestem bardzo zadowolony z jakości, dokładnie taki jaki był opisany - zdecydowanie polecam każdemu!', '2025-01-01 21:47:56'),
(174, 6, 54, 3, 'Produkt dotarł w dobrym stanie i zgadza się z opisem, ale niestety jakość materiału okazała się gorsza niż się spodziewałem. Za tę cenę mogłem się spodziewać czegoś lepszego.', '2025-01-17 08:01:40'),
(175, 41, 54, 4, 'Bardzo fajny produkt, solidnie wykonany i dokładnie taki, jaki był na zdjęciach. Szybka dostawa, jedynym minusem jest odrobinę wyższa cena, ale na pewno go polecam!', '2024-12-30 08:01:40'),
(176, 30, 54, 5, 'Świetna jakość i szybka dostawa! Produkt odpowiada opisowi, polecam każdemu - za taką cenę to prawdziwa okazja.', '2024-12-26 08:01:40'),
(177, 49, 36, 5, 'Świetna jakość i super szybka dostawa - wszystko zgodne z opisem! Polecam ten produkt każdemu, naprawdę warto i jestem bardzo zadowolony z zakupu.', '2025-01-02 09:30:44'),
(178, 59, 36, 1, 'Produkt kompletnie nie spełnił moich oczekiwań - materiał jest tandetny, a konstrukcja krucha i już po kilku dniach użytkowania zaczęła się walić. Za takie pieniądze spodziewałem się znacznie lepszej jakości, zdecydowanie nie polecam nikomu!', '2025-01-22 09:30:44'),
(179, 112, 47, 4, 'Produkt jest super, szybko dotarł i dokładnie taki, jaki był na zdjęciu - polecam! Jedynym minusem jest opakowanie mogłoby być nieco lepsze, ale sam produkt jest naprawdę solidny i wart tej ceny.', '2025-01-11 12:58:27'),
(180, 51, 47, 4, 'Produkt jest bardzo solidny i dokładnie taki, jak na zdjęciach - polecam! Jedynym minusem jest to, że przyszedł trochę dłużej niż się spodziewałem, ale sama jakość zasługuje na pełne zadowolenie.', '2024-12-26 12:58:27'),
(181, 12, 47, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu! Zamówiłem kilka dni temu, dotarł szybko i dobrze zapakowany - na pewno będę kupować tu znowu.', '2025-01-15 12:58:27'),
(182, 196, 2, 5, 'Doskonały produkt, dokładnie taki jaki się spodziewałem - bardzo dobra jakość i szybka dostawa! Gorąco polecam, na pewno będę zamawiać od tego sprzedawcy jeszcze raz.', '2025-01-18 12:52:52'),
(183, 46, 2, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu, szybka dostawa i super jakość! Polecam każdemu, na pewno kupię jeszcze.', '2025-01-21 19:51:00'),
(184, 41, 2, 5, 'Produkt doskonały, przyszedł szybko i w idealnym stanie! Nie mogę się nadziwić tak dobrej jakości za taką cenę, zdecydowanie polecam wszystkim i kupię tutaj jeszcze.', '2024-12-29 19:51:00'),
(185, 7, 60, 5, 'Produkt przyszedł szybko i niezwykle dobrze zapakowany. Polecam każdemu - najwyższa jakość, dokładnie taki, jak na zdjęciu, i jestem naprawdę zadowolony z zakupu!', '2025-01-01 08:00:24'),
(186, 9, 58, 4, 'Produkt przyszedł szybko i dobrze zapakowany, wygląda tak samo jak na zdjęciach. Wszystko działa bez zastrzeżeń, mogę polecić - jedynym minusem była trochę wysoka cena dostaw, ale ogólnie jestem zadowolony.', '2025-01-12 09:41:55'),
(187, 46, 24, 4, 'Produkt przyszedł szybko i dobrze zapakowany, jakość całkiem niezła jak na tę cenę - polecam! Jedynym minusem jest, że instrukcja obsługi mogła być bardziej przejrzysta, ale ogólnie jestem zadowolony/a z zakupu.', '2025-01-05 15:11:06'),
(188, 186, 84, 4, 'Świetny produkt, dokładnie taki jaki na zdjęciu - dobra jakość materiału i wykonania, chociaż dostarczenie zajęło nieco dłużej niż się spodziewałem. Na pewno bym to polecił innym i chętnie kupię od tego sklepu ponownie!', '2025-01-17 12:26:17'),
(189, 185, 81, 4, 'Produkt doskonały, dokładnie taki jaki się spodziewałem – solidna jakość i szybka dostawa. Jedynym minusem jest nieco wysza cena, ale zdecydowanie warto, polecam!', '2025-01-17 18:17:28'),
(190, 99, 65, 3, 'Produkt jest solidny i sprawdza się w podstawowym użyciu, jednak za tę cenę spodziewałem się lepszej jakości wykonania. Dla mnie to średniak - nie jest zły, ale nie wkładam go na półkę z ulubionymi zakupami.', '2025-01-23 09:56:28'),
(191, 81, 65, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem! Szybka dostawa, doskonała jakość i polecam każdemu - warto każdej złotówki.', '2025-01-21 09:56:28'),
(192, 112, 81, 4, 'Produkt przyszedł szybko i dobrze zapakowany, jakość całkiem niezła jak na cenę. Jedyna mała wada to opakowanie mogło być bardziej ekologiczne, ale ogólnie jestem zadowolona i polecam!', '2025-01-30 12:27:28'),
(193, 108, 78, 1, 'Produkt to kompletna porażka - wysłali mi coś zupełnie innego niż na zdjęciu i jeszcze uszkodzone. Za takie pieniądze mogłem oczekiwać znacznie lepszej jakości, zdecydowanie nie polecam.', '2025-01-21 15:13:08'),
(194, 96, 78, 3, 'Produkt doszedł w dobrym stanie i zgadza się z opisem, jednak cena jest raczej wysoka w stosunku do jakości materiału. Polecam, ale tylko jeśli będzie okazja na promocję.', '2025-01-12 15:13:08'),
(195, 59, 78, 4, 'Produkt jest naprawdę dobrej jakości i dokładnie taki, jaki widać na zdjęciach - solidnie wykonany i wygodny w użytkowaniu. Jedynym minusem jest, że dostarczenie zajęło trochę dłużej niż się spodziewałem, ale samo dobro jest warte swojej ceny.', '2025-01-13 15:13:08'),
(196, 47, 78, 3, 'Produkt jest solidny i spełnia swoje zadanie, ale cena wydaje mi się trochę wysoka w stosunku do jakości. Nie rozczarował mnie, ale i nie zafascynował - średniak, który można rozważyć, jeśli będzie promocja.', '2025-01-30 21:30:21'),
(197, 16, 78, 5, 'Produkt doskonały! Przyszedł szybko, dobrze zapakowany i wygląda dokładnie jak na zdjęciach - gorąco polecam każdemu, kto szuka czegoś naprawdę wartościowego.', '2025-01-11 21:30:21'),
(198, 51, 78, 5, 'Fantastyczny produkt, przesyłka przyszła szybko i wszystko idealnie zapakowane! Naprawdę polecam, przekonałem się osobiście że warto było wydać te pieniądze, 100% zadowolony 👍', '2025-01-16 21:30:21'),
(199, 169, 13, 3, 'Produkt spełnia swoje podstawowe funkcje, ale jakość mogłaby być lepsza, szczególnie biorąc pod uwagę cenę. Dostarczka była szybka, ale sam towar ma kilka drobnych wad, które mnie trochę rozczarowały.', '2025-02-03 18:54:33'),
(200, 28, 13, 4, 'Świetny produkt za rozsądną cenę, dokładnie taki jak na zdjęciach - polecam! Jedynym minusem jest to, że opakowanie przyszło trochę pomiętane, ale rzecz sama jest warte swojej ceny i działała od razu bez żadnych problemów.', '2025-01-16 18:54:33'),
(201, 181, 43, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach! Szybka dostawa, superowa jakość i przystępna cena - polecam wszystkim, nie żałuję zakupu!', '2025-01-07 21:09:05'),
(202, 135, 38, 5, 'Niesamowity produkt! Dokładnie taki, jaki pokazano w opisie - świetna jakość, szybka dostawa, a do tego jeszcze przyszło w pięknym opakowaniu. Serdecznie polecam każdemu, naprawdę warto!', '2025-01-14 18:11:16'),
(203, 106, 38, 5, 'Niesamowita jakość za taką cenę! Towar przyszedł szybko i dobrze zapakowany, dokładnie taki jak na zdjęciach - polecam wszystkim bez wahania! ⭐⭐⭐⭐⭐', '2025-01-23 18:11:16'),
(204, 168, 9, 3, 'Produkt jest przyzwoity, ale niezbyt wyjątkowy. Za tę cenę można znaleźć lepsze alternatywy, mimo że jakość nie jest zła.', '2025-01-25 11:59:59'),
(205, 141, 9, 5, 'Fantastyczny produkt, dokładnie taki jak na zdjęciu! Szybka wysyłka i świetna jakość - polecam każdemu, naprawdę warto!', '2025-01-29 11:59:59'),
(206, 198, 35, 2, 'Produkt całkowicie nie spełnił moich oczekiwań - materiał okazał się być kiepskiej jakości, a po kilku dniach użytkowania już się rozlatuje. Szkoda czasu i pieniędzy, zdecydowanie nie polecam.', '2025-02-04 10:04:49'),
(207, 36, 8, 4, 'Świetny produkt, dokładnie taki, jaki widziałem na zdjęciu – solidny, dobrze wykonany i szybko dotarł. Zdecydowanie polecam, jedynie szkoda, że brakuje mi zapachu, ale to drobnostka, która nie psuje całego wrażenia.', '2025-02-08 10:16:20'),
(208, 99, 8, 4, 'Świetny produkt za rozsądną cenę, szybko przyszedł i naprawdę spełnia swoje zadanie. Jedynym minusem jest, że opakowanie mogłoby być lepsze, ale samo dobro jest top i już go polecam znajomym.', '2025-01-27 10:16:20'),
(209, 59, 53, 5, 'Absolutnie zachwycony tym produktem! Jakość wykonania jest wzorowa, szybka dostawa i dokładnie takie, jak na zdjęciach - polecam wszystkim bez wahania!', '2025-01-21 11:24:24'),
(210, 25, 66, 5, 'Świetnie zrobiony produkt, dokładnie taki, jaki widziałem na zdjęciach - wysokiej jakości i szybko dostarczony. Zdecydowanie polecam, warto każdej złotówki! ⭐⭐⭐⭐⭐', '2025-01-25 08:20:21'),
(211, 186, 47, 5, 'Polecam! Produkt spełnił wszystkie moje oczekiwania, doskonała jakość i super szybka dostawa. Nie żałuję zakupu, z pewnością będę zamawiać więcej! ⭐⭐⭐⭐⭐', '2025-01-23 08:13:36'),
(212, 126, 47, 5, 'Świetny produkt! Przesyłka dotarła szybko i dobrze opakowana, a sam towar jest dokładnie taki jak na zdjęciach - wysokiej jakości i solidnie wykonany. Polecam wszystkim, naprawdę warto!', '2025-02-01 08:13:36'),
(213, 123, 47, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach - dobra jakość, szybka dostawa i super cena! Polecam wszystkim, jestem naprawdę zadowolony z zakupu.', '2025-01-20 08:13:36'),
(214, 58, 26, 2, 'Produkt całkowicie nie spełnił moich oczekiwań - szybko się zdarł, a jakość materiału była zdecydowanie poniżej standardu. Żałuję zakupu i nie polecam, lepiej zapłacić więcej i kupić coś wartościowego.', '2025-01-16 18:30:00'),
(215, 6, 26, 5, 'Produkt fantastyczny, dobrze zapakowany i taki jak na zdjęciach - serdecznie polecam! Dostawy błyskawiczna, a obsługa sklepu bardzo miła, z pewnością wracam po więcej. ⭐⭐⭐⭐⭐', '2025-01-20 18:30:00'),
(216, 19, 7, 4, 'Bardzo polecam! Produkt przyszedł szybko, dobrze zapakowany i dokładnie taki jaki widać na zdjęciach. Jedyna drobna niedogodność to brak instrukcji obsługi w polskim, ale nic to nie zmienia faktu, że jestem zadowolony z zakupu.', '2025-01-26 19:36:59'),
(217, 120, 18, 2, 'Produkt kompletnie nie spełnił moich oczekiwań - materiał tandetny, a po dwóch tygodniach użytkowania już się rozpadł. Nie polecam, poleciłem pieniądze w błoto.', '2025-02-03 21:42:39'),
(218, 72, 6, 4, 'Świetny produkt, dokładnie taki jak na zdjęciach - solidny i dobrej jakości. Jedyna szkoda, że dostarczenie trochę się przeciągnęło, ale na pewno będę tu jeszcze zamawiać!', '2025-02-04 19:22:36'),
(219, 171, 52, 5, 'Świetny produkt! Polecam go każdemu - żadnych wad, wszystko działa idealnie i przyszło szybko. Naprawdę warto!', '2025-01-28 20:17:38'),
(220, 188, 52, 5, 'Produkt przyszedł szybko i dokładnie taki, jak się spodziewałem - najwyższa jakość! Gorąco polecam wszystkim, jestem bardzo zadowolony z zakupu i na pewno będę tutaj kupować znowu.', '2025-01-22 20:17:38'),
(221, 157, 52, 5, 'Świetny produkt, dokładnie taki jaki opisywał sprzedawca - najwyższa jakość i solidne wykonanie! Polecam każdemu, warto każdej złotówki.', '2025-02-14 20:17:38'),
(222, 9, 17, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu, wysyłka błyskawiczna! Polecam każdemu, bardzo zadowolony z zakupu i na pewno będę zamawiać tutaj jeszcze.', '2025-02-11 15:35:46'),
(223, 55, 17, 4, 'Produkt przyszedł szybko i bardzo dobrze zapakowany, dodatkowo jakość przeszła moje oczekiwania. Jedyna drobnostka to niewielkie opóźnienie w wysyłce, ale mimo to jestem zadowolony i chętnie polecę ten sklep znajomym!', '2025-02-05 15:35:46'),
(224, 152, 42, 2, 'Produkt to kompletna klapa - materiał słabej jakości, a do tego do mnie doszedł uszkodzony i popękany. Zwróciłem go zaraz po otrzymaniu, bo za takie pieniądze nie ma się czym pochwalić.', '2025-01-23 14:55:05'),
(225, 107, 42, 5, 'Doskonały produkt, dokładnie taki jak na zdjęciu - solidna jakość w super cenie! Polecam każdemu, szybka dostawa i zadowolony jestem na 100%.', '2025-01-26 14:55:05'),
(226, 53, 61, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu – solidna jakość i szybka dostawa! Gorąco polecam, naprawdę wart swojej ceny.', '2025-01-26 12:16:15');
INSERT INTO `product_ratings` (`id`, `product_id`, `user_id`, `rating`, `comment`, `created_at`) VALUES
(227, 156, 61, 4, 'Świetny produkt, dokładnie taki jaki się spodziewałem – solidna jakość i szybka dostawa. Jedyna małość to opakowanie mogłoby być trochę bardziej wytrzymałe, ale ogólnie na pewno polecam!', '2025-02-06 12:16:15'),
(228, 7, 59, 4, 'Produkt doskonały, całkowicie zgodny z opisem - solidna jakość i szybka dostawa. Jedynym minusem jest trochę wyższa cena, ale naprawdę warto, wciąż bym to polecał każdemu!', '2025-01-24 18:25:06'),
(229, 169, 81, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach – wysokiej jakości i solidnie wykonany! Dostarczono szybko i bezpiecznie zapakowane, na pewno będę kupować tu więcej. ⭐⭐⭐⭐⭐', '2025-02-02 20:00:35'),
(230, 131, 5, 2, 'Produkt całkowicie nie spełnił moich oczekiwań - materiał okazał się tandetny, a towar przyszedł uszkodzony. Za taką cenę można znaleźć coś znacznie lepszej jakości w innym sklepie.', '2025-02-02 16:29:49'),
(231, 53, 31, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach, bardzo szybka dostawa! Zdecydowanie polecam, jestem bardzo zadowolony z zakupu i na pewno będę tutaj zamawiać jeszcze.', '2025-02-03 18:37:59'),
(232, 5, 52, 3, 'Produkt odpowiada opisowi, ale jest droższy niż u konkurencji i dostarczenie trwało dłużej niż się spodziewałem. Dla tej ceny mogę znaleźć lepsze alternatywy.', '2025-02-11 09:23:05'),
(233, 146, 24, 5, 'Świetny produkt, przyszedł szybko i dobrze zapakowany! Polecam każdemu, dokładnie taki jaki chciałem - najwyższa klasa! 5/5 ⭐', '2025-02-12 20:11:02'),
(234, 36, 15, 4, 'Produkt dokładnie taki jak w opisie, świetna jakość za rozsądną cenę! Jedynym minusem jest brak szybszej dostawy, ale ogólnie jestem bardzo zadowolona i na pewno będę zamawiać jeszcze.', '2025-02-19 15:29:58'),
(235, 107, 69, 5, 'Fantastyczny produkt, dokładnie taki jak na zdjęciu! Szybka dostawa, świetna jakość wykonania i naprawdę warta swoją cenę - polecam wszystkim! ⭐⭐⭐⭐⭐', '2025-02-23 16:42:40'),
(236, 174, 82, 4, 'Produkt warto kupić - jakość całkiem dobra za taką cenę, szybka dostawa i ponadto wciąż działa bez najmniejszych problemów. Jedynym minusem jest opakowanie mogłoby być trochę solidniejsze, ale to niedużó rzeczy.', '2025-01-31 09:23:02'),
(237, 49, 16, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu! Dostarczony szybko, dobrze zapakowany, jedynie trochę droższy niż u konkurencji, ale jakość warta swojej ceny. Gorąco polecam!', '2025-02-02 20:14:21'),
(238, 10, 16, 5, 'Fantastyczny produkt, przekracza wszelkie oczekiwania! Zamówienie przyszło szybko, a jakość i opakowanie nie pozostawiają nic do życzenia - na pewno będę zamawiać jeszcze.', '2025-02-08 20:14:21'),
(239, 67, 9, 5, 'Świetny produkt, dokładnie taki jaki sobie wyobrażałem - najwyższa jakość za rozsądną cenę. Dostarczenie było szybkie, a opakowanie wzorowe, polecam każdemu!', '2025-02-10 16:49:09'),
(240, 58, 9, 4, 'Produkt bardzo solidny i dokładnie taki, jak na zdjęciach. Szybka dostawa i świetna jakość, choć mogłoby być nieco taniej - mimo to zdecydowanie polecam! ⭐⭐⭐⭐', '2025-01-31 16:49:09'),
(241, 70, 9, 5, 'Produktu polecam z całego serca - doskonała jakość, szybka dostawa i dokładnie taki, jaki był na zdjęciu! Jestem bardzo zadowolona z zakupu i na pewno będę kupować tutaj ponownie.', '2025-02-02 16:49:09'),
(242, 75, 9, 5, 'Świetny produkt, dokładnie taki, jaki sobie wyobrażałem! Szybka dostawa, najwyższa jakość i niesamowita cena - polecam każdemu bez wahania! ⭐⭐⭐⭐⭐', '2025-02-08 16:49:09'),
(243, 177, 32, 4, 'Świetny produkt, dokładnie taki jaki się spodziewałem! Szybka dostawa, ładnie zapakowane, jedyna mała niedogodność to że nieco inny odcień niż na zdjęciu, ale i tak jestem zadowolony. Polecam! 👍', '2025-02-12 11:38:48'),
(244, 3, 32, 2, 'Produkt to zwykła rozczarowaniem - materiał tandetny, szybko się zdarł, a do tego rozmiar okazał się zupełnie inny niż na zdjęciu. Za takie pieniądze spodziewałem się o wiele lepszej jakości, nie polecam.', '2025-02-19 11:38:48'),
(245, 189, 32, 5, 'Niesamowity produkt, przyszedł szybko i w idealnym stanie! Wszystko dokładnie takie, jak się spodziewałem – polecam każdemu bez wahania, na pewno kupię u was jeszcze!', '2025-02-09 11:38:48'),
(246, 162, 32, 4, 'Bardzo zadowolona z zakupu! Produkt przyszedł szybko i dobrze zapakowany, dokładnie taki jak na zdjęciu, tylko szkoda że raz już wygląda na lekko przetarty, ale cena wart każdej złotówki.', '2025-02-05 11:38:48'),
(247, 67, 26, 5, 'Świetny produkt, dokładnie taki jaki opisywało ogłoszenie - solidna jakość i piękny wygląd. Jestem bardzo zadowolony z zakupu, polecam każdemu!', '2025-02-04 14:02:41'),
(248, 61, 41, 4, 'Produkt na prawdę wart swoich pieniędzy, solidny wykonanie i szybka dostawa - jedyne co by mogło być lepsze to opakowanie, ale to drobiazg. Zdecydowanie polecam, będę tu jeszcze zamawiać!', '2025-03-07 17:19:34'),
(249, 142, 41, 4, 'Produkt przyszedł szybko i w idealnym stanie, naprawdę spełnia oczekiwania. Polecam, zwłaszcza za taką cenę - jedynym minusem jest to, że mogłoby być trochę lepszej jakości, ale na 4/5 zdecydowanie gra.', '2025-02-24 17:19:34'),
(250, 25, 41, 4, 'Produkt jest naprawdę solidny i warte swojej ceny - dobrze wykonany, funkcjonalny i przyszedł w doskonałym stanie. Jedynym minusem jest to, że dostawa trwała nieco dłużej niż się spodziewałem, ale samo urządzenie mi się bardzo podoba!', '2025-02-17 17:19:34'),
(251, 166, 59, 4, 'Polecam! Produkt przyszedł szybko i świetnie się sprawdza w codziennym użytkowaniu, jedynie opakowanie mogłoby być lepiej zabezpieczone, ale to drobnostka.', '2025-02-20 17:37:01'),
(252, 2, 57, 5, 'Świetny produkt! Jakość na najwyższym poziomie, szybko przyszło i dokładnie takie, jak na zdjęciach - jestem absolutnie zadowolona i na pewno będę kupować tutaj jeszcze.', '2025-02-21 11:40:21'),
(253, 116, 42, 5, 'Produkt przyszedł szybko i idealnie spakowany, dokładnie taki jak na zdjęciach. Jestem całkowicie zadowolony/zadowolona z jakości i ceny - na pewno będę zamawiać u was ponownie!', '2025-03-09 15:15:28'),
(254, 47, 42, 4, 'Świetny produkt, szybko dotarł i dokładnie taki jaki na zdjęciu - polecam! Jedyna mała wada to opakowanie, które mogło być lepsze, ale sam towar jest naprawdę zadowalający za tę cenę.', '2025-02-10 15:15:28'),
(255, 4, 69, 5, 'Niesamowity produkt, dokładnie taki jak na zdjęciach! Jakość na najwyższym poziomie, szybka dostawa i gorąco polecam każdemu - warta każda złotówka! ⭐⭐⭐⭐⭐', '2025-02-18 17:24:01'),
(256, 23, 69, 4, 'Bardzo zadowolony z zakupu, produkt przyszedł szybko i jest dokładnie taki, jaki opisywano na stronie. Jedynym minusem jest brak polskiej instrukcji obsługi, ale poza tym wszystko super!', '2025-02-27 17:24:01'),
(257, 189, 14, 2, 'Rozczarowujący produkt, materiał słabej jakości i szybko się wysypał. Za taką cenę spodziewałem się czegoś znacznie lepszego, na pewno więcej nie kupię.', '2025-02-16 15:46:41'),
(258, 74, 14, 4, 'Produkt doskonale zaspokaja moje oczekiwania i nadeszedł szybko - polecam! Jedynym minusem jest opakowanie, które mogłoby być bardziej ekologiczne, ale jakość towaru tego w pełni rekompensuje.', '2025-02-25 15:46:41'),
(259, 60, 14, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu, dobra jakość i szybka dostawa! Na pewno zakupię tu znowu, polecam każdemu.', '2025-02-27 15:46:41'),
(260, 109, 45, 5, 'Najwyższa ocena! Produkt przyszedł szybko i idealnie spakowany, jakość naprawdę imponująca za taką cenę. Polecam każdemu, nie żałuję zakupu! 5/5 ⭐', '2025-03-12 08:34:06'),
(261, 85, 18, 5, 'Świetny produkt, dokładnie taki, jaki pokazany na zdjęciu - solidna jakość, szybko przyszła przesyłka. Polecam każdemu, na pewno będę tu kupować jeszcze!', '2025-02-16 14:14:26'),
(262, 182, 18, 4, 'Świetny produkt, dokładnie taki jak w opisie, bardzo szybka dostawa. Jedynym minusem jest brak dodatkowych akcesoriów w zestawie, ale zdecydowanie godny polecenia i na pewno będę tu jeszcze kupować.', '2025-02-24 14:14:26'),
(263, 164, 18, 4, 'Produkt przyjechał szybko i bardzo dobrze zapakowany, jakość rzeczywiście nie zawiedzie. Jedynym minusem jest, że mogłoby być trochę więcej szczegółów w opisie, ale mimo wszystko jestem zadowolony z zakupu i będę polecać ten sklep znajomym!', '2025-03-12 14:14:26'),
(264, 105, 18, 3, 'Produkt jest w porządku, choć szczerze mówiąc nie spełnił moich oczekiwań. Dobre wykonanie, ale za tę cenę spodziewałem się czegoś lepszego pod względem jakości materiału.', '2025-03-11 14:14:26'),
(265, 175, 13, 1, 'Produkt to zwykła zapaść - przyszedł z defektem, a obsługa klienta odpowiadała mi dopiero po miesiącu. Za takie pieniądze mogłem coś znacznie lepszego znaleźć u konkurencji, kompletna strata czasu i kasy.', '2025-02-28 20:29:20'),
(266, 2, 49, 4, 'Świetny produkt, dokładnie taki jaki oczekiwałem – dobra jakość i szybka dostawa. Jedynym minusem jest, że opakowanie mogło być bardziej starannie przygotowane, ale sam towar to solidna czwórka.', '2025-02-23 21:15:24'),
(267, 59, 49, 5, 'Produkt przyszedł szybko i doskonale spakowany, a jakość przewyższyła moje oczekiwania - naprawdę warte każdego grosza! Gorąco polecam, już zamówiłem sobie drugi egzemplarz dla przyjaciela.', '2025-03-06 21:15:24'),
(268, 1, 41, 5, 'Produkt doskonały, przyszedł szybko i dobrze zapakowany, dokładnie taki jaki pokazany na zdjęciu! Polecam każdemu, naprawdę warta cena i najwyższej jakości wykonanie. ⭐⭐⭐⭐⭐', '2025-02-27 11:44:31'),
(269, 188, 53, 1, 'Produkt to totalna porażka - przyszedł uszkodzony, a obsługa klienta wcale nie chciała mi pomóc. Za takie pieniądze spodziewałem się znacznie więcej, zdecydowanie nie polecam, strata czasu i pieniędzy.', '2025-03-11 16:19:04'),
(270, 121, 53, 3, 'Produkt spełnia swoją funkcję, ale jakość mogłaby być lepsza, zwłaszcza biorąc pod uwagę cenę. Dobrze by było, gdyby producent zadbał o wykończenie detali.', '2025-02-28 16:19:04'),
(271, 159, 6, 5, 'Genialny produkt, dokładnie taki jaki oczekiwałem - wysokiej jakości, szybka dostawa i świetny stosunek ceny do jakości. Polecam każdemu, już teraz czekam na następne zamówienie!', '2025-02-18 13:09:58'),
(272, 70, 6, 4, 'Produkt jest naprawdę solidny i przeszedł już u nas całą testowo, mogę go szczerze polecić wszystkim szukającym czegoś niezawodnego w tej cenie. Jedyną niedoskonałością jest opakowanie, które trochę przytłocze przy przesyłce, ale sam towar jest świetny!', '2025-02-19 13:09:58'),
(273, 41, 6, 5, 'Doskonały produkt, dokładnie taki jak na zdjęciu w sklepie - wysokiej jakości materiał i niesamowita cena! Gorąco polecam, jestem bardzo zadowolony z zakupu i na pewno wrócę do tego sklepu.', '2025-03-03 13:09:58'),
(274, 144, 75, 4, 'Produkt przyszedł szybko i jest naprawdę solidny, zupełnie taki jaki byłem po sobie wymaga od teraz na rzeczy. Mogę polecić, moja jedyna uwaga to że opakowanie mogło być lepsze ale za tę cenę to świetny wybór!', '2025-03-18 10:57:18'),
(275, 16, 82, 3, 'Produkt ma niezłą jakość i szybko dotarł do mnie, ale cena jest dość wysoka w stosunku do tego, co oferuje. Nie rozczarowała mnie, ale i nie zachwycił - średniak godny polecenia tylko, gdy będzie promocja.', '2025-03-18 18:43:59'),
(276, 130, 73, 1, 'Produkt to kompletna porażka - przyszedł uszkodzony, a instrukcja obsługi była niezrozumiała. Za takie pieniądze spodziewałem się znacznie lepszej jakości i nie polecam go nikomu.', '2025-02-25 08:34:18'),
(277, 75, 17, 4, 'Produkt jest naprawdę świetny, przyjechał szybko i dobrze zapakowany - mam tylko małą uwagę, że opakowanie mogłoby być nieco mniej plastiku. Polecam każdemu, kto szuka czegoś niezawodnego w tej cenie!', '2025-03-16 12:20:39'),
(278, 139, 17, 5, 'Fantastyczny produkt, dokładnie taki jak na zdjęciu i jeszcze lepszy w rzeczywistości! Szybka dostawa, świetna jakość i za bardzo rozsądną cenę - zdecydowanie polecam każdemu, na pewno będę zamawiać jeszcze.', '2025-03-16 12:20:39'),
(279, 29, 17, 5, 'Świetny produkt, bardzo zadowolony z jakości i szybkiej dostawy - wszystko przyszło w idealnym stanie! Zdecydowanie polecam, warto każdej złotówki.', '2025-03-06 12:20:39'),
(280, 111, 64, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu, a wysyłka była szybka i sprawna. Polecam, jedynym minusem jest brak różnych wariantów kolorów, ale za tę cenę to naprawdę warte wrzucenia do koszyka!', '2025-02-23 14:06:30'),
(281, 51, 54, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach! Szybka dostawa i naprawdę wysokiej jakości materiały - nie mogę się doczekać, aby go używać. Polecam każdemu! ⭐⭐⭐⭐⭐', '2025-03-04 16:20:06'),
(282, 31, 8, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach, szybko dotarł i świetnie spakowany! Naprawdę polecam, za taką cenę to jest strzał w dziesiątkę, już zamówiłem drugi raz.', '2025-03-12 17:27:30'),
(283, 12, 8, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem - najwyższa jakość i szybka dostawa! Zdecydowanie polecam, jestem bardzo zadowolony z zakupu i już chcę zamówić coś więcej od tego sprzedawcy.', '2025-03-12 17:27:30'),
(284, 44, 8, 4, 'Produkt przyszedł w idealnym stanie i bardzo szybko. Polecam - naprawdę wart swojej ceny, jedynym minusem jest brak instrukcji po polsku, ale użytkowanie jest intuicyjne.', '2025-02-26 17:27:30'),
(285, 20, 79, 5, 'Świetna jakość produktu, dokładnie taki, jak pokazywany na zdjęciach! Szybka dostawa i niezawodny seller - polecam każdemu, jestem bardzo zadowolony z zakupu! 5/5', '2025-03-25 18:34:04'),
(286, 105, 79, 5, 'Jestem zachwycony tym produktem! Doskonała jakość, szybka dostawa i dokładnie to, co się spodziewałem – na pewno będę zamawiać od tego sklepu ponownie.', '2025-03-07 18:34:04'),
(287, 177, 48, 5, 'Świetny produkt, dokładnie taki, jaki pokazywał producent! Szybka dostawa, piękne opakowanie i naprawdę godne polecenia - z czystym sumieniem dać 5 gwiazdek! ⭐⭐⭐⭐⭐', '2025-03-07 09:20:33'),
(288, 109, 62, 5, 'Świetny produkt, dokładnie taki, jaki się spodziewałem - wysokiej jakości, solidne wykonanie i szybka dostawa. Gorąco polecam, naprawdę warto!', '2025-03-21 21:07:32'),
(289, 25, 62, 1, 'Okropny produkt, który rozpadł się po tygodniu używania - wysyłam reklamację. Za taką cenę spodziewałem się znacznie lepszej jakości i nie polecam tego nikomu.', '2025-02-25 21:07:32'),
(290, 23, 77, 3, 'Produkt jest solidny, ale nic wyjątkowego - odpowiada cenie i spełnia swoją funkcję. Dostawa była szybka, choć opakowanie mogłoby być lepsze.', '2025-03-13 13:23:42'),
(291, 112, 70, 4, 'Produkt przyszedł szybko i bardzo ładnie zapakowany, robi dokładnie to co obiecuje - jestem bardzo zadowolona. Jedyną małą niedogodnością jest brak polskiej instrukcji, ale poza tym to solidna rzecz za dobrą cenę!', '2025-03-15 12:29:22'),
(292, 66, 47, 3, 'Produkt zgodny z opisem, jednak jakość materiału mogła być lepsza jak na tę cenę. Dostawę otrzymałem na czas, ale nie jestem całkowicie zadowolony z trwałości.', '2025-03-05 14:12:04'),
(293, 185, 47, 3, 'Produkt jest w porządku, choć nie spełnił moich oczekiwań. Jakość dobra, ale cena trochę wysoka w stosunku do tego, co otrzymujesz.', '2025-02-28 14:12:04'),
(294, 161, 47, 5, 'Świetny produkt, dokładnie taki, jaki sobie wyobrażałem - solidny, ładnie zapakowany i szybko dotarł. Polecam z czystym sumieniem, na pewno będę kupować tutaj więcej!', '2025-03-08 14:12:04'),
(295, 16, 38, 5, 'Doskonały produkt, dokładnie taki jak na zdjęciach! Szybka dostawa, solidne opakowanie i niesamowita jakość - jestem zachwycona, na pewno będę zamawiać ponownie. ⭐⭐⭐⭐⭐', '2025-03-31 17:22:38'),
(296, 179, 38, 1, 'Produkt nie spełnił moich oczekiwań - materiał był kiepskiej jakości i już po tygodniu zaczął się sypać. Za taką cenę mogłem kupić coś znacznie lepszego, nie polecam i żałuję tego zakupu.', '2025-03-16 17:22:38'),
(297, 35, 30, 5, 'Przepiękny produkt, dokładnie taki, jaki wyglądał na zdjęciu! Szybka dostawa, świetna jakość i jeszcze tańsze niż u konkurencji – polecam każdemu!', '2025-03-04 13:47:42'),
(298, 169, 80, 5, 'Doskonały produkt, przesyłka dotarła szybko i dobrze zapakowana! Polecam każdemu, całkowicie spełnił moje oczekiwania i warte każdego złotego. ⭐⭐⭐⭐⭐', '2025-03-03 16:49:07'),
(299, 100, 80, 4, 'Bardzo zadowolony z zakupu - produkt jest naprawdę solidny i dobrze wykonany, całkiem przekonał mnie swoją jakością. Jedynym minusem jest droga dostawa, ale za samą rzecz daję 4/5 gwiazdek, bo warto!', '2025-03-03 20:59:11'),
(300, 137, 80, 4, 'Produkt przyszedł szybko i dobrze zapakowany, jakość całkiem niezła. Mogę polecić, chociaż za tę cenę mogłoby być coś lepsze, ale na pewno nie żałuję zakupu!', '2025-03-18 20:59:11'),
(301, 91, 80, 5, 'Produkt doskonały, dokładnie taki, jak opisano w ogłoszeniu - wysokiej jakości, solidnie wykonany i szybko dotarł. Polecam każdemu, naprawdę warto, już nie robię zakupów nigdzie indziej!', '2025-03-20 20:59:11'),
(302, 104, 80, 5, 'Świetny produkt, dokładnie taki jak na zdjęciu i bardzo szybka dostawa! Polecam każdemu, naprawdę warto - na pewno będę kupować znowu.', '2025-03-28 20:59:11'),
(303, 108, 25, 4, 'Bardzo dobry produkt, dokładnie taki jak w opisie - solidny, funkcjonalny i bez żadnych wad. Dla mnie to zdecydowanie warte ceny, jedyny minus to trochę dłużej czekałem na dostawę, ale to nie wina sklepu.', '2025-03-27 09:18:05'),
(304, 195, 25, 5, 'Świetny produkt, dokładnie taki jaki się spodziewałem! Jakość super, szybka dostawa i jeszcze cena konkurencyjna - polecam każdemu, nie żałuję zakupu! ⭐⭐⭐⭐⭐', '2025-03-11 09:18:05'),
(305, 6, 25, 4, 'Bardzo zadowolony z zakupu, produkt jest solidny i dobrze wykonany, całkowicie spełnia moje oczekiwania. Jedynym minusem jest, że trochę dłużej czekałem na dostawę, ale zdecydowanie polecam.', '2025-04-02 09:18:05'),
(306, 129, 56, 1, 'Zamawiałem ten produkt z nadzieją, ale otrzymałem kompletnie rozbite opakowanie, a sam towar okazał się zdecydowanie gorszej jakości niż na zdjęciach. Całkowicie nie polecam - to była strata pieniędzy i czasu.', '2025-03-10 16:22:23'),
(307, 84, 56, 4, 'Świetny produkt, dokładnie taki jak na zdjęciu - dobra jakość materiału i dopasowanie. Jedyna niedoskonałość to dość długi czas dostawy, ale poza tym polecam!', '2025-03-12 16:22:23'),
(308, 161, 18, 4, 'Bardzo zadowolony z zakupu, produkt przyszedł szybko i jest dokładnie taki jak na zdjęciach. Jedyne co mogę zarzucić to przesada z pakowaniem, ale poza tym polecam - za taką cenę to naprawdę solidna rzecz!', '2025-03-27 12:13:51'),
(309, 8, 18, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach - wysokiej jakości i szybka dostawa! Polecam każdemu, jestem bardzo zadowolony z zakupu i na pewno będę zamawiać znowu. ⭐⭐⭐⭐⭐', '2025-03-11 12:13:51'),
(310, 112, 35, 5, 'Fantastyczny produkt, dokładnie taki jak na zdjęciu – solidna jakość i bardzo szybka dostawa! Wszystko super, polecam każdemu, już zamawiam więcej.', '2025-03-19 17:25:34'),
(311, 83, 35, 4, 'Jestem bardzo zadowolony z tego produktu, wykonanie jest solidne a cena całkowicie uzasadniona. Jedynym minusem jest, że dostarczenie trwało nieco dłużej niż się spodziewałem, ale towar dotarł w idealnym stanie.', '2025-03-25 17:25:34'),
(312, 2, 35, 5, 'Polecam ten produkt z całego serca! Świetna jakość, szybka dostawa i naprawdę warte każde złote - już nie mogę się doczekać następnego zakupu w tym sklepie. ⭐⭐⭐⭐⭐', '2025-03-12 17:25:34'),
(313, 114, 43, 4, 'Produkt dotarł szybko i jest dokładnie taki, jaki się spodziewałem - wysokiej jakości, wygodny i perfekcyjnie wykonany. Gorąco polecam, jedyną minusem jest nieco wyższa cena, ale jakość warta jest każdej złotówki!', '2025-04-02 17:52:01'),
(314, 9, 43, 2, 'Produkt nie spełnił moich oczekiwań - materiał okazał się kiepskiej jakości, a już po kilku dniach użytkowania widać wyraźne ślady zużycia. Zdecydowanie nie polecam, warto wydać więcej i kupić coś od innego producenta.', '2025-03-29 17:52:01'),
(315, 64, 43, 4, 'Produkt bardzo mi się podoba, najwyższej jakości materiał i super dopasowanie, jedyne co - dostarczanie trochę dłużej niż oczekiwałem, ale zdecydowanie warto. Polecam każdemu!', '2025-03-18 17:52:01'),
(316, 116, 66, 5, 'Super jakość, dokładnie jak na zdjęciu! Szybka dostawa i przemiła obsługa - na pewno będę tu znowu robić zakupy. Polecam każdemu! ⭐⭐⭐⭐⭐', '2025-04-03 21:02:55'),
(317, 1, 81, 5, 'Świetny produkt, dokładnie taki jak na zdjęciach i bardzo dobrej jakości - polecam! Szybka dostawa i super obsługa sklepu, na pewno będę tu jeszcze kupować.', '2025-03-23 16:37:43'),
(318, 108, 42, 4, 'Produkt przyszedł szybko i dobrze zapakowany, naprawdę się podoba! Jedynym minusem jest to, że kolorystyka na zdjęciach różni się od rzeczywistości, ale ogólnie jestem zadowolony i polecam.', '2025-03-21 18:03:53'),
(319, 200, 42, 4, 'Produkt doskonały, dokładnie taki jak na zdjęciach – solidny, ładnie wykonany i szybka dostawa. Jestem bardzo zadowolona z zakupu, jedynym minusem jest brak bardziej szczegółowej instrukcji obsługi, ale dla mnie to niewielka wada.', '2025-04-01 18:03:53'),
(320, 188, 15, 5, 'Jestem zachwycony tym produktem! Jakość jest niezawodna, dostarczenie było szybkie, a cena całkowicie sprawiedliwa - na pewno polecam wszystkim i zamówię jeszcze raz!', '2025-03-27 10:24:44'),
(321, 27, 15, 4, 'Bardzo zadowolony z zakupu - produkt jest dokładnie taki, jak na zdjęciach, dobrej jakości i przyszedł szybko. Jedynym minusem jest brak instrukcji po polsku, ale ogólnie polecam, warto dla tej ceny!', '2025-03-16 10:24:44'),
(322, 27, 61, 4, 'Świetny produkt, dobrze zapakowany i przyszedł dokładnie tak jak opisano. Polecam, jedyna mała wada to nieco dłuża dostawa, ale jakość przekonuje mnie, że czekało się warto!', '2025-03-19 14:12:33'),
(323, 9, 12, 4, 'Produkt jest naprawdę solidny i dokładnie taki, jaki była opisany na stronie - szybko przyszedł i dobrze zapakowany. Jedynym minusem jest to, że opakowanie mogłoby być bardziej ekologiczne, ale za taką cenę to świetny zakup i zdecydowanie polecam!', '2025-04-04 20:44:47'),
(324, 1, 9, 4, 'Bardzo zadowolony z zakupu, produkt jest dokładnie taki jak na zdjęciach i świetnie się sprawdza w codziennym użytkowaniu. Jedynym minusem jest opakowanie, które mogłoby być lepiej zabezpieczone, ale sam przedmiot to naprawdę solidna rzecz.', '2025-03-21 21:53:32'),
(325, 46, 9, 4, 'Świetny produkt, dokładnie taki jak na zdjęciach – solidna jakość i szybka dostawa. Jedyna mała wada to brak instrukcji po polsku, ale ogólnie jestem bardzo zadowolony/zadowolona i wciąż polecę to innym!', '2025-04-11 21:53:32'),
(326, 29, 9, 2, 'Produkt nie spełnił moich oczekiwań - materiał okazał się słabej jakości, a po tygodniu noszenia zaczął się sypać. Za taką cenę można dostać coś dużo lepszego w innym sklepie.', '2025-03-26 21:53:32'),
(327, 107, 72, 5, 'Absolutnie fantastyczny produkt, przekonałem się o tym na własnej skórze! Polecam każdemu, jakość jest na najwyższym poziomie, a cena całkowicie uzasadniona - bez wahania kupuję znowu.', '2025-04-07 19:29:45'),
(328, 26, 72, 4, 'Świetny produkt, dokładnie taki, jaki się spodziewałem – dobra jakość, szybka dostawa. Jedynym minusem są niezbyt precyzyjne instrukcje, ale ogólnie polecam!', '2025-04-08 19:29:45'),
(329, 152, 69, 4, 'Produkt na wysoki poziomie - dobrze zapakowany, przyszedł szybko i dokładnie taki jak na zdjęciach. Jedynym minusem jest trochę wyższa cena, ale jakość rzeczywiście warta swojego pieniędzy, polecam!', '2025-04-15 12:32:08'),
(330, 68, 52, 3, 'Produkt jest porządkowy, ale jego cena nie do końca się sprawdza. Funkcjonuje jak powinien, choć liczyłem na lepszą jakość za takie pieniądze.', '2025-04-11 15:24:54'),
(331, 190, 1, 3, 'dasd', '2026-04-21 20:42:10'),
(332, 145, 1, 5, 'Super git clanker', '2026-04-21 20:48:49'),
(333, 4, 1, 3, 'SUper Michalki', '2026-04-21 22:29:10');
