--
-- Struktura widoku `avalible_products`
--
DROP TABLE IF EXISTS `avalible_products`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `avalible_products`  AS SELECT `p`.`id` AS `id`, `p`.`name` AS `name`, `p`.`sku` AS `sku`, `p`.`description` AS `description`, `p`.`price` AS `price`, `p`.`weight` AS `weight`, `p`.`category_id` AS `category_id`, `p`.`active` AS `active`, `p`.`image` AS `image`, `p`.`created_at` AS `created_at`, round(avg(`pr`.`rating`),2) AS `rating`, count(`pr`.`rating`) AS `rating_count`, `pc`.`name` AS `category_name` FROM ((`products` `p` left join `product_ratings` `pr` on(`p`.`id` = `pr`.`product_id`)) left join `product_categories` `pc` on(`p`.`category_id` = `pc`.`id`)) GROUP BY `p`.`id`, `p`.`name` ;

