-- Struktura widoku `user_cart`
--
DROP TABLE IF EXISTS `user_cart`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `user_cart`  AS SELECT `c`.`id` AS `id`, `c`.`user_id` AS `user_id`, `c`.`product_id` AS `product_id`, `c`.`quantity` AS `quantity`, `p`.`name` AS `name`, `p`.`price` AS `price`, `p`.`sku` AS `sku` FROM (`cart` `c` join `products` `p` on(`c`.`product_id` = `p`.`id`)) ;

